local AUTOSAVE = ROOT .. "/autosave_v2.json"

local function writeAsset(name, b64)
    local ok, asset = pcall(function()
        local path = ROOT .. "/icons/" .. name .. ".png"
        local decode = (crypt and crypt.base64decode) or base64_decode or (base64 and base64.decode)
        writefile(path, decode(b64))
        return getcustomasset(path)
    end)
    return ok and asset or ""
end
local iconCache = {}
local function icon(name)
    if not iconCache[name] then iconCache[name] = writeAsset(name, ICONS[name]) end
    return iconCache[name]
end
local crownAsset
local function crownImage()
    if not crownAsset then crownAsset = writeAsset("crown", CROWN_B64) end
    return crownAsset
end
