local F_SEMI = Font.new(FONT_PATH, Enum.FontWeight.SemiBold)

local function new(class, props, parent)
    local o = Instance.new(class)
    for k, v in pairs(props) do o[k] = v end
    o.Parent = parent
    return o
end

local function label(parent, text, props)
    props = props or {}
    return new("TextLabel", {
        BackgroundTransparency = 1, Text = text, FontFace = props.Bold and F_BOLD or (props.Semi and F_SEMI or F_REG),
        TextSize = props.TextSize or 12, TextColor3 = props.Color or T.text,
        TextXAlignment = props.Align or Enum.TextXAlignment.Left,
        Size = props.Size or UDim2.fromScale(1, 1), Position = props.Position or UDim2.new(),
        AnchorPoint = props.AnchorPoint or Vector2.zero, TextTruncate = Enum.TextTruncate.AtEnd,
    }, parent)
end

local function tween(inst, props, t, style, dir)
    local tw = TweenService:Create(inst, TweenInfo.new(t or 0.16, style or Enum.EasingStyle.Quint, dir or Enum.EasingDirection.Out), props)
    tw:Play()
    return tw
end
local function corner(inst, r) return new("UICorner", { CornerRadius = UDim.new(0, r) }, inst) end

local function pretty(name) return (tostring(name):gsub("(%l)(%u)", "%1 %2")) end
local function rand(a, b) return a + (b - a) * math.random() end

local function ident() pcall(setthreadidentity, 8) end

local function guard(fn)
    return function(...)
        local prev = 2
        pcall(function() prev = getthreadidentity() end)
        local ok, err = pcall(fn, ...)
        pcall(setthreadidentity, prev)
        if not ok then warn("[Prestige] hook error: " .. tostring(err)) end
    end
end

