    AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, -80), Size = UDim2.fromOffset(300, 34),
    BackgroundColor3 = T.header, BorderSizePixel = 0, Visible = false, ZIndex = 20,
}, hud)
corner(toast, 8)
new("UIStroke", { Color = T.stroke }, toast)
local toastBar = new("Frame", { Size = UDim2.new(0, 3, 1, -12), Position = UDim2.fromOffset(8, 6), BackgroundColor3 = T.accent, BorderSizePixel = 0, ZIndex = 21 }, toast)
corner(toastBar, 2)
local toastText = label(toast, "", { Semi = true, Color = T.bright, Position = UDim2.fromOffset(20, 0), Size = UDim2.new(1, -28, 1, 0) })
toastText.ZIndex = 21
local toastId = 0
local function notify(msg)
    ident()
    toastId += 1
    local id = toastId
    toastText.Text = msg
    toastBar.BackgroundColor3 = T.accent
    toast.Visible = true
    toast.Position = UDim2.new(0.5, 0, 1, -64)
    tween(toast, { Position = UDim2.new(0.5, 0, 1, -80) }, 0.28)
    task.delay(2.4, function()
        if id == toastId then
            tween(toast, { Position = UDim2.new(0.5, 0, 1, -64) }, 0.22)
            task.wait(0.22)
            if id == toastId then toast.Visible = false end
        end
    end)
end

local function onAccent(fn) table.insert(Hub.accentSubs, fn); fn() end
local function setAccent(c)
    T.accent = c
    Hub.listDirty = true
    for _, fn in ipairs(Hub.accentSubs) do pcall(fn) end
end

local dirtyId = 0
local collect
local function dirty()
    dirtyId += 1
    local id = dirtyId
    task.delay(1, function()
        if id == dirtyId and Hub.alive then
            pcall(function() writefile(AUTOSAVE, HttpService:JSONEncode(collect())) end)
        end
    end)
end

local listening
local function keyName(input)
    if input.UserInputType == Enum.UserInputType.Keyboard then return input.KeyCode.Name end
    if input.UserInputType == Enum.UserInputType.MouseButton2 or input.UserInputType == Enum.UserInputType.MouseButton3 then
        return input.UserInputType.Name
    end
end
local function listen(cb) listening = cb end

