Hub.listDirty = true
local function setEnabled(mod, v)
    v = v == true
    if mod.enabled == v then return end
    mod.enabled = v
    mod.render()
    if mod.def.onToggle then pcall(mod.def.onToggle, mod, v) end
    if Hub.moduleToast then pcall(Hub.moduleToast, mod, v) end
    if not v then
        if Hub.Core then Hub.Core.release(mod) end
        mod.rt = {}
    end
    Hub.listDirty = true
end
Hub.setEnabled = setEnabled
local newPanel, newModule, addBind, addCheck, addSlider, addMode, addText
local UI = { winOff = Vector2.zero, cat = {}, catList = {}, gen = {}, genList = {} }
do
    local TH = { idx = 1, c = V3THEMES[1].c }
    UI.TH = TH
    function TH.col(k) local v = TH.c[k - 3]; return Color3.fromRGB(v[1], v[2], v[3]), v[4] / 255 end

    local binds = {}
    local function paintOne(b, t)
        pcall(function()
            local c, a = b.fn()
            local props
            if b.kind == "bg" then props = { BackgroundColor3 = c, BackgroundTransparency = 1 - a }
            elseif b.kind == "txt" then props = { TextColor3 = c, TextTransparency = 1 - a }
            elseif b.kind == "str" then props = { Color = c, Transparency = 1 - a }
            else props = { ImageColor3 = c, ImageTransparency = 1 - a } end
            if t and t > 0 then tween(b.inst, props, t) else for k, v in pairs(props) do b.inst[k] = v end end
        end)
    end
    local function B(inst, kind, fn)
        local b = { inst = inst, kind = kind, fn = fn }
        binds[#binds + 1] = b
        paintOne(b, 0)
        return function(t) paintOne(b, t == nil and 0.14 or t) end
    end
    local function R(inst, kind, slot, mul) return B(inst, kind, function() local c, a = TH.col(slot); return c, a * (mul or 1) end) end
    local function mixc(c1, a1, c2, a2, t) return c1:Lerp(c2, t), a1 + (a2 - a1) * t end
    UI.B, UI.R, UI.mixc = B, R, mixc
    function TH.set(i)
        TH.idx = i
        TH.c = V3THEMES[i].c
        for _, b in ipairs(binds) do paintOne(b, 0.25) end
        if UI.onTheme then pcall(UI.onTheme) end
    end

    local ic = {}
    for k, v in pairs(V3ICONS) do ic[k] = writeAsset("v3_" .. k, v) end
    UI.ic = ic
    local chevAsset = icon("chevron-down")
    local F_SERIF = Font.new("rbxasset://fonts/families/Merriweather.json", Enum.FontWeight.Regular, Enum.FontStyle.Italic)
    UI.F_SERIF = F_SERIF

    local function T_(parent, text, o)
        o = o or {}
        local l = new("TextLabel", {
            BackgroundTransparency = 1, Text = text, FontFace = o.font or F_REG, TextSize = o.size or 14,
            TextXAlignment = o.ax or Enum.TextXAlignment.Left, TextYAlignment = o.ay or Enum.TextYAlignment.Center,
            AnchorPoint = o.anchor or Vector2.zero, Position = o.pos or UDim2.fromOffset(o.x or 0, o.y or 0),
            Size = o.sz or UDim2.fromOffset(o.w or 200, o.h or 20), TextWrapped = o.wrap or false,
            TextTruncate = o.trunc and Enum.TextTruncate.AtEnd or Enum.TextTruncate.None, ZIndex = o.z or 1,
            RichText = o.rich or false, Active = false,
        }, parent)
        if o.slot then R(l, "txt", o.slot, o.mul) end
        return l
    end
    UI.T = T_

    local function rectF(parent, x, y, w, h, r, fillSlot, strokeSlot, o)
        o = o or {}
        local f = new("Frame", { Position = o.pos or UDim2.fromOffset(x, y), Size = o.sz or UDim2.fromOffset(w, h), AnchorPoint = o.anchor or Vector2.zero, BorderSizePixel = 0, ZIndex = o.z or 1 }, parent)
        if r and r > 0 then corner(f, r) end
        if fillSlot then R(f, "bg", fillSlot, o.fmul) else f.BackgroundTransparency = 1 end
        local st
        if strokeSlot then st = new("UIStroke", { Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, f); R(st, "str", strokeSlot, o.smul) end
        return f, st
    end
    UI.rectF = rectF

    local function hit(parent, z)
        return new("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, ZIndex = z or 5 }, parent)
    end
    UI.hit = hit

    local activeDrag
    connect(UIS.InputChanged, function(i)
        if activeDrag and i.UserInputType == Enum.UserInputType.MouseMovement then activeDrag() end
    end)
    connect(UIS.InputEnded, function(i)
        if activeDrag and i.UserInputType == Enum.UserInputType.MouseButton1 then activeDrag = nil; dirty() end
    end)
    function UI.setDrag(fn) activeDrag = fn end

    local function pillSwitch(parent, pos, anchor, h, getOn, onClick, z)
        local track = new("Frame", { Size = UDim2.fromOffset(44, h), AnchorPoint = anchor, Position = pos, BorderSizePixel = 0, ZIndex = z or 6 }, parent)
        corner(track, h / 2)
        local glow = new("Frame", { Size = UDim2.new(1, 4, 1, 4), Position = UDim2.fromOffset(-2, -2), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = (z or 6) - 1 }, track)
        corner(glow, h / 2 + 2)
        local st = new("UIStroke", { Thickness = 1 }, track)
        local knob = new("Frame", { Size = UDim2.fromOffset(16, 16), AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, ZIndex = (z or 6) + 1 }, track)
        corner(knob, 8)
        local hot = false
        local repaintTrack = B(track, "bg", function()
            local on = getOn()
            local c, a = TH.col(on and 18 or 17)
            if hot then c = Color3.new(math.min(c.R * 1.15, 1), math.min(c.G * 1.15, 1), math.min(c.B * 1.15, 1)) end
            return c, a
        end)
        local repaintGlow = B(glow, "bg", function() local c, a = TH.col(11); return c, getOn() and a * 0.3 or 0 end)
        R(st, "str", 14)
        local function place(animate)
            local on = getOn()
            local pos2 = UDim2.new(0, on and 32 or 12, 0.5, 0)
            if animate then tween(knob, { Position = pos2 }, 0.26, Enum.EasingStyle.Back) else knob.Position = pos2 end
        end
        place(false)
        local btn = hit(track, (z or 6) + 2)
        btn.MouseEnter:Connect(function() hot = true; repaintTrack() end)
        btn.MouseLeave:Connect(function() hot = false; repaintTrack() end)
        btn.MouseButton1Click:Connect(function() if onClick then onClick() end end)
        return { refresh = function() repaintTrack(); repaintGlow(); place(true) end, hit = btn, track = track }
    end
    UI.pillSwitch = pillSwitch

    local win = new("CanvasGroup", {
        Name = "Window", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
        Size = UDim2.fromOffset(1100, 700), BorderSizePixel = 0,
    }, root)
    corner(win, 25)
    B(win, "bg", function() local c, a = TH.col(4); return c, a * math.clamp(Hub.alpha, 0.3, 1) end)
    UI.window, UI.win = win, win
    function UI.winPos(dy) return UDim2.new(0.5, UI.winOff.X, 0.5, UI.winOff.Y + (dy or 0)) end

    UI.orbs = {}
    for i, o in ipairs({ { 33, 520 }, { 34, 460 }, { 35, 310 } }) do
        local im = new("ImageLabel", { BackgroundTransparency = 1, Image = ic.glow, AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(o[2] * 2, o[2] * 2), ZIndex = 0 }, win)
        B(im, "img", function() local c, a = TH.col(o[1]); return c, math.min(0.95, a * (i == 2 and 1.5 or 1)) end)
        UI.orbs[i] = im
    end

    local dragH = new("Frame", { Size = UDim2.fromOffset(1100, 92), BackgroundTransparency = 1, Active = true, ZIndex = 1 }, win)
    do
        local dragging, ds, so
        connect(dragH.InputBegan, function(i)
            if i.UserInputType == Enum.UserInputType.MouseButton1 then dragging, ds, so = true, UIS:GetMouseLocation(), UI.winOff end
        end)
        connect(UIS.InputChanged, function(i)
            if dragging and i.UserInputType == Enum.UserInputType.MouseMovement then
                local vp = workspace.CurrentCamera.ViewportSize / uiScale.Scale
            local o = so + (UIS:GetMouseLocation() - ds) / uiScale.Scale
            UI.winOff = Vector2.new(math.clamp(o.X, -vp.X / 2 - 200, vp.X / 2 + 200), math.clamp(o.Y, -vp.Y / 2 + 40, vp.Y / 2 + 100))
                win.Position = UI.winPos(0)
            end
        end)
        connect(UIS.InputEnded, function(i) if dragging and i.UserInputType == Enum.UserInputType.MouseButton1 then dragging = false end end)
    end

    local sideW = 230
    local side = rectF(win, 14, 14, sideW, 672, 16, 23, 25, { z = 2 })
    local logo = new("ImageLabel", { BackgroundTransparency = 1, Image = ic.logo, Position = UDim2.fromOffset(20, 15), Size = UDim2.fromOffset(46, 46), ZIndex = 4 }, win)
    R(logo, "img", 9)
    T_(win, "Prestige", { x = 70, y = 22, w = 100, h = 30, size = 24, font = F_SEMI, slot = 12, z = 4 })
    UI.clientLbl = T_(win, "Client", { x = 148, y = 22, w = 90, h = 30, size = 24, font = F_SERIF, slot = 27, z = 4 })
    UI.betaLabel = T_(win, "BETA RELEASE " .. Hub.version, { x = 70, y = 51, w = 160, h = 16, size = 12, slot = 30, z = 4 })
    T_(win, "MODULES", { x = 38, y = 95, w = 150, h = 17, size = 12, font = F_SEMI, slot = 30, z = 4 })
    T_(win, "GENERAL", { x = 38, y = 394, w = 150, h = 18, size = 12, font = F_SEMI, slot = 30, z = 4 })

    do
        local x0, x1 = sideW * 0.12 + 14, sideW * 0.88 + 14
        local line = new("Frame", { Position = UDim2.fromOffset(x0, 380), Size = UDim2.fromOffset(x1 - x0, 1), BorderSizePixel = 0, ZIndex = 4 }, win)
        R(line, "bg", 25)
        new("UIGradient", { Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.5, 0), NumberSequenceKeypoint.new(1, 1) }) }, line)
    end

    local function navEntry(name, iconKey, y, iconSize, iconOff, withCount)
        local e = { name = name, sel = false, hov = false }
        local row = new("Frame", { Position = UDim2.fromOffset(26, y), Size = UDim2.fromOffset(sideW - 24, 36), BorderSizePixel = 0, ZIndex = 4 }, win)
        corner(row, 10)
        local st = new("UIStroke", { Thickness = 1 }, row)
        e.row = row
        e.repFill = B(row, "bg", function()
            local c1, a1 = TH.col(10)
            local c2, a2 = TH.col(29)
            local k = e.sel and 1 or 0
            local c, a = mixc(c1, a1, c2, a2, k)
            return c, a * math.max(e.hov and 0.55 or 0, k)
        end)
        e.repStroke = B(st, "str", function() local c, a = TH.col(25); return c, e.sel and a or 0 end)
        local img = new("ImageLabel", { BackgroundTransparency = 1, Image = ic[iconKey], Position = UDim2.fromOffset(iconOff, iconOff), Size = UDim2.fromOffset(iconSize, iconSize), ZIndex = 5 }, row)
        e.repIcon = B(img, "img", function() return TH.col((e.sel or e.hov) and 9 or 13) end)
        local lab = T_(row, name, { x = 37, y = 9, w = 120, h = 18, size = 17, z = 5 })
        e.repLabel = B(lab, "txt", function()
            local c1, a1 = TH.col(13)
            local c2, a2 = TH.col(12)
            return mixc(c1, a1, c2, a2, (e.sel or e.hov) and 1 or 0)
        end)
        if withCount then
            e.count = T_(row, "0", { pos = UDim2.new(1, -14, 0, 9), anchor = Vector2.new(1, 0), w = 40, h = 18, size = 14, ax = Enum.TextXAlignment.Right, z = 5 })
            e.repCount = B(e.count, "txt", function() return TH.col((e.sel or e.hov) and 13 or 30) end)
        end
        local btn = hit(row, 8)
        btn.MouseEnter:Connect(function()
            e.hov = true
            e.repFill()
            e.repIcon()
            e.repLabel()
            if e.repCount then e.repCount() end
            tween(row, { Position = UDim2.fromOffset(29, y) }, 0.12)
        end)
        btn.MouseLeave:Connect(function()
            e.hov = false
            e.repFill()
            e.repIcon()
            e.repLabel()
            if e.repCount then e.repCount() end
            tween(row, { Position = UDim2.fromOffset(26, y) }, 0.14)
        end)
        e.btn = btn
        function e.setSel(v)
            e.sel = v
            e.repFill()
            e.repStroke()
            e.repIcon()
            e.repLabel()
            if e.repCount then e.repCount() end
        end
        return e
    end

    UI.pages = {}
    function UI.go(page)
        if UI.active == page then return end
        local old = UI.active
        UI.active = page
        if old and old.resetDetail then old.resetDetail() end
        if UI.closeDropdown then UI.closeDropdown() end
        for _, p in ipairs(UI.pages) do
            p.nav.setSel(p == page)
            if p ~= page and p.frame.Visible then
                tween(p.frame, { GroupTransparency = 1 }, 0.12)
                task.delay(0.13, function() if UI.active ~= p then p.frame.Visible = false end end)
            end
        end
        page.frame.Visible = true
        page.frame.GroupTransparency = 1
        page.frame.Position = UDim2.fromOffset(0, 14)
        tween(page.frame, { GroupTransparency = 0, Position = UDim2.fromOffset(0, 0) }, 0.32)
        if UI.search then UI.search.setVisible(page.kind == "cat") end
        if page.kind == "cat" and UI.stagger then UI.stagger(page) end
        if page.onShow then pcall(page.onShow) end
        if UI.closePopup then UI.closePopup() end
    end

    local function addPageEntry(def)
        local nav = navEntry(def.name, def.icon, def.y, def.iconSize, def.iconOff, def.kind == "cat")
        local frame = new("CanvasGroup", { Size = UDim2.fromOffset(1100, 700), BackgroundTransparency = 1, Visible = false, ZIndex = 3 }, win)
        local page = { name = def.name, kind = def.kind, frame = frame, nav = nav, mods = {}, count = 0 }
        nav.btn.MouseButton1Click:Connect(function() UI.go(page) end)
        table.insert(UI.pages, page)
        return page
    end

    local CATS = { { "Combat", "combat" }, { "Mace", "mace" }, { "Misc", "misc" }, { "Movement", "movement" }, { "Spear", "spear" }, { "Visual", "visual" } }
    local GEN = { { "Settings", "menu" }, { "Theme", "themes" }, { "Cosmetics", "chest" }, { "Configs", "configs" }, { "Socials", "social" }, { "Keybinds", "keyboard" } }

    local function textW(s, size, font)
        local ok, v = pcall(function()
            local p = Instance.new("GetTextBoundsParams")
            p.Text, p.Font, p.Size, p.Width = s, font or F_REG, size, 2000
            return game:GetService("TextService"):GetTextBoundsAsync(p).X
        end)
        return ok and v or #s * size * 0.55
    end
    UI.textW = textW
    UI.clientLbl.Position = UDim2.fromOffset(70 + textW("Prestige", 24, F_SEMI) + 5, 22)

    local function buildCat(p)
        local f = p.frame

        local hdr = new("Frame", { Position = UDim2.fromOffset(260, 26), Size = UDim2.fromOffset(480, 44), BackgroundTransparency = 1 }, f)
        new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, SortOrder = Enum.SortOrder.LayoutOrder, VerticalAlignment = Enum.VerticalAlignment.Center }, hdr)
        local t1 = new("TextLabel", { Size = UDim2.fromOffset(0, 44), AutomaticSize = Enum.AutomaticSize.X, BackgroundTransparency = 1, Text = p.name, FontFace = F_SERIF, TextSize = 34, LayoutOrder = 1 }, hdr)
        R(t1, "txt", 27)
        local t2 = new("TextLabel", { Size = UDim2.fromOffset(0, 44), AutomaticSize = Enum.AutomaticSize.X, BackgroundTransparency = 1, Text = " Modules", FontFace = F_SEMI, TextSize = 34, LayoutOrder = 2 }, hdr)
        R(t2, "txt", 12)
        p.sub = T_(f, "0 modules", { x = 260, y = 72, w = 480, h = 20, size = 17, slot = 13 })

        p.filterOn = false
        local bw = textW("Enabled", 17) + 28
        local pill = new("Frame", { Position = UDim2.fromOffset(264, 104), Size = UDim2.fromOffset(bw, 24), BorderSizePixel = 0 }, f)
        corner(pill, 12)
        local pst = new("UIStroke", { Thickness = 1 }, pill)
        local pillHot = false
        local repPill = B(pill, "bg", function()
            local c1, a1 = TH.col(24)
            local c2, a2 = TH.col(29)
            return mixc(c1, a1, c2, a2, math.min(1, (p.filterOn and 1 or 0) + (pillHot and 0.4 or 0)))
        end)
        local repPillS = B(pst, "str", function()
            local c1, a1 = TH.col(14)
            local c2, a2 = TH.col(25)
            return mixc(c1, a1, c2, a2, math.max(p.filterOn and 1 or 0, pillHot and 0.6 or 0))
        end)
        local pillLab = T_(pill, "Enabled", { sz = UDim2.fromScale(1, 1), size = 17, ax = Enum.TextXAlignment.Center })
        local repPillT = B(pillLab, "txt", function()
            local c1, a1 = TH.col(13)
            local c2, a2 = TH.col(12)
            return mixc(c1, a1, c2, a2, (p.filterOn or pillHot) and 1 or 0)
        end)
        local pillBtn = hit(pill, 6)
        pillBtn.MouseEnter:Connect(function() pillHot = true; repPill(); repPillT(); repPillS() end)
        pillBtn.MouseLeave:Connect(function() pillHot = false; repPill(); repPillT(); repPillS() end)
        pillBtn.MouseButton1Click:Connect(function()
            if p.openMod then return end
            p.filterOn = not p.filterOn
            repPill()
            repPillT()
            repPillS()
            p.applyFilter()
        end)
        p.pill = pill

        local back = new("Frame", { Position = UDim2.fromOffset(264, 104), Size = UDim2.fromOffset(78, 24), BorderSizePixel = 0, Visible = false, ZIndex = 8 }, f)
        corner(back, 12)
        local bst = new("UIStroke", { Thickness = 1 }, back)
        local backHot = false
        local repBack = B(back, "bg", function() local c1, a1 = TH.col(24); local c2, a2 = TH.col(29); return mixc(c1, a1, c2, a2, backHot and 0.4 or 0) end)
        local repBackS = B(bst, "str", function() local c1, a1 = TH.col(14); local c2, a2 = TH.col(25); return mixc(c1, a1, c2, a2, backHot and 0.6 or 0) end)
        local chev = new("ImageLabel", { BackgroundTransparency = 1, Image = chevAsset, Size = UDim2.fromOffset(12, 12), Position = UDim2.fromOffset(12, 6), Rotation = 90, ZIndex = 9 }, back)
        B(chev, "img", function() return TH.col(backHot and 12 or 13) end)
        local backLab = T_(back, "Back", { x = 28, y = 0, w = 44, h = 24, size = 17, z = 9 })
        local repBackT = B(backLab, "txt", function() return TH.col(backHot and 12 or 13) end)
        local backBtn = hit(back, 10)
        backBtn.MouseEnter:Connect(function() backHot = true; repBack(); repBackS(); repBackT() end)
        backBtn.MouseLeave:Connect(function() backHot = false; repBack(); repBackS(); repBackT() end)
        backBtn.MouseButton1Click:Connect(function() p.closeDetail() end)
        p.back = back

        local vs = new("Frame", { Position = UDim2.fromOffset(998, 104), Size = UDim2.fromOffset(68, 24), BorderSizePixel = 0 }, f)
        corner(vs, 12)
        R(vs, "bg", 24)
        local vst = new("UIStroke", { Thickness = 1 }, vs)
        R(vst, "str", 14)
        local sel = new("Frame", { Position = UDim2.fromOffset(2, 2), Size = UDim2.fromOffset(30, 20), BorderSizePixel = 0 }, vs)
        corner(sel, 10)
        R(sel, "bg", 29)
        local function seg(i)
            local cx = 34 * (i - 1) + 17
            local g = new("Frame", { Position = UDim2.fromOffset(34 * (i - 1), 0), Size = UDim2.fromOffset(34, 24), BackgroundTransparency = 1 }, vs)
            local parts = {}
            if i == 1 then
                for k, yy in ipairs({ 6, 11, 16 }) do parts[k] = new("Frame", { Position = UDim2.fromOffset(11, yy), Size = UDim2.fromOffset(12, 2), BorderSizePixel = 0 }, g) end
            else
                local pos = { { 11, 6 }, { 18, 6 }, { 11, 13 }, { 18, 13 } }
                for k, pp in ipairs(pos) do parts[k] = new("Frame", { Position = UDim2.fromOffset(pp[1], pp[2]), Size = UDim2.fromOffset(5, 5), BorderSizePixel = 0 }, g); corner(parts[k], 1) end
            end
            local hot = false
            local reps = {}
            for k, part in ipairs(parts) do reps[k] = B(part, "bg", function() return TH.col((p.grid == (i == 2)) or hot and 12 or 13) end) end
            local b = hit(g, 6)
            b.MouseEnter:Connect(function() hot = true; for _, r in ipairs(reps) do r() end end)
            b.MouseLeave:Connect(function() hot = false; for _, r in ipairs(reps) do r() end end)
            b.MouseButton1Click:Connect(function() p.setGrid(i == 2) end)
            return reps
        end
        local segReps = { seg(1), seg(2) }

        local group = new("CanvasGroup", { Position = UDim2.fromOffset(230, 147), Size = UDim2.fromOffset(870, 538), BackgroundTransparency = 1 }, f)
        p.group = group
        local scroll = new("ScrollingFrame", {
            Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 3, CanvasSize = UDim2.new(),
            AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollingDirection = Enum.ScrollingDirection.Y,
        }, group)
        scroll.ScrollBarImageColor3 = Color3.fromRGB(120, 120, 130)
        new("UIPadding", { PaddingLeft = UDim.new(0, 30), PaddingRight = UDim.new(0, 30), PaddingTop = UDim.new(0, 6), PaddingBottom = UDim.new(0, 24) }, scroll)
        p.layout = new("UIGridLayout", { CellSize = UDim2.fromOffset(810, 75), CellPadding = UDim2.fromOffset(10, 10), SortOrder = Enum.SortOrder.LayoutOrder }, scroll)
        p.scroll = scroll

        local det = new("CanvasGroup", { Position = UDim2.fromOffset(300, 152), Size = UDim2.fromOffset(810, 533), Visible = false, GroupTransparency = 1, ZIndex = 6 }, f)
        corner(det, 12)
        R(det, "bg", 23, 1.4)
        local dst = new("UIStroke", { Thickness = 1 }, det)
        R(dst, "str", 15)
        p.det = det
        p.detTitle = T_(det, "", { x = 20, y = 18, w = 700, h = 30, size = 20, font = F_SEMI, slot = 12, z = 7 })
        p.detDesc = T_(det, "", { x = 20, y = 52, w = 770, h = 38, size = 14, slot = 30, wrap = true, ay = Enum.TextYAlignment.Top, z = 7 })
        new("Frame", { Position = UDim2.fromOffset(20, 92), Size = UDim2.fromOffset(770, 2), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.7, BorderSizePixel = 0, ZIndex = 7 }, det)
        p.detSwitch = pillSwitch(det, UDim2.new(1, -20, 0, 21), Vector2.new(1, 0), 24,
            function() return p.openMod and p.openMod.enabled end,
            function() if p.openMod then Hub.setEnabled(p.openMod, not p.openMod.enabled); dirty() end end, 8)
        p.detScroll = new("ScrollingFrame", {
            Position = UDim2.fromOffset(0, 100), Size = UDim2.fromOffset(810, 433), BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 3,
            CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ZIndex = 7, ScrollBarImageColor3 = Color3.fromRGB(120, 120, 130),
        }, det)
        new("UIPadding", { PaddingTop = UDim.new(0, 8), PaddingBottom = UDim.new(0, 20) }, p.detScroll)

        function p.refreshCount()
            local n, shown = 0, 0
            for _, m in ipairs(p.mods) do if m.enabled then n += 1 end; if m.card.Visible then shown += 1 end end
            p.sub.Text = string.format("%d modules \xC2\xB7 %d enabled", #p.mods, n)
        end
        function p.applyFilter()
            local q = (UI.search and UI.search.text() or ""):lower()
            local idx = 0
            for _, m in ipairs(p.mods) do
                local ok = (not p.filterOn or m.enabled) and (q == "" or m.name:lower():find(q, 1, true) ~= nil or (m.desc or ""):lower():find(q, 1, true) ~= nil)
                m.card.Visible = ok
            end
        end
        function p.setGrid(g)
            if p.grid == g then return end
            p.grid = g
            tween(sel, { Position = UDim2.fromOffset(g and 36 or 2, 2) }, 0.22)
            for _, r in ipairs(segReps[1]) do r() end
            for _, r in ipairs(segReps[2]) do r() end
            local w = g and math.floor((810 - 20) / 3) or 810
            p.layout.CellSize = UDim2.fromOffset(w, g and 120 or 75)
            for _, m in ipairs(p.mods) do if m.applyLayout then m.applyLayout(g) end end
        end
        function p.openDetail(mod)
            if p.openMod == mod then return end
            if p.openMod then p.openMod.dd.Visible = false end
            p.openMod = mod
            p.detTitle.Text = mod.name
            p.detDesc.Text = mod.desc or ""
            mod.dd.Visible = true
            p.detScroll.CanvasPosition = Vector2.zero
            p.detSwitch.refresh()
            det.Visible = true
            det.Position = UDim2.fromOffset(300, 152)
            tween(det, { GroupTransparency = 0, Position = UDim2.fromOffset(260, 152) }, 0.34, Enum.EasingStyle.Quint)
            tween(group, { GroupTransparency = 1, Position = UDim2.fromOffset(190, 147) }, 0.26)
            task.delay(0.28, function() if p.openMod then group.Visible = false end end)
            pill.Visible = false
            back.Visible = true
        end
        function p.resetDetail()
            if not p.openMod then return end
            p.openMod.dd.Visible = false
            p.openMod = nil
            det.Visible, det.GroupTransparency, det.Position = false, 1, UDim2.fromOffset(300, 152)
            group.Visible, group.GroupTransparency, group.Position = true, 0, UDim2.fromOffset(230, 147)
            back.Visible, pill.Visible = false, true
        end
        function p.closeDetail()
            if not p.openMod then return end
            local m = p.openMod
            p.openMod = nil
            group.Visible = true
            tween(det, { GroupTransparency = 1, Position = UDim2.fromOffset(300, 152) }, 0.24)
            tween(group, { GroupTransparency = 0, Position = UDim2.fromOffset(230, 147) }, 0.3, Enum.EasingStyle.Quint)
            task.delay(0.26, function() if not p.openMod then det.Visible = false; m.dd.Visible = false end end)
            back.Visible = false
            pill.Visible = true
        end
        p.setGrid(false)
        p.grid = false
        p.refreshCount()
    end

    for i, c in ipairs(CATS) do
        local p = addPageEntry({ name = c[1], icon = c[2], y = 126 + (i - 1) * 40, iconSize = 18, iconOff = 9, kind = "cat" })
        UI.cat[c[1]] = p
        table.insert(UI.catList, p)
        buildCat(p)
        Hub.panels[c[1]] = p
    end
    for i, g in ipairs(GEN) do
        local p = addPageEntry({ name = g[1], icon = g[2], y = 420 + (i - 1) * 40, iconSize = 20, iconOff = 8, kind = "gen" })
        UI.gen[g[1]] = p
        table.insert(UI.genList, p)
        Hub.panels[g[1]] = p
    end
    newPanel = function(title) return UI.cat[title] or UI.gen[title] end

    do
        local sb = rectF(win, 760, 42, 310, 36, 8, 24, 14, { z = 5 })
        local focus = false
        local sst = sb:FindFirstChildOfClass("UIStroke")
        local repS = B(sst, "str", function() local c1, a1 = TH.col(14); local c2, a2 = TH.col(9); return mixc(c1, a1, c2, a2, focus and 0.6 or 0) end)

        local ring = new("Frame", { Position = UDim2.fromOffset(16, 11), Size = UDim2.fromOffset(12, 12), BackgroundTransparency = 1, ZIndex = 6 }, sb)
        corner(ring, 6)
        local rst = new("UIStroke", { Thickness = 1.5 }, ring)
        local handle = new("Frame", { Position = UDim2.fromOffset(25, 21), Size = UDim2.fromOffset(6, 1.5), Rotation = 45, BorderSizePixel = 0, ZIndex = 6 }, sb)
        local repIcon = function()
            local c, a = mixc(select(1, TH.col(13)), select(2, TH.col(13)), select(1, TH.col(9)), select(2, TH.col(9)), focus and 0.8 or 0)
            rst.Color, rst.Transparency = c, 1 - a
            handle.BackgroundColor3, handle.BackgroundTransparency = c, 1 - a
        end
        local box = new("TextBox", {
            Position = UDim2.fromOffset(40, 9), Size = UDim2.fromOffset(255, 18), BackgroundTransparency = 1, Text = "", PlaceholderText = "Search modules",
            FontFace = F_REG, TextSize = 17, TextXAlignment = Enum.TextXAlignment.Left, ClearTextOnFocus = false, ZIndex = 6,
        }, sb)
        R(box, "txt", 12)
        local function placeholder() box.PlaceholderColor3 = (TH.col(13)) end
        placeholder()
        box.Focused:Connect(function() focus = true; repS(); repIcon() end)
        box.FocusLost:Connect(function() focus = false; repS(); repIcon() end)
        repIcon()
        UI.onTheme = function() repIcon(); placeholder() end
        local search = { frame = sb }
        function search.text() return box.Text end
        function search.setVisible(v) sb.Visible = v end
        UI.search = search

        local pop = new("Frame", { Position = UDim2.fromOffset(720, 88), Size = UDim2.fromOffset(350, 0), Visible = false, ZIndex = 30, ClipsDescendants = true }, win)
        corner(pop, 10)
        R(pop, "bg", 6)
        local pst = new("UIStroke", { Thickness = 1 }, pop)
        R(pst, "str", 14)
        new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder }, pop)
        new("UIPadding", { PaddingTop = UDim.new(0, 6), PaddingBottom = UDim.new(0, 6), PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6) }, pop)
        local function rebuild()
            for _, c in ipairs(pop:GetChildren()) do if c:IsA("TextButton") then c:Destroy() end end
            local q = box.Text:lower()
            local p = UI.active
            if q == "" then pop.Visible = false; if p and p.kind == "cat" then p.applyFilter() end; return end
            if p and p.kind == "cat" then p.applyFilter() end
            local n = 0
            for _, cp in ipairs(UI.catList) do
                for _, m in ipairs(cp.mods) do
                    if n < 6 and (m.name:lower():find(q, 1, true)) then
                        n += 1
                        local r = new("TextButton", { Size = UDim2.new(1, 0, 0, 38), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, LayoutOrder = n, ZIndex = 31 }, pop)
                        corner(r, 6)
                        local hot = false
                        local rep = B(r, "bg", function() local c, a = TH.col(7); return c, hot and a or 0 end)
                        local nm = T_(r, m.name, { x = 10, y = 3, w = 220, h = 18, size = 17, slot = 12, z = 32 })
                        T_(r, cp.name, { x = 10, y = 21, w = 220, h = 14, size = 12, slot = 30, z = 32 })
                        r.MouseEnter:Connect(function() hot = true; rep() end)
                        r.MouseLeave:Connect(function() hot = false; rep() end)
                        r.MouseButton1Click:Connect(function()
                            box.Text = ""
                            pop.Visible = false
                            UI.go(cp)
                            task.delay(0.1, function() cp.openDetail(m) end)
                        end)
                    end
                end
            end
            pop.Visible = n > 0
            pop.Size = UDim2.fromOffset(350, n * 38 + 12)
        end
        box:GetPropertyChangedSignal("Text"):Connect(rebuild)
        function UI.closePopup() pop.Visible = false; box.Text = "" end
    end

    local DESC = Hub.descriptions or {}
    newModule = function(panel, name, def)
        def = def or {}
        local mod = { name = name, def = def, enabled = false, bind = nil, settings = {}, setters = {}, renders = {}, open = false, rt = {}, hidden = def.hidden, panel = panel, desc = def.desc or (Hub.descriptions and Hub.descriptions[name]) or "" }
        Hub.modules[name] = mod
        table.insert(Hub.order, mod)
        panel.count += 1
        table.insert(panel.mods, mod)
        local cat = panel
        local nav = panel.nav
        if nav.count then nav.count.Text = tostring(#panel.mods) end

        local card = new("CanvasGroup", { BackgroundTransparency = 1, BorderSizePixel = 0, LayoutOrder = panel.count }, panel.scroll)
        local body = new("Frame", { Size = UDim2.fromScale(1, 1), BorderSizePixel = 0 }, card)
        corner(body, 10)
        local bst = new("UIStroke", { Thickness = 1 }, body)
        local hover = false
        local function glowK() return mod.enabled and 1 or 0 end
        local repFill = B(body, "bg", function()
            local sc, sa = TH.col(23)
            local ac = TH.col(9)
            local k = glowK() * 0.07
            return sc:Lerp(ac, k), math.min(1, sa + (hover and 0.04 or 0))
        end)
        local repStroke = B(bst, "str", function() return mixc(select(1, TH.col(14)), select(2, TH.col(14)), select(1, TH.col(15)), select(2, TH.col(15)), math.max(hover and 1 or 0, glowK())) end)
        corner(card, 10)
        local hl = new("Frame", { Position = UDim2.fromOffset(6, 0), Size = UDim2.new(1, -12, 0, 1), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0.93, BorderSizePixel = 0, ZIndex = 2 }, body)
        local bar = new("Frame", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 2, 0.5, 0), Size = UDim2.fromOffset(2, 0), BorderSizePixel = 0, ZIndex = 3 }, body)
        corner(bar, 1)
        R(bar, "bg", 9)
        local barGlow = new("Frame", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, -2, 0.5, 0), Size = UDim2.fromOffset(10, 0), BorderSizePixel = 0, ZIndex = 2 }, body)
        corner(barGlow, 5)
        R(barGlow, "bg", 9, 0.16)

        local nameL = T_(body, name, { font = F_SEMI, size = 20, slot = 12, trunc = true, z = 4, h = 26 })
        local descL = T_(body, mod.desc, { size = 14, slot = 30, trunc = true, z = 4, h = 16 })
        local chev = new("ImageLabel", { BackgroundTransparency = 1, Image = chevAsset, Size = UDim2.fromOffset(12, 12), AnchorPoint = Vector2.new(0.5, 0.5), Rotation = -90, ZIndex = 4 }, body)
        local chevHot = false
        local repChev = B(chev, "img", function() return TH.col(chevHot and 9 or 13) end)

        local sw = pillSwitch(body, UDim2.new(1, -16, 0, 30), Vector2.new(1, 0), 24, function() return mod.enabled end, function()
            Hub.setEnabled(mod, not mod.enabled)
            dirty()
        end, 6)

        function mod.applyLayout(grid, instant)
            local dur = instant and 0 or 0.28
            local function tw(i, props) if instant then for k, v in pairs(props) do i[k] = v end else tween(i, props, dur, Enum.EasingStyle.Quint) end end
            if grid then
                tw(nameL, { Position = UDim2.fromOffset(20, 12), Size = UDim2.new(1, -84, 0, 26) })
                tw(descL, { Position = UDim2.fromOffset(20, 46), Size = UDim2.new(1, -40, 0, 34) })
                descL.TextWrapped = true
                descL.TextTruncate = Enum.TextTruncate.AtEnd
                descL.TextYAlignment = Enum.TextYAlignment.Top
                tw(chev, { Position = UDim2.new(1, -28, 0, 96) })
                tw(sw.track, { Position = UDim2.new(1, -16, 0, 14) })
            else
                tw(nameL, { Position = UDim2.fromOffset(20, 16), Size = UDim2.new(0, 220, 0, 26) })
                tw(descL, { Position = UDim2.fromOffset(20, 44), Size = UDim2.new(1, -160, 0, 16) })
                descL.TextWrapped = false
                descL.TextYAlignment = Enum.TextYAlignment.Center
                tw(chev, { Position = UDim2.new(1, -85, 0, 38) })
                tw(sw.track, { Position = UDim2.new(1, -16, 0, 26) })
            end
            local h = grid and 120 or 75
            bar.Size = UDim2.fromOffset(2, mod.enabled and (h - 24) or 0)
            barGlow.Size = UDim2.fromOffset(10, mod.enabled and (h - 24) or 0)
        end
        mod.applyLayout(false, true)

        mod.render = function()
            local h = panel.grid and 120 or 75
            repFill()
            repStroke()
            sw.refresh()
            panel.detSwitch.refresh()
            tween(bar, { Size = UDim2.fromOffset(2, mod.enabled and (h - 24) or 0) }, 0.3, Enum.EasingStyle.Quint)
            tween(barGlow, { Size = UDim2.fromOffset(10, mod.enabled and (h - 24) or 0) }, 0.3, Enum.EasingStyle.Quint)
            if panel.refreshCount then panel.refreshCount() end
            if panel.applyFilter and panel.filterOn then panel.applyFilter() end
            for _, r in ipairs(mod.renders) do r() end
        end
        mod.updateChip = function() end
        mod.card = card

        local btn = hit(body, 5)
        btn.MouseEnter:Connect(function() hover = true; repFill(); repStroke() end)
        btn.MouseLeave:Connect(function() hover = false; repFill(); repStroke() end)
        btn.MouseButton1Click:Connect(function() panel.openDetail(mod) end)
        local cb = new("TextButton", { AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(30, 30), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, ZIndex = 7 }, body)
        cb.MouseEnter:Connect(function() chevHot = true; repChev() end)
        cb.MouseLeave:Connect(function() chevHot = false; repChev() end)
        cb.MouseButton1Click:Connect(function() panel.openDetail(mod) end)
        local function followChev() cb.Position = chev.Position end
        chev:GetPropertyChangedSignal("Position"):Connect(followChev)
        followChev()
        onAccent(function() end)

        local dd = new("Frame", { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, Visible = false, ZIndex = 8 }, panel.detScroll)
        new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder }, dd)
        mod.dd = dd

        addBind(mod, dd)
        if def.build then def.build(mod, dd) end
        mod.render()

        card.GroupTransparency = 1
        return mod
    end
    UI.stagger = function(p)
        for i, m in ipairs(p.mods) do
            m.card.GroupTransparency = 1
            task.delay(math.min(i * 0.025, 0.5), function() tween(m.card, { GroupTransparency = 0 }, 0.3) end)
        end
    end

    local rowCount = {}
    local function newRow(dd, text)
        local n = (dd:GetAttribute("rows") or 0) + 1
        dd:SetAttribute("rows", n)
        local row = new("Frame", { Size = UDim2.new(1, 0, 0, 54), BackgroundTransparency = 1, LayoutOrder = n, ZIndex = 9 }, dd)
        local sep = new("Frame", { Position = UDim2.new(0, 20, 1, -1), Size = UDim2.new(1, -40, 0, 1), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.65, BorderSizePixel = 0, ZIndex = 9 }, row)
        local ind = new("Frame", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 14, 0.5, 0), Size = UDim2.fromOffset(2, 0), BorderSizePixel = 0, ZIndex = 9 }, row)
        R(ind, "bg", 9, 0.45)
        local lab = T_(row, text, { pos = UDim2.fromOffset(20, 0), sz = UDim2.new(1, -420, 1, 0), size = 20, font = F_SEMI, slot = 12, trunc = true, z = 10 })
        row.MouseEnter:Connect(function() tween(ind, { Size = UDim2.fromOffset(2, 44) }, 0.16) end)
        row.MouseLeave:Connect(function() tween(ind, { Size = UDim2.fromOffset(2, 0) }, 0.2) end)
        return row, lab
    end

    local function box(parent, w, h, pos, anchor)
        local b = new("Frame", { Size = UDim2.fromOffset(w, h), Position = pos, AnchorPoint = anchor or Vector2.new(1, 0.5), BorderSizePixel = 0, ZIndex = 11 }, parent)
        corner(b, 4)
        R(b, "bg", 6)
        local st = new("UIStroke", { Thickness = 1 }, b)
        R(st, "str", 14)
        return b, st
    end

    addBind = function(mod, dd)
        local row = newRow(dd, "Keybind")
        local b, st = box(row, 120, 28, UDim2.new(1, -20, 0.5, 0))
        local val = T_(b, "None", { sz = UDim2.new(1, -16, 1, 0), pos = UDim2.fromOffset(8, 0), size = 14, ax = Enum.TextXAlignment.Center, z = 12, trunc = true })
        local listening = false
        local hot = false
        local repT = B(val, "txt", function() return TH.col(listening and 9 or 12) end)
        local repS = B(st, "str", function() local c1, a1 = TH.col(14); local c2, a2 = TH.col(listening and 16 or 15); return mixc(c1, a1, c2, a2, (listening or hot) and 1 or 0) end)
        local function render()
            val.Text = listening and "Press a key" or (mod.bind and pretty(mod.bind) or "None")
            repT()
            repS()
        end
        local btn = hit(b, 13)
        btn.MouseEnter:Connect(function() hot = true; repS() end)
        btn.MouseLeave:Connect(function() hot = false; repS() end)
        btn.MouseButton1Click:Connect(function()
            listening = true
            render()
            listen(function(name) listening = false; mod.bind = name; render(); dirty() end)
        end)
        btn.MouseButton2Click:Connect(function() mod.bind = nil; listening = false; render(); dirty() end)
        table.insert(mod.renders, render)
        render()
    end

    addCheck = function(mod, dd, key, text, default)
        mod.settings[key] = default
        local row = newRow(dd, text)
        local sw
        sw = pillSwitch(row, UDim2.new(1, -20, 0.5, 0), Vector2.new(1, 0.5), 22, function() return mod.settings[key] end, function()
            mod.settings[key] = not mod.settings[key]
            sw.refresh()
            Hub.listDirty = true
            dirty()
        end, 11)
        mod.setters[key] = function(v) mod.settings[key] = v == true; sw.refresh() end
    end

    addSlider = function(mod, dd, key, text, min, max, default, step, suffix)
        step, suffix = step or 1, suffix or ""
        mod.settings[key] = default
        local row = newRow(dd, text)
        local vb = box(row, 96, 24, UDim2.new(1, -20, 0.5, 0))
        local vt = T_(vb, "", { sz = UDim2.fromScale(1, 1), size = 14, ax = Enum.TextXAlignment.Center, slot = 12, z = 12 })
        local area = new("Frame", { Size = UDim2.fromOffset(200, 20), AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -128, 0.5, 0), BackgroundTransparency = 1, ZIndex = 11 }, row)
        local track = new("Frame", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.new(1, 0, 0, 6), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0.9, BorderSizePixel = 0, ZIndex = 11 }, area)
        corner(track, 3)
        local fill = new("Frame", { Size = UDim2.fromScale(0, 1), BorderSizePixel = 0, ZIndex = 12 }, track)
        corner(fill, 3)
        R(fill, "bg", 9)
        local knobGlow = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(22, 22), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 12 }, track)
        corner(knobGlow, 11)
        local repGlow
        local hot, drag = false, false
        repGlow = B(knobGlow, "bg", function() local c, a = TH.col(11); return c, (hot or drag) and 0.3 or 0 end)
        local knob = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(12, 12), BorderSizePixel = 0, ZIndex = 13 }, track)
        corner(knob, 6)
        R(knob, "bg", 9)
        local function fmt(v)
            local s = step >= 1 and tostring(math.floor(v + 0.5)) or string.format(step < 0.1 and "%.2f" or "%.1f", v)
            return s .. suffix
        end
        local function render(animate)
            local v = mod.settings[key]
            local a = math.clamp((v - min) / (max - min), 0, 1)
            if animate then
                tween(fill, { Size = UDim2.fromScale(a, 1) }, 0.08)
                tween(knob, { Position = UDim2.fromScale(a, 0.5), Size = UDim2.fromOffset(drag and 16 or (hot and 14 or 12), drag and 16 or (hot and 14 or 12)) }, 0.08)
                tween(knobGlow, { Position = UDim2.fromScale(a, 0.5) }, 0.08)
            else
                fill.Size = UDim2.fromScale(a, 1)
                knob.Position = UDim2.fromScale(a, 0.5)
                knobGlow.Position = UDim2.fromScale(a, 0.5)
            end
            vt.Text = fmt(v)
        end
        local function fromMouse()
            local a = math.clamp((UIS:GetMouseLocation().X - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1), 0, 1)
            mod.settings[key] = math.clamp(math.floor((min + a * (max - min)) / step + 0.5) * step, min, max)
            render(true)
        end
        local b = hit(area, 14)
        b.MouseEnter:Connect(function() hot = true; repGlow(); render(true) end)
        b.MouseLeave:Connect(function() hot = false; repGlow(); render(true) end)
        b.InputBegan:Connect(function(i)
            if i.UserInputType == Enum.UserInputType.MouseButton1 then
                drag = true
                repGlow()
                UI.setDrag(function() fromMouse() end)
                fromMouse()
                local c
                c = UIS.InputEnded:Connect(function(e) if e.UserInputType == Enum.UserInputType.MouseButton1 then drag = false; repGlow(); render(true); c:Disconnect() end end)
            end
        end)
        mod.setters[key] = function(v) mod.settings[key] = tonumber(v) or default; render() end
        render()
    end

    local pop
    function UI.openDropdown(anchor, options, current, onPick)
        UI.closeDropdown()
        local sc = uiScale.Scale
        local ap, wp = anchor.AbsolutePosition, win.AbsolutePosition
        local x, y = (ap.X - wp.X) / sc, (ap.Y - wp.Y) / sc + anchor.AbsoluteSize.Y / sc + 4
        local w = anchor.AbsoluteSize.X / sc
        local visibleRows = math.min(#options, 8)
        local fullH = visibleRows * 28 + 8

        local up = y + fullH > 692
        local anchorTop = (ap.Y - wp.Y) / sc
        pop = new("Frame", {
            Position = up and UDim2.fromOffset(x, math.max(anchorTop - 4, fullH + 8)) or UDim2.fromOffset(x, y),
            AnchorPoint = up and Vector2.new(0, 1) or Vector2.zero,
            Size = UDim2.fromOffset(w, fullH), ZIndex = 61, ClipsDescendants = true, Active = true,
        }, win)
        local catcher = new("TextButton", { Size = UDim2.fromOffset(1100, 700), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, ZIndex = 60 }, win)
        catcher.MouseButton1Down:Connect(function() task.defer(UI.closeDropdown) end)
        catcher.MouseButton2Down:Connect(function() task.defer(UI.closeDropdown) end)
        UI.catcher = catcher
        corner(pop, 6)
        R(pop, "bg", 6)
        local st = new("UIStroke", { Thickness = 1 }, pop)
        R(st, "str", 15)
        local holder = pop
        if #options > 8 then
            holder = new("ScrollingFrame", { Size = UDim2.new(1, 0, 1, -8), Position = UDim2.fromOffset(0, 4), BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 3, CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ZIndex = 61, ScrollBarImageColor3 = Color3.fromRGB(120, 120, 130) }, pop)
        else
            new("UIPadding", { PaddingTop = UDim.new(0, 4), PaddingBottom = UDim.new(0, 4) }, pop)
        end
        new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder }, holder)
        for i, o in ipairs(options) do
            local r = new("TextButton", { Size = UDim2.new(1, 0, 0, 28), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, LayoutOrder = i, ZIndex = 62 }, holder)
            local hot = false
            local rep = B(r, "bg", function() local c, a = TH.col(7); return c, hot and a or 0 end)
            local l = T_(r, tostring(o), { pos = UDim2.fromOffset(10, 0), sz = UDim2.new(1, -20, 1, 0), size = 14, z = 63 })
            B(l, "txt", function() return TH.col(o == current and 9 or 12) end)
            r.MouseEnter:Connect(function() hot = true; rep() end)
            r.MouseLeave:Connect(function() hot = false; rep() end)
            r.MouseButton1Click:Connect(function() onPick(o); UI.closeDropdown() end)
        end
        pop.Size = UDim2.fromOffset(w, 0)
        tween(pop, { Size = UDim2.fromOffset(w, fullH) }, 0.16)
        UI.popupAge = os.clock()
    end
    function UI.closeDropdown()
        if pop then pop:Destroy(); pop = nil end
        if UI.catcher then UI.catcher:Destroy(); UI.catcher = nil end
    end
    addMode = function(mod, dd, key, text, options, default)
        mod.settings[key] = default
        local row = newRow(dd, text)
        local b, st = box(row, 140, 28, UDim2.new(1, -20, 0.5, 0))
        local lab = T_(b, default, { pos = UDim2.fromOffset(8, 0), sz = UDim2.new(1, -36, 1, 0), size = 14, slot = 12, trunc = true, z = 12 })
        local ch = new("ImageLabel", { BackgroundTransparency = 1, Image = chevAsset, Size = UDim2.fromOffset(12, 12), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(1, -14, 0.5, 0), ZIndex = 12 }, b)
        local hot = false
        local repCh = B(ch, "img", function() return TH.col(hot and 9 or 13) end)
        local repS = B(st, "str", function() local c1, a1 = TH.col(14); local c2, a2 = TH.col(9); return mixc(c1, a1, c2, a2, hot and 1 or 0) end)
        local repB = B(b, "bg", function() local c1, a1 = TH.col(6); local c2, a2 = TH.col(7); return mixc(c1, a1, c2, a2, hot and 1 or 0) end)
        local function render() lab.Text = tostring(mod.settings[key]) end
        local btn = hit(b, 13)
        btn.MouseEnter:Connect(function() hot = true; repCh(); repS(); repB() end)
        btn.MouseLeave:Connect(function() hot = false; repCh(); repS(); repB() end)
        btn.MouseButton1Click:Connect(function()
            UI.openDropdown(b, options, mod.settings[key], function(o) mod.settings[key] = o; render(); dirty() end)
        end)
        btn.MouseButton2Click:Connect(function()
            local idx = table.find(options, mod.settings[key]) or 1
            mod.settings[key] = options[(idx) % #options + 1]
            render()
            dirty()
        end)
        mod.setters[key] = function(v) if table.find(options, v) then mod.settings[key] = v; render() end end
        render()
    end

    addText = function(mod, dd, key, text, default)
        mod.settings[key] = default
        local row = newRow(dd, text)
        local b, st = box(row, 240, 28, UDim2.new(1, -20, 0.5, 0))
        local tb = new("TextBox", { Position = UDim2.fromOffset(8, 0), Size = UDim2.new(1, -16, 1, 0), BackgroundTransparency = 1, Text = default, FontFace = F_REG, TextSize = 14, TextXAlignment = Enum.TextXAlignment.Left, ClearTextOnFocus = false, ZIndex = 13 }, b)
        R(tb, "txt", 12)
        tb.Focused:Connect(function() tween(st, { Color = (TH.col(9)) }, 0.12) end)
        tb.FocusLost:Connect(function() R(st, "str", 14); mod.settings[key] = tb.Text; dirty() end)
        mod.setters[key] = function(v) mod.settings[key] = tostring(v); tb.Text = tostring(v) end
    end

    function UI.tick(dt)
        local t = os.clock()
        local o = UI.orbs
        o[1].Position = UDim2.fromOffset(math.sin(t * 0.11) * 12 + 550, math.sin(t * 0.13 + 1.2) * 8 + 280)
        o[2].Position = UDim2.fromOffset(math.sin(t * 0.09 + 2.4) * 18 + 120, math.sin(t * 0.15) * 10 + 504)
        o[3].Position = UDim2.fromOffset(math.sin(t * 0.1 + 0.7) * 14 + 1140, math.sin(t * 0.12 + 1.9) * 9 - 50)
        local vp = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(1920, 1080)
        local s = math.min(Hub.userScale or 1, (vp.X - 24) / 1100, (vp.Y - 24) / 700)
        if math.abs(uiScale.Scale - s) > 0.002 then uiScale.Scale = s end
    end
    connect(RS.RenderStepped, function(dt) if Hub.open then UI.tick(dt) end end)
end

local Hands, Controller, Input, Items, World, Config, Combat
local gameOk, gameErr = pcall(function()
    local MC = LP:WaitForChild("PlayerScripts"):WaitForChild("MC")
    Hands = require(MC.Hands)
    Controller = require(MC.Controller)
    Input = require(MC.Input)
    World = require(MC.World)
    local RSMC = game:GetService("ReplicatedStorage"):WaitForChild("MC")
    Items = require(RSMC.Items)
    Config = require(RSMC.Config)
    Combat = require(RSMC.Combat)
end)
if not gameOk then warn("[Prestige] game modules failed: " .. tostring(gameErr)) end

local Core = {}
Hub.Core = Core
local WEAPON = { sword = true, axe = true, mace = true, spear = true, trident = true }
local BLOCK = (Config and Config.BLOCK) or 3

function Core.alive()
    local c = LP.Character
    return gameOk and c ~= nil and c:GetAttribute("Alive") ~= false and Controller.state ~= nil
end
function Core.heldKind()
    local it = Hands.held()
    if not it then return nil end
    local ok, d = pcall(Items.def, it)
    ident()
    return ok and d and d.kind or nil
end
function Core.findSlot(kind)
    for i = 1, 9 do
        local it = Hands.inv.hotbar[i]
        if it then
            local ok, d = pcall(Items.def, it)
            if ok and d and d.kind == kind then ident(); return i end
        end
    end
    ident()
end
function Core.reach()
    local extra = LP:GetAttribute("CreatorReach")
    return math.max(Config.REACH or 3, type(extra) == "number" and extra or 0)
end

local PARTS = { Head = 0.9, Chest = 0.68, Body = 0.5, Feet = 0.1 }
function Core.aimPoint(t, part)
    return t.feet + Vector3.new(0, t.height * (PARTS[part or "Chest"] or 0.68), 0)
end

function Core.targets(playersOnly)
    local out = {}
    local eye = Controller.eye()
    local selfId = LP:GetAttribute("EntityId")
    for _, t in pairs(World.targets()) do
        local m = t.model
        if t.id ~= selfId and m and m.Parent and m:GetAttribute("Alive") ~= false and m:GetAttribute("Gamemode") ~= "spectator" then
            local plr = Players:GetPlayerFromCharacter(m) or Players:FindFirstChild(m.Name)
            if not playersOnly or plr then
                out[#out + 1] = {
                    id = t.id, model = m, raw = t, plr = plr, friend = plr ~= nil and Hub.friends ~= nil and Hub.friends[plr.Name] == true, feet = t.feet, height = t.height or 1.8,
                    name = m:GetAttribute("DisplayName") or m.Name, health = m:GetAttribute("Health") or 20,
                    maxHealth = m:GetAttribute("MaxHealth") or 20,
                    dist = ((t.feet + Vector3.new(0, 0.9, 0)) - eye).Magnitude,
                }
            end
        end
    end
    ident()
    return out
end

function Core.canHit(t, dir, reach)
    local p = World.pick(Controller.eye(), dir, reach)
    ident()
    return p ~= nil and p.id == t.id
end

function Core.best(o)
    local eye, look = Controller.eye(), Controller.look()
    if o.needHit then o = setmetatable({ range = math.min(o.range, Core.reach()) }, { __index = o }) end
    local best, bestDir, bestScore
    for _, t in ipairs(Core.targets(o.playersOnly)) do
        local v = Core.aimPoint(t, o.part) - eye
        local d = v.Magnitude
        if d <= o.range + 1 and d > 0.01 and t.id ~= o.exclude and not t.friend then
            local dir = v.Unit
            local ang = math.deg(math.acos(math.clamp(dir:Dot(look), -1, 1)))
            if not o.fov or ang <= o.fov * 0.5 then
                if not o.needHit or Core.canHit(t, dir, o.range) then
                    local score = o.priority == "Distance" and d or (o.priority == "Health" and t.health or ang)
                    if not bestScore or score < bestScore then best, bestDir, bestScore = t, dir, score end
                end
            end
        end
    end
    ident()
    return best, bestDir
end

local saved
function Core.aim(dir)
    if saved or not gameOk then return end
    saved = { Controller.yaw, Controller.pitch }
    Controller.yaw = math.atan2(-dir.X, -dir.Z)
    Controller.pitch = math.asin(math.clamp(dir.Y, -1, 1))
end
function Core.unaim()
    if saved then
        Controller.yaw, Controller.pitch = saved[1], saved[2]
        saved = nil
    end
end

local function asGame(fn, ...)
    local prev = 8
    pcall(function() prev = getthreadidentity() end)
    pcall(setthreadidentity, 2)
    local ok, err = pcall(fn, ...)
    pcall(setthreadidentity, prev)
    if not ok then error(err, 0) end
end
function Core.select(slot) asGame(Hands.select, slot) end
function Core.virtual(action, down) asGame(Input.setVirtual, action, down) end
function Core.press(action)
    if Input.isDown(action) then Core.virtual(action, false) end
    Core.virtual(action, true)
    Core.virtual(action, false)
end
function Core.attackAt(dir)
    if dir then Core.aim(dir) end
    local ok, err = pcall(Core.press, "attack")
    ident()
    if dir then Core.unaim() end
    if not ok then warn("[Prestige] attack failed: " .. tostring(err)) end
end

function Core.charged() local v = Hands.strength(0) >= 1; ident(); return v end

function Core.claim(owner)
    if Core.owner and Core.owner ~= owner and os.clock() < (Core.ownerUntil or 0) then return false end
    Core.owner, Core.ownerUntil = owner, os.clock() + 4
    return true
end
function Core.release(owner) if Core.owner == owner then Core.owner = nil end end

local tickFn, postFn
if gameOk then
    tickFn = guard(function()
        if not Core.alive() then return end
        for _, mod in ipairs(Hub.order) do
            if mod.enabled and mod.def.tick then
                ident()
                local ok, err = pcall(mod.def.tick, mod)
                if not ok then
                    mod.errs = (mod.errs or 0) + 1
                    if mod.errs <= 3 then warn("[Prestige] " .. mod.name .. " tick: " .. tostring(err)) end
                end
            end
        end
    end)
    postFn = guard(function() Core.unaim() end)
    table.insert(Controller.beforeTick, 1, tickFn)
    table.insert(Controller.beforeTick, postFn)
end

local lastFrame = os.clock()
connect(RS.RenderStepped, function()
    local now = os.clock()
    local dt = math.min(now - lastFrame, 0.1)
    lastFrame = now
    Hub.frameId = (Hub.frameId or 0) + 1
    if not (gameOk and Core.alive()) then return end
    for _, mod in ipairs(Hub.order) do
        if mod.enabled and mod.def.step then
            ident()
            local ok, err = pcall(mod.def.step, mod, dt)
            if not ok then
                mod.errs = (mod.errs or 0) + 1
                if mod.errs <= 3 then warn("[Prestige] " .. mod.name .. " step: " .. tostring(err)) end
            end
        end
    end
end)

local pressTable
if gameOk then
    local ups = debug.getupvalues and debug.getupvalues(Input.onPressed)
    pressTable = ups and ups[1] and ups[1].attack
end
local silentPre = guard(function()

    local mod = Hub.modules["Silent Aim"]
    if mod and mod.enabled and not saved then
        local s = mod.settings
        local t, dir = Core.best({ range = s.range, fov = s.fov, playersOnly = s.playersOnly, part = s.part, priority = "Angle", needHit = true })
        if t then Core.aim(dir); Hub.lastTarget, Hub.lastTargetAt = t, os.clock() end
    end
    local ms = Hub.modules["Mace Swap"]
    if ms and ms.enabled then pcall(ms.def.attrSwap, ms) end
end)
local wtapPost = guard(function()
    local mod = Hub.modules["W Tap"]
    if mod and mod.enabled then
        Core.virtual("forward", false)
        task.delay(mod.settings.delay / 1000, function()
            if UIS:IsKeyDown(Enum.KeyCode.W) then Core.virtual("forward", true) end
        end)
    end
end)
local silentPost = guard(function() Core.unaim() end)
if pressTable then
    table.insert(pressTable, 1, silentPre)
    table.insert(pressTable, silentPost)
    table.insert(pressTable, wtapPost)
end

function Core.frameTargets()
    if Core._fid ~= Hub.frameId then Core._fid = Hub.frameId; Core._ft = Core.targets(false) end
    return Core._ft
end
local function decodeAttr(m, name)
    local ok, d = pcall(HttpService.JSONDecode, HttpService, tostring(m:GetAttribute(name) or ""))
    return ok and type(d) == "table" and d.id or ""
end
function Core.shielded(t)
    local using = tostring(t.model:GetAttribute("Using") or "")
    if using == "" then return false end
    if using:lower():find("shield") then return true end
    return decodeAttr(t.model, "Held") == "shield" or decodeAttr(t.model, "Offhand") == "shield"
end
local function setTarget(t) Hub.lastTarget, Hub.lastTargetAt = t, os.clock() end
local function escapePat(s) return (s:gsub("%p", "%%%0")) end

local combat   = newPanel("Combat", "swords")
local misc     = newPanel("Misc", "wrench")
local movement = newPanel("Movement", "footprints")
local visual   = newPanel("Visual", "eye")
local PNX = { mace = newPanel("Mace"), spear = newPanel("Spear") }

newModule(combat, "Aim Assist", {
    build = function(mod, dd)
        addSlider(mod, dd, "range", "Range", 3, 12, 6, 0.5, " b")
        addSlider(mod, dd, "fov", "FOV", 10, 180, 90, 5, "°")
        addSlider(mod, dd, "speed", "Smoothing", 1, 30, 8, 1)
        addMode(mod, dd, "part", "Aim At", { "Head", "Chest", "Body" }, "Chest")
        addCheck(mod, dd, "vertical", "Vertical", true)
        addCheck(mod, dd, "clickOnly", "Only While Clicking", true)
        addCheck(mod, dd, "playersOnly", "Players Only", true)
    end,
    step = function(mod, dt)
        local s = mod.settings
        if Input.mouseFree then return end
        if s.clickOnly and not UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then return end
        local t, dir = Core.best({ range = s.range, fov = s.fov, playersOnly = s.playersOnly, part = s.part, priority = "Angle", needHit = false })
        if not t then return end
        local a = math.min(1, s.speed * dt)
        local dy = (math.atan2(-dir.X, -dir.Z) - Controller.yaw + math.pi) % (2 * math.pi) - math.pi
        Controller.yaw = Controller.yaw + dy * a
        if s.vertical then Controller.pitch = Controller.pitch + (math.asin(dir.Y) - Controller.pitch) * a end
    end,
})

newModule(combat, "Auto Totem", {
    build = function(mod, dd)
        addSlider(mod, dd, "delay", "Delay", 0, 500, 120, 10, " ms")
        addCheck(mod, dd, "swapBack", "Swap Back", true)
    end,
    tick = function(mod)
        local rt, s = mod.rt, mod.settings
        if rt.stage == "back" then
            rt.n += 1
            if rt.n >= 2 then
                if s.swapBack and rt.origin ~= rt.slot then Core.select(rt.origin) end
                mod.rt = { cool = os.clock() + 0.8 }
                Core.release(mod)
            end
            return
        end
        local off = Hands.inv.offhand
        local ok, d = pcall(Items.def, off or {})
        if off and ok and d and d.kind == "totem" then rt.since = nil; return end
        if rt.cool and os.clock() < rt.cool then return end
        rt.since = rt.since or os.clock()
        if os.clock() - rt.since < s.delay / 1000 then return end
        local slot = Core.findSlot("totem")
        if not slot or not Core.claim(mod) then return end
        rt.origin, rt.slot, rt.since = Hands.inv.selected, slot, nil
        if slot ~= rt.origin then Core.select(slot) end
        Core.press("swap")
        rt.stage, rt.n = "back", 0
    end,
})

newModule(combat, "Kill Aura", {
    build = function(mod, dd)
        addSlider(mod, dd, "range", "Range", 2, 3.6, 3, 0.1, " b")
        addSlider(mod, dd, "minDelay", "Min Delay", 0, 500, 80, 10, " ms")
        addSlider(mod, dd, "maxDelay", "Max Delay", 0, 500, 140, 10, " ms")
        addSlider(mod, dd, "fov", "FOV", 30, 360, 360, 10, "°")
        addMode(mod, dd, "rotation", "Rotation", { "Silent Flick", "None" }, "Silent Flick")
        addMode(mod, dd, "targets", "Targets", { "Single", "Switch" }, "Single")
        addMode(mod, dd, "priority", "Priority", { "Distance", "Health", "Angle" }, "Distance")
        addMode(mod, dd, "part", "Aim At", { "Head", "Chest", "Body" }, "Chest")
        addCheck(mod, dd, "requireCharge", "Require Charge", true)
        addCheck(mod, dd, "weaponsOnly", "Weapons Only", true)
        addCheck(mod, dd, "playersOnly", "Players Only", true)
    end,
    tick = function(mod)
        local s, rt = mod.settings, mod.rt
        if Input.mouseFree or Hands.using or Core.owner then return end
        if s.weaponsOnly and not WEAPON[Core.heldKind() or ""] then return end
        local now = os.clock()
        if rt.nextAt and now < rt.nextAt then return end
        if s.requireCharge and not Core.charged() then return end
        local t, dir
        if s.rotation == "None" then

            t = Core.pickTarget(s.playersOnly)
        else

            local o = { range = s.range, fov = s.fov, playersOnly = s.playersOnly, part = s.part, priority = s.priority, needHit = true, exclude = (s.targets == "Switch") and rt.last or nil }
            t, dir = Core.best(o)
            if not t and o.exclude then o.exclude = nil; t, dir = Core.best(o) end
        end
        if not t then return end
        Core.attackAt(dir)
        setTarget(t)
        rt.last = t.id
        rt.nextAt = now + rand(math.min(s.minDelay, s.maxDelay), math.max(s.minDelay, s.maxDelay)) / 1000
    end,
})

newModule(PNX.spear, "Lunge Swap", {
