newModule(PNX.mace, "Mace Swap", {
    build = function(mod, dd)
        addMode(mod, dd, "mode", "Trigger", { "Falling", "Always" }, "Falling")
        addSlider(mod, dd, "minFall", "Fall Height", 1.5, 40, 2, 0.5, " b")
        addSlider(mod, dd, "backTicks", "Swap Back After", 2, 10, 3, 1, " ticks")
        addMode(mod, dd, "gate", "Swap When", { "Crosshair On", "Target Near", "Any Click" }, "Crosshair On")
        addCheck(mod, dd, "swapBack", "Swap Back", true)
        addCheck(mod, dd, "playersOnly", "Players Only", true)
        addCheck(mod, dd, "debug", "Show Skip Reason", false)
    end,

    attrSwap = function(mod)
        local s, rt, st = mod.settings, mod.rt, Controller.state
        local function skip(why)
            Hub.maceLog = Hub.maceLog or {}
            table.insert(Hub.maceLog, why)
            if #Hub.maceLog > 30 then table.remove(Hub.maceLog, 1) end
            if s.debug then notify("Mace Swap skipped: " .. why) end
        end
        if not Core.alive() then return skip("not alive") end
        if rt.stage then return skip("swap already running (stage " .. tostring(rt.stage) .. ")") end
        if Core.heldKind() == "mace" then return end
        local fall = (st.fallDistance or 0) >= math.max(s.minFall, (Combat and Combat.SMASH_MIN_FALL) or 1.5) and not st.gliding
        if s.mode == "Falling" and not fall then return skip(string.format("fall %.1f < %.1f", st.fallDistance or 0, s.minFall)) end
        local slot = Core.findSlot("mace")
        if not slot then return skip("no mace in hotbar") end
        if s.gate == "Crosshair On" then
            if not Core.pickTarget(s.playersOnly) then return skip("crosshair not on a target") end
        elseif s.gate == "Target Near" then

            local eye, look = Controller.eye(), Controller.look()
            local near = false
            for _, t in ipairs(Core.targets(s.playersOnly)) do
                local v = Core.aimPoint(t, "Chest") - eye
                if v.Magnitude <= Core.reach() * 1.45 + 0.5 and v.Unit:Dot(look) > -0.2 then near = true; break end
            end
            if not near then return skip("no target within reach") end
        end
        rt.stage, rt.slot, rt.origin, rt.n = "hit", slot, Hands.inv.selected, 0
        Core.select(slot)
    end,
    tick = function(mod)
        local rt, s = mod.rt, mod.settings
        if rt.stage ~= "hit" then return end
        rt.n += 1
        if rt.n >= s.backTicks then
            if s.swapBack and rt.origin ~= rt.slot and Hands.inv.selected == rt.slot then Core.select(rt.origin) end
            mod.rt = {}
        end
    end,
})

newModule(combat, "Shield Breaker", {
    build = function(mod, dd)
        addSlider(mod, dd, "range", "Range", 2, 3.6, 3, 0.1, " b")
        addSlider(mod, dd, "swapDelay", "Swap Delay", 0, 400, 0, 10, " ms")
        addSlider(mod, dd, "attackDelay", "Attack Delay", 0, 400, 0, 10, " ms")
        addSlider(mod, dd, "backDelay", "Back Delay", 0, 600, 120, 10, " ms")
        addCheck(mod, dd, "auto", "Auto (Blocking Only)", true)
        addCheck(mod, dd, "swapBack", "Swap Back", true)
        addCheck(mod, dd, "playersOnly", "Players Only", true)
    end,
    onBind = function(mod) mod.force = true end,
    tick = function(mod)
        local s, rt, now = mod.settings, mod.rt, os.clock()
        if rt.stage then
            if rt.stage == "swap" and now >= rt.at then
                if Hands.inv.selected ~= rt.slot then Core.select(rt.slot) end
                rt.stage, rt.at = "attack", now + s.attackDelay / 1000
            end
            if rt.stage == "attack" and now >= rt.at then
                local t, dir = Core.best({ range = s.range, playersOnly = s.playersOnly, part = "Chest", priority = "Distance", needHit = true })
                if t then Core.attackAt(dir); setTarget(t) end
                rt.stage, rt.at = "back", now + s.backDelay / 1000
            elseif rt.stage == "back" and now >= rt.at then
                if s.swapBack and rt.origin ~= rt.slot then Core.select(rt.origin) end
                mod.rt = { cool = now + 0.35 }
                Core.release(mod)
            end
            return
        end
        if rt.cool and now < rt.cool then return end
        if Input.mouseFree or Hands.using or Core.owner then return end
        local force = mod.force
        if not (s.auto or force) then return end
        local t = Core.best({ range = s.range, playersOnly = s.playersOnly, part = "Chest", priority = "Distance", needHit = true })
        if not t or not (force or Core.shielded(t)) then return end
        mod.force = false
        local slot = Core.findSlot("axe")
        if not slot then
            if not rt.warned then rt.warned = true; notify("No axe in hotbar") end
            return
        end
        if Core.heldKind() == "axe" then slot = Hands.inv.selected end
        if not Core.claim(mod) then return end
        mod.rt = { stage = "swap", slot = slot, origin = Hands.inv.selected, at = now + s.swapDelay / 1000 }
    end,
})

