newModule(combat, "Triggerbot", {
    build = function(mod, dd)
        addSlider(mod, dd, "minDelay", "Min Delay", 0, 500, 40, 10, " ms")
        addSlider(mod, dd, "maxDelay", "Max Delay", 0, 500, 90, 10, " ms")
        addCheck(mod, dd, "requireCharge", "Require Charge", true)
        addCheck(mod, dd, "weaponsOnly", "Weapons Only", true)
        addCheck(mod, dd, "playersOnly", "Players Only", true)
    end,
    tick = function(mod)
        local s, rt = mod.settings, mod.rt
        if Input.mouseFree or Hands.using or Core.owner then return end
        if s.weaponsOnly and not WEAPON[Core.heldKind() or ""] then rt.id = nil; return end
        local raw = World.pick(Controller.eye(), Controller.look(), Core.reach())
        if not raw then rt.id = nil; return end
        local t
        for _, x in ipairs(Core.targets(s.playersOnly)) do if x.id == raw.id then t = x; break end end
        if not t then rt.id = nil; return end
        local now = os.clock()
        local lo, hi = math.min(s.minDelay, s.maxDelay), math.max(s.minDelay, s.maxDelay)
        if rt.id ~= t.id then rt.id, rt.seen, rt.wait = t.id, now, rand(lo, hi) / 1000 end
        if now - rt.seen < rt.wait then return end
        if s.requireCharge and not Core.charged() then return end
        Core.attackAt(nil)
        setTarget(t)
        rt.seen, rt.wait = now, rand(lo, hi) / 1000
    end,
})

