local function useSwap(kind, nice, extra)
    return {
        build = function(mod, dd)
            addSlider(mod, dd, "backDelay", "Back Delay", 0, 500, 120, 10, " ms")
            addCheck(mod, dd, "swapBack", "Swap Back", true)
            if extra then extra(mod, dd) end
        end,
        onBind = function(mod)
            if mod.rt.stage then return end
            local slot = Core.findSlot(kind)
            if not slot then return notify("No " .. nice .. " in hotbar") end
            if not Core.claim(mod) then return end
            mod.rt = { stage = "select", slot = slot, origin = Hands.inv.selected }
        end,
        tick = function(mod)
            local rt, s = mod.rt, mod.settings
            if not rt.stage then return end
            local down = s.lookDown
            if rt.stage == "select" then
                if rt.slot ~= Hands.inv.selected then Core.select(rt.slot) end
                if down then Core.aim(Vector3.new(0, -1, 0)) end
                Core.virtual("use", true)
                rt.stage, rt.n = "release", 0
            elseif rt.stage == "release" then
                rt.n += 1
                if down then Core.aim(Vector3.new(0, -1, 0)) end
                if rt.n >= 2 then
                    Core.virtual("use", false)
                    rt.stage, rt.at = "back", os.clock() + s.backDelay / 1000
                end
            elseif os.clock() >= rt.at then
                if s.swapBack and rt.origin ~= rt.slot then Core.select(rt.origin) end
                mod.rt = {}
                Core.release(mod)
            end
        end,
    }
end
