newModule(misc, "Name Hider", {
    build = function(mod, dd) addText(mod, dd, "name", "Replace With", "Player") end,
    step = function(mod, dt)
        local rt = mod.rt
        rt.acc = (rt.acc or 0) + dt
        if rt.acc < 0.4 then return end
        rt.acc = 0
        rt.orig = rt.orig or {}
        local repl = (mod.settings.name or "Player"):gsub("%%", "%%%%")
        for _, d in ipairs(LP.PlayerGui:GetDescendants()) do
            if d:IsA("TextLabel") or d:IsA("TextButton") then
                local tx = d.Text
                local changed = tx
                for _, n in ipairs({ LP.Name, LP.DisplayName }) do
                    if n ~= "" and changed:find(n, 1, true) then changed = changed:gsub(escapePat(n), repl) end
                end
                if changed ~= tx then rt.orig[d] = rt.orig[d] or tx; d.Text = changed end
            end
        end
    end,
    onToggle = function(mod, on)
        if not on and mod.rt.orig then
            for d, tx in pairs(mod.rt.orig) do if d.Parent then d.Text = tx end end
            mod.rt.orig = nil
        end
    end,
})

