        addCheck(mod, dd, "fill", "Fill", true)
        addCheck(mod, dd, "outline", "Outline", true)
        addCheck(mod, dd, "playersOnly", "Players Only", true)
    end,
    step = function(mod)
        local s, rt = mod.settings, mod.rt
        rt.hl = rt.hl or {}
        local seen = {}
        for _, t in ipairs(Core.frameTargets()) do
            if (not s.playersOnly or t.plr) and t.dist <= s.maxDist then
                seen[t.id] = true
                local h = rt.hl[t.id]
                if not h or h.Adornee ~= t.model then
                    if h then h:Destroy() end
                    h = new("Highlight", { Adornee = t.model, DepthMode = Enum.HighlightDepthMode.AlwaysOnTop }, world)
                    rt.hl[t.id] = h
                end
                local col = T.accent
                if t.friend then col = Color3.fromRGB(74, 222, 128)
                elseif s.color == "Health" then col = Color3.fromHSV(math.clamp(t.health / math.max(t.maxHealth, 1), 0, 1) * 0.33, 0.75, 1)
                elseif s.color == "Distance" then col = Color3.fromRGB(255, 80, 80):Lerp(T.accent, math.clamp(t.dist / s.maxDist, 0, 1)) end
                h.FillColor = col
                h.OutlineColor = col:Lerp(Color3.new(1, 1, 1), 0.55)
                h.FillTransparency = s.fill and 0.7 or 1
                h.OutlineTransparency = s.outline and 0 or 1
            end
        end
        for id, h in pairs(rt.hl) do if not seen[id] then h:Destroy(); rt.hl[id] = nil end end
    end,
    onToggle = function(mod, on)
        if not on and mod.rt.hl then
            for _, h in pairs(mod.rt.hl) do h:Destroy() end
            mod.rt.hl = nil
        end
    end,
})

local Plates = { list = {} }
function Plates.clear()
    for id, p in pairs(Plates.list) do p.gui:Destroy(); Plates.list[id] = nil end
end
function Plates.sync()
    if Plates.fid == Hub.frameId then return end
    Plates.fid = Hub.frameId
    local nt, hi = Hub.modules["Name Tags"], Hub.modules["Health Indicators"]
    local seen = {}
    for _, t in ipairs(Core.frameTargets()) do
        local showName = nt.enabled and (not nt.settings.playersOnly or t.plr) and t.dist <= nt.settings.maxDist
        local showHP = hi.enabled and (not hi.settings.playersOnly or t.plr) and t.dist <= hi.settings.maxDist
        if showName or showHP then
            seen[t.id] = true
            local p = Plates.list[t.id]
            local adornee = t.model:FindFirstChild("Head") or t.model:FindFirstChild("HumanoidRootPart")
            if adornee then
                if not p or p.adornee ~= adornee then
                    if p then p.gui:Destroy() end
                    local bb = new("BillboardGui", {
                        Adornee = adornee, Size = UDim2.fromOffset(150, 38), StudsOffsetWorldSpace = Vector3.new(0, 1.8, 0),
                        AlwaysOnTop = true, LightInfluence = 0, ResetOnSpawn = false,
                    }, world)
                    local name = new("TextLabel", {
                        Size = UDim2.new(1, 0, 0, 14), BackgroundTransparency = 1, FontFace = F_BOLD, TextSize = 12,
                        TextColor3 = Color3.new(1, 1, 1), TextStrokeTransparency = 0.45,
                    }, bb)
                    local back = new("Frame", {
                        Size = UDim2.fromOffset(84, 5), Position = UDim2.new(0.5, -42, 0, 18), BackgroundColor3 = Color3.fromRGB(20, 20, 24),
                        BorderSizePixel = 0,
                    }, bb)
                    new("UICorner", { CornerRadius = UDim.new(1, 0) }, back)
                    new("UIStroke", { Color = Color3.new(0, 0, 0), Transparency = 0.4 }, back)
                    local fill = new("Frame", { Size = UDim2.fromScale(1, 1), BorderSizePixel = 0 }, back)
                    new("UICorner", { CornerRadius = UDim.new(1, 0) }, fill)
                    local num = new("TextLabel", {
                        Size = UDim2.new(1, 0, 0, 12), Position = UDim2.fromOffset(0, 25), BackgroundTransparency = 1, FontFace = F_REG,
                        TextSize = 10, TextColor3 = T.bright, TextStrokeTransparency = 0.5,
                    }, bb)
                    p = { gui = bb, adornee = adornee, name = name, back = back, fill = fill, num = num }
                    Plates.list[t.id] = p
                end
                p.name.Visible = showName
                if showName then
                    p.name.Text = nt.settings.showDist and string.format("%s  [%.0f]", t.name, t.dist) or t.name
                    p.name.TextColor3 = t.friend and Color3.fromRGB(74, 222, 128) or T.bright
                end
                p.back.Visible, p.num.Visible = showHP, showHP and hi.settings.showNumber
                p.back.Position = UDim2.new(0.5, -42, 0, showName and 18 or 2)
                p.num.Position = UDim2.fromOffset(0, showName and 25 or 9)
                if showHP then
                    local frac = math.clamp(t.health / math.max(t.maxHealth, 1), 0, 1)
                    p.fill.Size = UDim2.fromScale(frac, 1)
                    p.fill.BackgroundColor3 = Color3.fromHSV(frac * 0.33, 0.72, 1)
                    p.num.Text = string.format("%.1f HP", t.health)
                end
            end
        end
    end
    for id, p in pairs(Plates.list) do if not seen[id] then p.gui:Destroy(); Plates.list[id] = nil end end
end
