        if not Drawing then return end
        local s, rt = mod.settings, mod.rt
        rt.lines = rt.lines or {}
        local cam = workspace.CurrentCamera
        local vp = cam.ViewportSize
        local from = s.origin == "Center" and Vector2.new(vp.X / 2, vp.Y / 2) or Vector2.new(vp.X / 2, vp.Y)
        local seen = {}
        for _, t in ipairs(Core.frameTargets()) do
