                local p, vis = cam:WorldToViewportPoint((t.feet + Vector3.new(0, t.height * 0.5, 0)) * BLOCK)
                if vis and p.Z > 0 then
                    local l = rt.lines[t.id]
                    if not l then l = Drawing.new("Line"); l.Thickness = 1.3; rt.lines[t.id] = l end
                    l.From, l.To, l.Color, l.Visible = from, Vector2.new(p.X, p.Y), T.accent, true
                    seen[t.id] = true
                end
            end
        end
        for id, l in pairs(rt.lines) do if not seen[id] then l.Visible = false end end
    end,
