function Core.pickTarget(playersOnly)
    local raw = World.pick(Controller.eye(), Controller.look(), Core.reach())
    ident()
    if not raw then return nil end
    for _, x in ipairs(Core.targets(playersOnly)) do if x.id == raw.id then return x end end
end

local MCFolder = gameOk and LP.PlayerScripts:FindFirstChild("MC")

local function findFood(preferGold)
    local best
    for i = 1, 9 do
        local it = Hands.inv.hotbar[i]
        if it then
            local ok, d = pcall(Items.def, it)
            if ok and d and d.kind == "food" then
                if not best then best = i end
                if preferGold and tostring(it.id):find("golden") then ident(); return i end
            end
        end
    end
    ident()
    return best
end
newModule(misc, "Auto Eat", {
    build = function(mod, dd)
        addSlider(mod, dd, "health", "Eat Below Health", 4, 19, 12, 1, " hp")
        addSlider(mod, dd, "hunger", "Eat Below Hunger", 2, 19, 10, 1)
        addSlider(mod, dd, "enemyRange", "Not Near Enemy", 0, 12, 4, 1, " b")
        addCheck(mod, dd, "swapBack", "Swap Back", true)
    end,
    tick = function(mod)
        local rt, s = mod.rt, mod.settings
        if rt.stage == "eat" then
            rt.n += 1
            if Hands.inv.selected ~= rt.slot then Core.select(rt.slot) end
            if rt.n >= 38 then Core.virtual("use", false); rt.stage, rt.n = "back", 0 end
        elseif rt.stage == "back" then
            rt.n += 1
            if rt.n >= 2 then
                if s.swapBack and rt.origin ~= rt.slot then Core.select(rt.origin) end
                mod.rt = { cool = os.clock() + 1.2 }
                Core.release(mod)
            end
        else
            if rt.cool and os.clock() < rt.cool then return end
            local hp, food = LP:GetAttribute("Health") or 20, LP:GetAttribute("Food") or 20
            if hp > s.health and food > s.hunger then return end
            if s.enemyRange > 0 then
                for _, t in ipairs(Core.targets(true)) do if t.dist <= s.enemyRange then return end end
            end
            local slot = findFood(hp <= s.health)
            if not slot or not Core.claim(mod) then return end
            rt.slot, rt.origin, rt.stage, rt.n = slot, Hands.inv.selected, "eat", 0
            if slot ~= rt.origin then Core.select(slot) end
            Core.virtual("use", true)
        end
    end,
    onToggle = function(mod, on) if not on and Input then Core.virtual("use", false) end end,
})

