newModule(misc, "Auto Quest", {
    build = function(mod, dd)
        addSlider(mod, dd, "range", "Hunt Range", 10, 150, 70, 5, " b")
        addSlider(mod, dd, "stop", "Stop Distance", 1.5, 3, 2.1, 0.1, " b")
        addSlider(mod, dd, "turn", "Turn Speed", 2, 30, 12, 1)
        addSlider(mod, dd, "minDelay", "Min Delay", 0, 500, 90, 10, " ms")
        addSlider(mod, dd, "maxDelay", "Max Delay", 0, 500, 150, 10, " ms")
        addCheck(mod, dd, "sprint", "Sprint", true)
        addCheck(mod, dd, "jump", "Jump Over Blocks", true)
        addCheck(mod, dd, "strafe", "Strafe", true)
        addCheck(mod, dd, "playersOnly", "Players Only", true)
    end,
    tick = function(mod)
        local s, rt, st = mod.settings, mod.rt, Controller.state
        if Input.mouseFree then return end
        local best, bd
        for _, t in ipairs(Core.targets(s.playersOnly)) do
            if t.dist <= s.range and (not bd or t.dist < bd) then best, bd = t, t.dist end
        end
        if not best then
            rt.target = nil
            Core.virtual("forward", false)
            Core.virtual("sprint", false)
            Core.virtual("jump", false)
            return
        end
        rt.target = best
        local eye = Controller.eye()
        local dir = (Core.aimPoint(best, "Chest") - eye).Unit
        rt.dir = dir
        local close = bd <= s.stop
        Core.virtual("forward", not close)
        Core.virtual("sprint", s.sprint and not close)
        local wantJump = s.jump and (st.hCollide or false) and st.onGround
        Core.virtual("jump", wantJump == true)
        if s.strafe and bd < 6 then
            local left = (math.floor(os.clock() * 1.3) % 2) == 0
            Core.virtual("left", left)
            Core.virtual("right", not left)
        else
            Core.virtual("left", false)
            Core.virtual("right", false)
        end
        local now = os.clock()
        if rt.nextAt and now < rt.nextAt then return end
        if Core.owner or Hands.using or not Core.charged() then return end
        local t, adir = Core.best({ range = Core.reach(), fov = 360, playersOnly = s.playersOnly, part = "Chest", priority = "Distance", needHit = true })
        if not t then return end
        Core.attackAt(adir)
        setTarget(t)
        rt.nextAt = now + rand(math.min(s.minDelay, s.maxDelay), math.max(s.minDelay, s.maxDelay)) / 1000
    end,
    step = function(mod, dt)
        local rt, s = mod.rt, mod.settings
        local dir = rt.dir
        if not (rt.target and dir) then return end
        local a = math.min(1, s.turn * dt)
        local dy = (math.atan2(-dir.X, -dir.Z) - Controller.yaw + math.pi) % (2 * math.pi) - math.pi
        Controller.yaw = Controller.yaw + dy * a
        Controller.pitch = Controller.pitch + (math.asin(math.clamp(dir.Y, -1, 1)) - Controller.pitch) * a
    end,
    onToggle = function(mod, on)
        if not on and Input then
            for _, a in ipairs({ "forward", "sprint", "jump", "left", "right" }) do Core.virtual(a, false) end
            mod.rt = {}
        end
    end,
})

