local TextService = game:GetService("TextService")
local widthCache = {}
local function textWidth(text)
    if not widthCache[text] then
        local ok, v = pcall(function()
            local params = Instance.new("GetTextBoundsParams")
            params.Text, params.Font, params.Size, params.Width = text, F_SEMI, 12, 1000
            return TextService:GetTextBoundsAsync(params).X
        end)
        widthCache[text] = (ok and v or (#text * 7)) + 1
    end
    return widthCache[text]
end

local netReg
if gameOk then
    local ok, reg = pcall(function() return debug.getupvalues(require(MCFolder.Net).on)[1] end)
    if ok and type(reg) == "table" then netReg = reg end
end
local function addNetHandler(event, fn)
    if not (netReg and netReg[event]) then return nil end
    local wrapped = guard(fn)
    table.insert(netReg[event], 1, wrapped)
    return wrapped
end
local function removeNetHandler(event, fn)
    if not (netReg and netReg[event] and fn) then return end
    local i = table.find(netReg[event], fn)
    if i then table.remove(netReg[event], i) end
end
local function myEntityId() return LP:GetAttribute("EntityId") end

