newModule(visual, "Crosshair", {
    build = function(mod, dd)
        addMode(mod, dd, "style", "Style", { "Prestige", "Cross", "Plus + Dot", "Dot", "Circle", "T Shape" }, "Prestige")
        addSlider(mod, dd, "size", "Length", 2, 24, 8, 1, " px")
        addSlider(mod, dd, "gap", "Gap", 0, 16, 4, 1, " px")
        addSlider(mod, dd, "thick", "Thickness", 1, 5, 2, 1, " px")
        addMode(mod, dd, "color", "Color", { "Accent", "White", "Health", "Rainbow" }, "Accent")
        addCheck(mod, dd, "outline", "Outline", true)
        addCheck(mod, dd, "dynamic", "Dynamic Gap", true)
        addCheck(mod, dd, "enemy", "Red On Target", true)
        addCheck(mod, dd, "hitmarker", "Hit Marker", true)
        addSlider(mod, dd, "opacity", "Opacity", 20, 100, 100, 5, "%")
    end,
    onToggle = function(mod, on)
        local rt = mod.rt
        if rt.root then rt.root:Destroy(); rt.root = nil end
        removeNetHandler("hurt", rt.hook)
        rt.hook = nil
        if not on then return end
        local root = new("Frame", { Size = UDim2.fromOffset(0, 0), Position = UDim2.fromScale(0.5, 0.5), BackgroundTransparency = 1 }, hud)
        rt.root, rt.bars, rt.spread, rt.hitT = root, {}, 0, -10
        for i = 1, 5 do
            local f = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), BorderSizePixel = 0 }, root)
            new("UIStroke", { Color = Color3.new(0, 0, 0), Thickness = 1, Transparency = 0.25 }, f)
            rt.bars[i] = f
        end
        rt.ringOut = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), BackgroundTransparency = 1 }, root)
        new("UICorner", { CornerRadius = UDim.new(1, 0) }, rt.ringOut)
        rt.ringOutStroke = new("UIStroke", { Color = Color3.new(0, 0, 0), Thickness = 4, Transparency = 0.76 }, rt.ringOut)
        rt.ring = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), BackgroundTransparency = 1 }, root)
        rt.ringCorner = new("UICorner", { CornerRadius = UDim.new(1, 0) }, rt.ring)
        rt.ringStroke = new("UIStroke", { Thickness = 2 }, rt.ring)
        rt.marks = {}
        for i = 1, 4 do
            rt.marks[i] = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, Rotation = 45 + 90 * (i - 1), Size = UDim2.fromOffset(2, 7) }, root)
        end
        rt.hook = addNetHandler("hurt", function(p)
            if p.attacker == myEntityId() and mod.enabled then rt.hitT = os.clock() end
        end)
    end,
    step = function(mod, dt)
        local rt, s = mod.rt, mod.settings
        if not rt.bars then return end
        local st = Controller and Controller.state
        local target = 0
        if s.dynamic and st then
            local sp = st.vel and Vector3.new(st.vel.X, 0, st.vel.Z).Magnitude or 0
            target = math.min(sp * 18, 4) + (st.sprinting and 2 or 0) + (st.onGround and 0 or 4)
        end
        local now = os.clock()
        target += math.max(0, 1 - (now - rt.hitT) / 0.2) * 3
        rt.spread += (target - rt.spread) * (1 - math.exp(-dt * 14))
        local col
        if s.color == "White" then col = Color3.new(1, 1, 1)
        elseif s.color == "Rainbow" then col = Color3.fromHSV((now * 0.25) % 1, 0.75, 1)
        elseif s.color == "Health" then
            local hp, mx = LP.Character and LP.Character:GetAttribute("Health"), LP.Character and LP.Character:GetAttribute("MaxHealth")
            col = Color3.fromHSV(math.clamp((hp or 20) / math.max(mx or 20, 1), 0, 1) * 0.33, 0.75, 1)
        else col = T.accent end
        if s.enemy and Core.pickTarget and Core.alive() then
            local ok, t = pcall(Core.pickTarget, false)
            if ok and t and not t.friend then col = Color3.fromRGB(255, 72, 72) end
        end
        local tr = 1 - s.opacity / 100
        local L, W = s.size, s.thick
        local G = s.gap + rt.spread
        local style = s.style
        local b, ring = rt.bars, rt.ring
        local show = { true, true, true, true, false }
        if style == "Prestige" then show = { false, false, false, false, true }
        elseif style == "Dot" then show = { false, false, false, false, true }
        elseif style == "Plus + Dot" then show[5] = true
        elseif style == "T Shape" then show[1] = false
        elseif style == "Circle" then show = { false, false, false, false, false } end
        b[1].Size, b[1].Position = UDim2.fromOffset(W, L), UDim2.fromOffset(0, -(G + L / 2))
        b[2].Size, b[2].Position = UDim2.fromOffset(W, L), UDim2.fromOffset(0, G + L / 2)
        b[3].Size, b[3].Position = UDim2.fromOffset(L, W), UDim2.fromOffset(-(G + L / 2), 0)
        b[4].Size, b[4].Position = UDim2.fromOffset(L, W), UDim2.fromOffset(G + L / 2, 0)
        b[5].Size, b[5].Position = UDim2.fromOffset(W, W), UDim2.fromOffset(0, 0)
        for i = 1, 5 do
            b[i].Visible = show[i]
            b[i].BackgroundColor3, b[i].BackgroundTransparency = col, tr
            local stroke = b[i]:FindFirstChildOfClass("UIStroke")
            stroke.Enabled = s.outline
        end
        ring.Visible = style == "Circle" or style == "Prestige"
        rt.ringOut.Visible = style == "Prestige"
        if style == "Prestige" then
            local flashK = math.clamp(1 - (now - rt.hitT) / 0.4, 0, 1)
            local pulse = (math.sin(now * 3) + 1) * 0.5
            local r = (1.5 + pulse * 0.3 + flashK * 1.25) * 2.4
            local c2 = col:Lerp(Color3.new(1, 1, 1), flashK)
            ring.Size = UDim2.fromOffset(r * 2, r * 2)
            rt.ringOut.Size = UDim2.fromOffset(r * 2, r * 2)
            rt.ringStroke.Color, rt.ringStroke.Thickness = c2, 1.6
            rt.ringStroke.Transparency = 1 - math.min(1, (190 + 65 * math.max(pulse * 0.5, flashK)) / 255) * (s.opacity / 100)
            b[5].Size = UDim2.fromOffset(2.6, 2.6)
            b[5].BackgroundColor3 = c2
            local c5 = b[5]:FindFirstChildOfClass("UIStroke")
            if c5 then c5.Enabled = true end
        elseif ring.Visible then
            local d = (L + G) * 2
            ring.Size = UDim2.fromOffset(d, d)
            rt.ringStroke.Color, rt.ringStroke.Transparency, rt.ringStroke.Thickness = col, tr, W
        end
        local hm = s.hitmarker and math.clamp(1 - (now - rt.hitT) / 0.35, 0, 1) or 0
        for i, m in ipairs(rt.marks) do
            m.Visible = hm > 0
            if hm > 0 then
                local ang = math.rad(45 + 90 * (i - 1))
                local r = 7 + (1 - hm) * 8
                m.Position = UDim2.fromOffset(math.sin(ang) * r, -math.cos(ang) * r)
                m.BackgroundTransparency = 1 - hm
            end
        end
    end,
})

