newModule(movement, "Target Strafe", {
    build = function(mod, dd)
        addSlider(mod, dd, "range", "Range", 2, 6, 4.5, 0.5, " b")
        addSlider(mod, dd, "switch", "Switch Time", 300, 2000, 900, 100, " ms")
        addCheck(mod, dd, "randomize", "Randomize", true)
    end,
    tick = function(mod)
        local s, rt = mod.settings, mod.rt
        local t = Hub.lastTarget
        local active = t and os.clock() - (Hub.lastTargetAt or 0) < 1.5 and t.model.Parent and not Input.mouseFree
        if active then
            local d = (Core.aimPoint(t, "Body") - Controller.eye()).Magnitude
            active = d <= s.range
        end
        if not active then
            if rt.on then Core.virtual("left", false); Core.virtual("right", false); rt.on = false end
            return
        end
        rt.on = true
        local now = os.clock()
        if not rt.nextFlip or now >= rt.nextFlip then
            rt.dir = (rt.dir == "left") and "right" or "left"
            local base = s.switch / 1000
            rt.nextFlip = now + (s.randomize and rand(base * 0.6, base * 1.4) or base)
        end
        Core.virtual("left", rt.dir == "left")
        Core.virtual("right", rt.dir == "right")
    end,
    onToggle = function(mod, on)
        if not on and Input then Core.virtual("left", false); Core.virtual("right", false); mod.rt = {} end
    end,
})

newModule(visual, "Zoom", {
    build = function(mod, dd)
        addSlider(mod, dd, "level", "Zoom Level", 1.5, 8, 3, 0.5, "x")
        addSlider(mod, dd, "speed", "Smoothing", 4, 30, 14, 1)
    end,
    step = function(mod, dt)
        local s = mod.settings
        local held = true
        if mod.bind then
            local kc = Enum.KeyCode[mod.bind]
            if kc then held = UIS:IsKeyDown(kc)
            elseif mod.bind == "MouseButton2" then held = UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
            elseif mod.bind == "MouseButton3" then held = UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton3) end
        end
        local target = held and (1 / s.level) or 1
        Controller.zoom = Controller.zoom + (target - Controller.zoom) * math.min(1, s.speed * dt)
    end,
    onToggle = function(mod, on) if not on and Controller then Controller.zoom = 1 end end,
})

newModule(visual, "Damage Numbers", {
    build = function(mod, dd)
        addSlider(mod, dd, "size", "Size", 10, 28, 16, 1)
        addSlider(mod, dd, "time", "Duration", 0.4, 2, 0.9, 0.1, " s")
        addCheck(mod, dd, "mine", "Only My Hits", true)
        addCheck(mod, dd, "taken", "Show Damage Taken", false)
    end,
    onToggle = function(mod, on)
        if on then
            mod.rt.hook = addNetHandler("hurt", function(p)
                if not (mod.enabled and Hub.alive) then return end
                local s, me = mod.settings, myEntityId()
                local mineHit, taken = p.attacker == me, p.id == me
                if not (mineHit or (taken and s.taken) or (not s.mine and not taken)) then return end
                if not p.amount or p.amount < 0.05 or p.type == "fire" then return end
                local model
                if taken then
                    model = LP.Character
                else
                    for _, t in ipairs(Core.targets(false)) do if t.id == p.id then model = t.model; break end end
                end
                local adornee = model and (model:FindFirstChild("Head") or model:FindFirstChild("HumanoidRootPart"))
                if not adornee then return end
                local col = p.smash and Color3.fromRGB(255, 150, 60) or (p.crit and Color3.fromRGB(255, 226, 90) or (taken and Color3.fromRGB(255, 90, 90) or Color3.new(1, 1, 1)))
                local bb = new("BillboardGui", {
                    Adornee = adornee, Size = UDim2.fromOffset(140, 30), AlwaysOnTop = true, LightInfluence = 0,
                    StudsOffsetWorldSpace = Vector3.new(rand(-1, 1), 2.4, rand(-1, 1)),
                }, world)
                local tl = new("TextLabel", {
                    Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, FontFace = F_BOLD, TextSize = s.size,
                    TextColor3 = col, TextStrokeTransparency = 0.3,
                    Text = (taken and "-" or "") .. string.format("%.1f", p.amount) .. (p.smash and " SMASH" or ""),
                }, bb)
                local dur = s.time
                tween(bb, { StudsOffsetWorldSpace = bb.StudsOffsetWorldSpace + Vector3.new(0, 3.2, 0) }, dur, Enum.EasingStyle.Quad)
                tween(tl, { TextTransparency = 1, TextStrokeTransparency = 1 }, dur, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
                task.delay(dur + 0.05, function() bb:Destroy() end)
            end)
        else
            removeNetHandler("hurt", mod.rt.hook)
            mod.rt.hook = nil
        end
    end,
})

newModule(misc, "Hit Sound", {
    build = function(mod, dd)
        addSlider(mod, dd, "volume", "Volume", 0.1, 3, 1, 0.1)
        addSlider(mod, dd, "pitch", "Pitch", 0.5, 2, 1.1, 0.05)
