                local s = mod.settings
                local snd = new("Sound", { SoundId = "rbxasset://sounds/electronicpingshort.wav", Volume = s.volume, PlaybackSpeed = s.pitch * ((s.smashHigher and (p.smash or p.crit)) and 1.35 or 1) }, world)
