local HUDBG = Color3.fromRGB(12, 12, 16)
Hub.hudPos = Hub.hudPos or {}
local function hudPos(key, base)
    local o = Hub.hudPos[key]
    if o then return base + UDim2.fromOffset(o[1], o[2]) end
    return base
end

local function hudPill(parent, order)
    local f = new("Frame", { BackgroundColor3 = HUDBG, BackgroundTransparency = 0.32, BorderSizePixel = 0, AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.fromOffset(0, 26), LayoutOrder = order or 0 }, parent)
    corner(f, 5)
    new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, VerticalAlignment = Enum.VerticalAlignment.Center, Padding = UDim.new(0, 7), SortOrder = Enum.SortOrder.LayoutOrder }, f)
    new("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 9) }, f)
    return f
end
local function hudIcon(parent, key, order, size)
    local i = new("ImageLabel", { Size = UDim2.fromOffset(size or 11, size or 11), BackgroundTransparency = 1, Image = UI.ic[key] or "", LayoutOrder = order }, parent)
    return i
end
local function hudSep(parent, order)
    return new("Frame", { Size = UDim2.fromOffset(1, 14), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0.86, BorderSizePixel = 0, LayoutOrder = order }, parent)
end
local function hudText(parent, text, size, font, order)
    return new("TextLabel", { Size = UDim2.fromOffset(0, 26), AutomaticSize = Enum.AutomaticSize.X, BackgroundTransparency = 1, Text = text, FontFace = font or F_SEMI, TextSize = size, TextColor3 = T.bright, LayoutOrder = order }, parent)
end
local function gradeColor(v, lo, hi)
    local t = math.clamp((v - lo) / (hi - lo), 0, 1)
    return Color3.fromHSV(0.33 * (1 - t), 0.7, 1)
end

newModule(visual, "Target HUD", {
    desc = "Shows the current target's face, health and distance.",
    build = function(mod, dd)
        addSlider(mod, dd, "size", "Size", 80, 160, 100, 5, "%")
        addCheck(mod, dd, "head", "Show Head", true)
        addCheck(mod, dd, "flash", "Damage Flash", true)
    end,
    onToggle = function(mod, on)
        local rt = mod.rt
        if rt.root then rt.root:Destroy(); rt.root = nil end
        if not on then return end
        local root = new("Frame", { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0.5, 96), Size = UDim2.fromOffset(165, 52), BackgroundTransparency = 1, Visible = false }, hud)
        local sc = new("UIScale", { Scale = 0 }, root)
        local card = new("CanvasGroup", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = HUDBG, BackgroundTransparency = 0.28, BorderSizePixel = 0 }, root)
        corner(card, 6)
        local flash = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.fromRGB(235, 70, 70), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 5 }, card)
        local headBg = new("Frame", { Position = UDim2.fromOffset(6, 7), Size = UDim2.fromOffset(38, 38), BackgroundColor3 = Color3.fromRGB(14, 14, 14), BackgroundTransparency = 0.45, BorderSizePixel = 0 }, card)
        corner(headBg, 5)
        local head = new("ImageLabel", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Image = "" }, headBg)
        corner(head, 5)
        local initial = new("TextLabel", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "?", FontFace = F_BOLD, TextSize = 18, TextColor3 = T.sub }, headBg)
        rt.name = new("TextLabel", { Position = UDim2.fromOffset(52, 4), Size = UDim2.new(1, -100, 0, 20), BackgroundTransparency = 1, Text = "", FontFace = F_SEMI, TextSize = 15, TextColor3 = T.bright, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd }, card)
        rt.dist = new("TextLabel", { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -8, 0, 6), Size = UDim2.fromOffset(44, 14), BackgroundTransparency = 1, Text = "", FontFace = F_REG, TextSize = 11, TextColor3 = T.sub, TextXAlignment = Enum.TextXAlignment.Right }, card)
        local track = new("Frame", { Position = UDim2.fromOffset(52, 36), Size = UDim2.new(1, -108, 0, 9), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0.91, BorderSizePixel = 0 }, card)
        corner(track, 3)
        rt.trail = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.fromRGB(235, 85, 85), BackgroundTransparency = 0.5, BorderSizePixel = 0 }, track)
        corner(rt.trail, 3)
        rt.bar = new("Frame", { Size = UDim2.fromScale(1, 1), BorderSizePixel = 0 }, track)
        corner(rt.bar, 3)
        rt.barGrad = new("UIGradient", { Rotation = 90 }, rt.bar)
        rt.hpText = new("TextLabel", { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -8, 0, 31), Size = UDim2.fromOffset(46, 18), BackgroundTransparency = 1, Text = "", FontFace = F_SEMI, TextSize = 14, TextColor3 = T.bright, TextXAlignment = Enum.TextXAlignment.Right }, card)
        rt.root, rt.scale, rt.card, rt.flash, rt.head, rt.initial, rt.headBg = root, sc, card, flash, head, initial, headBg
        rt.shown, rt.p, rt.trailP, rt.lastHp, rt.hurtAt = false, 1, 1, nil, 0
    end,
    step = function(mod, dt)
        local rt, s = mod.rt, mod.settings
        if not rt.root then return end
        rt.root.Position = hudPos("target", UDim2.new(0.5, 0, 0.5, 96))
        local t = Hub.lastTarget
        if not (t and os.clock() - (Hub.lastTargetAt or 0) < 2.5 and t.model and t.model.Parent) then
            t = Core.best({ range = 8, fov = 70, playersOnly = false, part = "Chest", priority = "Angle", needHit = false })
        end
        local want = t ~= nil
        if want then rt.lostAt = nil elseif rt.shown and not rt.lostAt then rt.lostAt = os.clock() end
        if rt.shown and not want and os.clock() - (rt.lostAt or 0) > 0.6 then
            rt.shown = false
            tween(rt.scale, { Scale = 0 }, 0.28, Enum.EasingStyle.Back, Enum.EasingDirection.In)
            task.delay(0.3, function() if not rt.shown and rt.root then rt.root.Visible = false end end)
        end
        if want and not rt.shown then
            rt.shown = true
            rt.root.Visible = true
            tween(rt.scale, { Scale = s.size / 100 }, 0.45, Enum.EasingStyle.Back)
        elseif rt.shown then
            rt.scale.Scale = rt.scale.Scale + (s.size / 100 - rt.scale.Scale) * math.min(1, dt * 10)
        end
        if not t then return end
        local hp = t.model:GetAttribute("Health") or t.health
        local frac = math.clamp(hp / math.max(t.maxHealth, 1), 0, 1)
        if rt.id ~= t.id then
            rt.id, rt.p, rt.trailP, rt.lastHp = t.id, frac, frac, hp
            rt.name.Text = t.name
            rt.initial.Text = (t.name or "?"):sub(1, 1):upper()
            if s.head and t.plr then
                rt.head.Image = "rbxthumb://type=AvatarHeadShot&id=" .. t.plr.UserId .. "&w=150&h=150"
                rt.initial.Visible = false
            else
                rt.head.Image = ""
                rt.initial.Visible = true
            end
        end
        rt.headBg.Visible = s.head
        if rt.lastHp and hp < rt.lastHp - 0.05 then rt.hurtAt = os.clock() end
        rt.lastHp = hp
        rt.p = rt.p + (frac - rt.p) * math.min(1, dt * 12)
        if frac >= rt.trailP then rt.trailP = frac
        elseif os.clock() - rt.hurtAt > 0.4 then rt.trailP = rt.trailP + (frac - rt.trailP) * math.min(1, dt * 3.5) end
        rt.dist.Text = string.format("%dm", math.floor(t.dist + 0.5))
        rt.trail.Size = UDim2.fromScale(math.max(rt.trailP, 0), 1)
        rt.bar.Size = UDim2.fromScale(math.max(rt.p, 0.03), 1)
        local c = rt.p > 0.6 and T.accent or (rt.p > 0.3 and Color3.fromRGB(240, 170, 60) or Color3.fromRGB(235, 75, 75))
        rt.barGrad.Color = ColorSequence.new(c:Lerp(Color3.new(1, 1, 1), 0.25), c:Lerp(Color3.new(0, 0, 0), 0.3))
        rt.hpText.Text = tostring(math.ceil(hp))
        rt.hpText.TextColor3 = rt.p > 0.6 and T.bright or c
        local fa = s.flash and math.clamp(1 - (os.clock() - rt.hurtAt) / 0.35, 0, 1) or 0
        rt.flash.BackgroundTransparency = 1 - fa * 0.22
    end,
})

newModule(visual, "Hud", {
    hidden = true,
    desc = "Watermark, FPS / ping / clock pills and the enabled-modules list.",
    build = function(mod, dd)
        addMode(mod, dd, "position", "Position", { "Top Left", "Top Center" }, "Top Left")
        addCheck(mod, dd, "watermark", "Watermark", true)
        addCheck(mod, dd, "fps", "FPS", true)
        addCheck(mod, dd, "ping", "Ping", true)
        addCheck(mod, dd, "clock", "Clock", false)
        addCheck(mod, dd, "moduleList", "Module List", true)
        addCheck(mod, dd, "showBinds", "Show Binds", false)
        addSlider(mod, dd, "maxEntries", "Max Entries", 4, 24, 12, 1)
    end,
    onToggle = function(mod, on)
        local rt = mod.rt
        for _, k in ipairs({ "top", "list" }) do if rt[k] then rt[k]:Destroy(); rt[k] = nil end end
        rt.entries = {}
        if not on then return end
        local top = new("Frame", { Size = UDim2.fromOffset(0, 0), AutomaticSize = Enum.AutomaticSize.XY, BackgroundTransparency = 1 }, hud)
        new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 5) }, top)
        rt.top = top

        local wm = hudPill(top, 1)
        wm.Size = UDim2.fromOffset(0, 32)
        rt.wmLogo = hudIcon(wm, "logo", 1, 28)
        hudSep(wm, 2)
        rt.wmText = hudText(wm, "Prestige Client", 15, F_SEMI, 3)
        rt.wm = wm

        local row = new("Frame", { Size = UDim2.fromOffset(0, 26), AutomaticSize = Enum.AutomaticSize.X, BackgroundTransparency = 1, LayoutOrder = 2 }, top)
        new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 5) }, row)
        local function stat(order, iconKey, unit)
            local p = hudPill(row, order)
            local ic = hudIcon(p, iconKey, 1, 12)
            hudSep(p, 2)
            local v = hudText(p, "0", 15, F_SEMI, 3)
            local u = hudText(p, unit, 10, F_REG, 4)
            u.TextColor3 = T.sub
            return { frame = p, icon = ic, value = v, unit = u }
        end
        rt.fpsP, rt.pingP, rt.clockP = stat(1, "fps", "fps"), stat(2, "latency", "ms"), stat(3, "clock", "")
        rt.fpsV, rt.pingV = 60, 40
        rt.list = new("Frame", { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -10, 0, 88), Size = UDim2.fromOffset(0, 0), AutomaticSize = Enum.AutomaticSize.XY, BackgroundTransparency = 1 }, hud)
        new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, HorizontalAlignment = Enum.HorizontalAlignment.Right, Padding = UDim.new(0, 2) }, rt.list)
        Hub.listDirty = true
    end,
    step = function(mod, dt)
        local rt, s = mod.rt, mod.settings
        if not rt.top then return end
        local now = os.clock()

        if s.position == "Top Center" then
            rt.top.AnchorPoint, rt.top.Position = Vector2.new(0.5, 0), hudPos("hud", UDim2.new(0.5, 0, 0, 10))
        else
            rt.top.AnchorPoint, rt.top.Position = Vector2.zero, hudPos("hud", UDim2.fromOffset(168, 10))
        end

        rt.wm.Visible = s.watermark
        if s.watermark then
            local pulse = (math.sin(now * 3.1415926 * 0.5 * 2 / 2) * 0.5 + 0.5)
            rt.wmText.TextColor3 = T.accent:Lerp(Color3.new(1, 1, 1), 0.3)
            rt.wmText.TextTransparency = 0.33 - 0.2 * pulse
            rt.wmLogo.ImageColor3 = T.accent
        end

        rt.fpsV = rt.fpsV + ((1 / math.max(dt, 1e-3)) - rt.fpsV) * math.min(1, dt * 1.5)
        rt.acc = (rt.acc or 0) + dt
        if rt.acc >= 0.4 then
            rt.acc = 0
            local ping = rt.pingV
            pcall(function() ping = game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue() end)
            rt.pingV = ping
            rt.fpsP.value.Text = tostring(math.floor(rt.fpsV + 0.5))
            rt.fpsP.value.TextColor3 = gradeColor(-rt.fpsV, -144, -30)
            rt.pingP.value.Text = tostring(math.floor(ping + 0.5))
            rt.pingP.value.TextColor3 = gradeColor(ping, 40, 250)
            rt.clockP.value.Text = os.date("%H:%M")
        end
        rt.fpsP.icon.ImageColor3, rt.pingP.icon.ImageColor3, rt.clockP.icon.ImageColor3 = T.accent, T.accent, T.accent
        rt.fpsP.frame.Visible, rt.pingP.frame.Visible, rt.clockP.frame.Visible = s.fps, s.ping, s.clock
        rt.fpsP.value.Parent.Parent.Visible = s.fps or s.ping or s.clock
        rt.list.Visible = s.moduleList
        rt.list.Position = hudPos("list", UDim2.new(1, -10, 0, 88))

        if not (Hub.listDirty or rt.lastBinds ~= s.showBinds or rt.lastMax ~= s.maxEntries or now - (rt.lastBuild or 0) > 1) then return end
        Hub.listDirty, rt.lastBinds, rt.lastMax, rt.lastBuild = false, s.showBinds, s.maxEntries, now
        local want, order = {}, {}
        for _, m in ipairs(Hub.order) do
            if m.enabled and not m.hidden then
                local text = m.name
                if s.showBinds and m.bind then text = text .. "  " .. pretty(m.bind) end
                want[m.name] = text
                order[#order + 1] = m.name
            end
        end
        table.sort(order, function(a, b)
            local wa, wb = textWidth(want[a]), textWidth(want[b])
            if wa ~= wb then return wa > wb end
            return a < b
        end)
        for i = #order, math.floor(s.maxEntries) + 1, -1 do want[order[i]] = nil; order[i] = nil end
        for name, e in pairs(rt.entries) do
            if not want[name] and not e.leaving then
                e.leaving = true
                tween(e.pill, { GroupTransparency = 1, Position = UDim2.new(0, 14, 0, 0) }, 0.22)
                tween(e.holder, { Size = UDim2.fromOffset(e.w, 0) }, 0.24)
                task.delay(0.26, function() if rt.entries[name] == e then e.holder:Destroy(); rt.entries[name] = nil end end)
            end
        end
        local h, sat, val = T.accent:ToHSV()
        for i, name in ipairs(order) do
            local text = want[name]
            local e = rt.entries[name]
            if e and e.leaving then e.holder:Destroy(); rt.entries[name] = nil; e = nil end
            local col = Color3.fromHSV((h + (i - 1) * 0.014) % 1, math.min(sat, 0.62), 1)
            if not e then
                local w = textWidth(text) + 14
                local holder = new("Frame", { Size = UDim2.fromOffset(w, 0), BackgroundTransparency = 1, LayoutOrder = i }, rt.list)
                local pill = new("CanvasGroup", { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, 12, 0, 0), Size = UDim2.new(1, 0, 0, 22), BackgroundColor3 = HUDBG, BackgroundTransparency = 0.32, BorderSizePixel = 0, GroupTransparency = 1 }, holder)
                corner(pill, 4)
                local lb = new("TextLabel", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = text, FontFace = F_SEMI, TextSize = 13, TextColor3 = col, TextXAlignment = Enum.TextXAlignment.Center }, pill)
                e = { holder = holder, pill = pill, label = lb, w = w, text = text }
                rt.entries[name] = e
                tween(holder, { Size = UDim2.fromOffset(w, 22) }, 0.22)
                tween(pill, { GroupTransparency = 0, Position = UDim2.new(1, 0, 0, 0) }, 0.3, Enum.EasingStyle.Quint)

                pill.BackgroundColor3 = HUDBG:Lerp(col, 0.4)
                tween(pill, { BackgroundColor3 = HUDBG }, 0.5)
            elseif e.text ~= text then
                e.text, e.label.Text, e.w = text, text, textWidth(text) + 14
                tween(e.holder, { Size = UDim2.fromOffset(e.w, 22) }, 0.2)
            end
            e.holder.LayoutOrder = i
            tween(e.label, { TextColor3 = col }, 0.3)
        end
    end,
})

newModule(visual, "Notifications", {
    desc = "Shows a toast when you turn a module on or off.",
    build = function(mod, dd)
        addSlider(mod, dd, "time", "Duration", 1, 5, 2.2, 0.1, " s")
    end,
    step = function(mod)
        if mod.rt.stack then mod.rt.stack.Position = hudPos("notify", UDim2.new(1, -16, 1, -90)) end
    end,
    onToggle = function(mod, on)
        local rt = mod.rt
        if rt.stack then rt.stack:Destroy(); rt.stack = nil end
        Hub.moduleToast = nil
        if not on then return end
        local stack = new("Frame", { AnchorPoint = Vector2.new(1, 1), Position = UDim2.new(1, -16, 1, -90), Size = UDim2.fromOffset(240, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1 }, hud)
        new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, VerticalAlignment = Enum.VerticalAlignment.Bottom, HorizontalAlignment = Enum.HorizontalAlignment.Right, Padding = UDim.new(0, 6) }, stack)
        rt.stack, rt.n = stack, 0
        rt.stackBase = UDim2.new(1, -16, 1, -90)
        Hub.moduleToast = function(m, v)
            if Hub.quiet or m.hidden or m == mod then return end
            rt.n += 1
            local holder = new("Frame", { Size = UDim2.fromOffset(240, 0), BackgroundTransparency = 1, LayoutOrder = rt.n }, stack)
            local card = new("CanvasGroup", { Size = UDim2.new(1, 0, 0, 42), Position = UDim2.fromOffset(40, 0), BackgroundColor3 = HUDBG, BackgroundTransparency = 0.25, BorderSizePixel = 0, GroupTransparency = 1 }, holder)
            corner(card, 6)
            local dot = new("Frame", { Position = UDim2.fromOffset(12, 13), Size = UDim2.fromOffset(16, 16), BackgroundColor3 = v and Color3.fromRGB(93, 222, 128) or Color3.fromRGB(235, 90, 90), BorderSizePixel = 0 }, card)
            corner(dot, 8)
            new("TextLabel", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = v and "\xE2\x9C\x93" or "\xE2\x9C\x95", FontFace = F_BOLD, TextSize = 11, TextColor3 = Color3.new(0.05, 0.05, 0.07) }, dot)
            new("TextLabel", { Position = UDim2.fromOffset(38, 5), Size = UDim2.new(1, -46, 0, 18), BackgroundTransparency = 1, Text = m.name, FontFace = F_SEMI, TextSize = 14, TextColor3 = T.bright, TextXAlignment = Enum.TextXAlignment.Left }, card)
            new("TextLabel", { Position = UDim2.fromOffset(38, 22), Size = UDim2.new(1, -46, 0, 14), BackgroundTransparency = 1, Text = v and "Enabled" or "Disabled", FontFace = F_REG, TextSize = 11, TextColor3 = T.sub, TextXAlignment = Enum.TextXAlignment.Left }, card)
            tween(holder, { Size = UDim2.fromOffset(240, 42) }, 0.2)
            tween(card, { GroupTransparency = 0, Position = UDim2.fromOffset(0, 0) }, 0.32, Enum.EasingStyle.Quint)
            task.delay(mod.settings.time, function()
                if not card.Parent then return end
                tween(card, { GroupTransparency = 1, Position = UDim2.fromOffset(40, 0) }, 0.25)
                tween(holder, { Size = UDim2.fromOffset(240, 0) }, 0.28)
                task.delay(0.3, function() holder:Destroy() end)
            end)
        end
    end,
})

newModule(visual, "Hit Effect", {
    desc = "Spawns a burst of glowing particles when you hit someone.",
    build = function(mod, dd)
        addMode(mod, dd, "style", "Style", { "Glow", "Pop" }, "Glow")
        addSlider(mod, dd, "amount", "Amount", 1, 20, 8, 1)
        addSlider(mod, dd, "duration", "Duration", 0.5, 4, 1.4, 0.1, " s")
        addSlider(mod, dd, "size", "Size", 0.2, 1.6, 0.7, 0.1)
        addCheck(mod, dd, "gravity", "Gravity", true)
        addCheck(mod, dd, "taken", "Also When Hit", false)
    end,
    onToggle = function(mod, on)
        removeNetHandler("hurt", mod.rt.hook)
        mod.rt.hook = nil
        if not on then return end
        mod.rt.hook = addNetHandler("hurt", function(p)
            if not (mod.enabled and Hub.alive) then return end
            local s, me = mod.settings, myEntityId()
            if not (p.attacker == me or (s.taken and p.id == me)) then return end
            if p.type == "fire" or (p.amount or 0) < 0.05 then return end
            local model
            if p.id == me then model = LP.Character
            else for _, t in ipairs(Core.targets(false)) do if t.id == p.id then model = t.model; break end end end
            local root = model and (model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart or model:FindFirstChild("Head"))
            if not root then return end
            local part = new("Part", { Anchored = true, CanCollide = false, CanQuery = false, CanTouch = false, Transparency = 1, Size = Vector3.new(1.4, 2.2, 1.4), CFrame = CFrame.new(root.Position) }, workspace.CurrentCamera)
            local c0 = T.accent:Lerp(Color3.new(1, 1, 1), 0.35)
            local c1 = T.accent:Lerp(Color3.new(0, 0, 0), 0.25)
            local pop = s.style == "Pop"
            local e = new("ParticleEmitter", {
                Texture = UI.ic[pop and "hitpop" or "hitglow"], Rate = 0, Lifetime = NumberRange.new(s.duration * 0.6, s.duration),
                Speed = NumberRange.new(pop and 4 or 0.5, pop and 9 or 3), SpreadAngle = Vector2.new(180, 180), Shape = Enum.ParticleEmitterShape.Box,
                Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, s.size, s.size * 0.3), NumberSequenceKeypoint.new(1, pop and s.size * 0.3 or 0) }),
                Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(0.6, 0.25), NumberSequenceKeypoint.new(1, 1) }),
                Color = ColorSequence.new(c0, c1), LightEmission = 1, LightInfluence = 0, Drag = pop and 3 or 0.4,
                Acceleration = Vector3.new(0, s.gravity and -(pop and 14 or 3) or 0, 0), RotSpeed = NumberRange.new(-60, 60), Rotation = NumberRange.new(0, 360),
            }, part)
            e:Emit(math.floor(s.amount * (pop and 2 or 3)))
            task.delay(s.duration + 0.6, function() part:Destroy() end)
        end)
    end,
})

newModule(visual, "Jump Circles", {
    desc = "Draws an expanding ring under you every time you jump.",
    build = function(mod, dd)
        addSlider(mod, dd, "size", "Size", 3, 14, 7, 0.5, " b")
        addSlider(mod, dd, "time", "Duration", 0.3, 2, 0.8, 0.1, " s")
    end,
    step = function(mod)
        local rt, s = mod.rt, mod.settings
        local st = Controller and Controller.state
        if not st then return end
        local grounded = st.onGround
        if rt.wasGround and not grounded and (st.vel and st.vel.Y > 0.05) then
            local root = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
            if root then
                local rp = RaycastParams.new()
                rp.FilterType = Enum.RaycastFilterType.Exclude
                rp.FilterDescendantsInstances = { LP.Character, workspace.CurrentCamera }
                local hit = workspace:Raycast(root.Position, Vector3.new(0, -10, 0), rp)
                local pos = hit and hit.Position + Vector3.new(0, 0.06, 0) or root.Position - Vector3.new(0, 3, 0)
                local ring = new("Part", {
                    Anchored = true, CanCollide = false, CanQuery = false, CanTouch = false, CastShadow = false, Shape = Enum.PartType.Cylinder,
                    Material = Enum.Material.Neon, Color = T.accent, Transparency = 0.35, Size = Vector3.new(0.05, 1, 1),
                    CFrame = CFrame.new(pos) * CFrame.Angles(0, 0, math.pi / 2),
                }, workspace.CurrentCamera)
                local d = s.size * 3
                tween(ring, { Size = Vector3.new(0.05, d, d), Transparency = 1 }, s.time, Enum.EasingStyle.Quad)
                task.delay(s.time + 0.1, function() ring:Destroy() end)
            end
        end
        rt.wasGround = grounded
    end,
})

newModule(visual, "Cooldown Indicator", {
    desc = "A slim bar under the crosshair for attack charge and item cooldowns.",
    build = function(mod, dd)
        addSlider(mod, dd, "width", "Width", 40, 160, 90, 5, " px")
        addSlider(mod, dd, "offset", "Offset", 10, 80, 34, 2, " px")
        addCheck(mod, dd, "items", "Item Cooldowns", true)
        addCheck(mod, dd, "hideFull", "Hide When Full", true)
    end,
    onToggle = function(mod, on)
        local rt = mod.rt
        if rt.root then rt.root:Destroy(); rt.root = nil end
        if not on then return end
        local root = new("CanvasGroup", { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(90, 6), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0.88, BorderSizePixel = 0, GroupTransparency = 1 }, hud)
        corner(root, 3)
        rt.fill = new("Frame", { Size = UDim2.fromScale(0, 1), BorderSizePixel = 0 }, root)
        corner(rt.fill, 3)
        rt.grad = new("UIGradient", { Rotation = 90 }, rt.fill)
        rt.root, rt.p, rt.vis = root, 1, 1
    end,
    step = function(mod, dt)
        local rt, s = mod.rt, mod.settings
        if not rt.root then return end
        local frac, itemBar = 1, false
        if Core.alive() and not Input.mouseFree then
            local held = Hands.held()
            local kind = Core.heldKind()
            if s.items and held and (kind == "pearl" or kind == "windcharge") then
                local ok, cd = pcall(Hands.cooldownFraction, held.id)
                ident()
                if ok and type(cd) == "number" and cd > 0 then frac, itemBar = 1 - cd, true end
            end
            if not itemBar then
                local ok, v = pcall(Hands.strength, 0)
                ident()
                if ok and type(v) == "number" then frac = math.clamp(v, 0, 1) end
            end
        end
        rt.p = rt.p + (frac - rt.p) * math.min(1, dt * 18)
        local show = not (s.hideFull and frac >= 0.995)
        rt.vis = rt.vis + ((show and 0 or 1) - rt.vis) * math.min(1, dt * 12)
        rt.root.GroupTransparency = rt.vis
        rt.root.Size = UDim2.fromOffset(s.width, 6)
        rt.root.Position = hudPos("cooldown", UDim2.new(0.5, 0, 0.5, s.offset))
        rt.fill.Size = UDim2.fromScale(rt.p, 1)
        local c = itemBar and Color3.fromRGB(240, 170, 60) or T.accent
        rt.grad.Color = ColorSequence.new(c:Lerp(Color3.new(1, 1, 1), 0.25), c:Lerp(Color3.new(0, 0, 0), 0.3))
    end,
})

