newModule(misc, "FPS Booster", {
    desc = "Turns off shadows and heavy post effects for more frames.",
    build = function(mod, dd)
        addCheck(mod, dd, "shadows", "Disable Shadows", true)
        addCheck(mod, dd, "effects", "Disable Post Effects", true)
        addCheck(mod, dd, "particles", "Hide Particles", false)
    end,
    onToggle = function(mod, on)
        local rt, s = mod.rt, mod.settings
        local L = game:GetService("Lighting")
        if on then
            rt.snap = { shadows = L.GlobalShadows, fx = {}, pf = {} }
            if s.shadows then L.GlobalShadows = false end
            if s.effects then
                for _, e in ipairs(L:GetChildren()) do
                    if (e:IsA("BloomEffect") or e:IsA("SunRaysEffect") or e:IsA("DepthOfFieldEffect") or e:IsA("BlurEffect")) and not e.Name:find("Prestige") and e.Enabled then
                        rt.snap.fx[e] = true
                        e.Enabled = false
                    end
                end
            end
            if s.particles then
                for _, d in ipairs(workspace:GetDescendants()) do
                    if d:IsA("ParticleEmitter") and d.Enabled and not d:FindFirstAncestorWhichIsA("Camera") then rt.snap.pf[d] = true; d.Enabled = false end
                end
            end
        elseif rt.snap then
            L.GlobalShadows = rt.snap.shadows
            for e in pairs(rt.snap.fx) do if e.Parent then e.Enabled = true end end
            for d in pairs(rt.snap.pf) do if d.Parent then d.Enabled = true end end
        end
    end,
})

do
    local BLOCKS = Config.BLOCK
    local ARROW_BOW, ARROW_XBOW = 9.0, 9.45
    local DRAG, GRAV = 0.99, 0.15

    local function hotSlot(pred)
        for i = 1, 9 do
            local it = Hands.inv.hotbar[i]
            if it then
                local ok, d = pcall(Items.def, it)
                if ok and d and pred(it, d) then ident(); return i, it end
            end
        end
        ident()
    end
    local function flameLevel(it) local ok, v = pcall(Items.ench, it, "flame"); ident(); return ok and tonumber(v) or 0 end
    local function weaponSlot(kind, needFlame)
        local best, bestIt
        for i = 1, 9 do
            local it = Hands.inv.hotbar[i]
            if it then
                local ok, d = pcall(Items.def, it)
                if ok and d and d.kind == kind then
                    if not needFlame or flameLevel(it) > 0 then
                        if not best or (kind == "crossbow" and it.loaded and not bestIt.loaded) then best, bestIt = i, it end
                    end
                end
            end
        end
        ident()
        return best, bestIt
    end
    local function ray(origin, dir, dist, filter)
        local r = World.blockRay(origin, dir, dist, filter)
        ident()
        return r
    end
    local function dirTo(point)
        local v = point - Controller.eye()
        return v.Magnitude > 0.01 and v.Unit or Controller.look()
    end
    local function cellPoint(c, up) return Vector3.new(c.X + 0.5, c.Y + (up or 0.5), c.Z + 0.5) end

    local function heightAt(theta, speed, dist)
        local vx, vy, x, y = speed * math.cos(theta), speed * math.sin(theta), 0, 0
        for _ = 1, 240 do
            local nx = x + vx
            if nx >= dist then return y + vy * ((dist - x) / vx) end
            x, y = nx, y + vy
            vx *= DRAG
            vy = vy * DRAG - GRAV
            if y < -600 then return nil end
        end
    end

    local function solve(from, target, speed, arc)
        local dx, dz = target.X - from.X, target.Z - from.Z
        local dist = math.sqrt(dx * dx + dz * dz)
        if dist < 0.05 then return nil end
        local want = target.Y - from.Y
        local roots, prevT, prevE = {}, nil, nil
        for deg = -80, 85, 0.5 do
            local th = math.rad(deg)
            local h = heightAt(th, speed, dist)
            local e = h and (h - want)
            if e and prevE and (e > 0) ~= (prevE > 0) then
                local lo, hi, elo = prevT, th, prevE
                for _ = 1, 28 do
                    local mid = (lo + hi) / 2
                    local hm = heightAt(mid, speed, dist)
                    if not hm then break end
                    local em = hm - want
                    if (em > 0) == (elo > 0) then lo, elo = mid, em else hi = mid end
                end
                roots[#roots + 1] = (lo + hi) / 2
            end
            prevT, prevE = th, e
        end
        if #roots == 0 then return nil end
        table.sort(roots)
        local th = (arc >= 50 and #roots > 1) and roots[#roots] or roots[1]
        local hx, hz = dx / dist, dz / dist
        return Vector3.new(hx * math.cos(th), math.sin(th), hz * math.cos(th)), th
    end

    local function pickGround(s)
        local eye = Controller.eye()
        if s.place == "Target Feet" then
            local t = Core.best({ range = 4.4, fov = 360, playersOnly = true, part = "Body", priority = "Distance", needHit = false })
            if t then
                local hit = ray(t.feet + Vector3.new(0, 1.2, 0), Vector3.new(0, -1, 0), 4, { "Solid" })
                if hit then return hit, t end
            end
            return nil, nil
        end
        local hit = ray(eye, Controller.look(), 4.5, { "Solid" })
        if hit and hit.normal.Y >= 0.5 then return hit end
    end

    Hub.cartSolve = solve
    local function cartModule(name, kind, desc)
        local isBow = kind == "bow"
        local speedFull = isBow and ARROW_BOW or ARROW_XBOW
        newModule(combat, name, {
            desc = desc,
            build = function(mod, dd)
                addSlider(mod, dd, "delay", "Switch Delay", 0, 10, 2, 1, " ticks")
                addMode(mod, dd, "place", "Place At", { "Target Feet", "Crosshair" }, "Target Feet")
                if isBow then addSlider(mod, dd, "minCharge", "Min Charge", 3, 20, 10, 1, " ticks") end
                addSlider(mod, dd, "arc", "Arc", 0, 100, 20, 5)
                addCheck(mod, dd, "needFlame", "Require Flame", true)
                addSlider(mod, dd, "overload", "Overload", 1, 4, 1, 1, " carts")
                addSlider(mod, dd, "olMin", "Overload Delay Min", 0, 500, 50, 10, " ms")
                addSlider(mod, dd, "olMax", "Overload Delay Max", 0, 500, 150, 10, " ms")
                addSlider(mod, dd, "minHealth", "Min Health", 1, 19, 8, 1, " hp")
                addCheck(mod, dd, "silent", "Silent Aim", true)
                if not isBow then addCheck(mod, dd, "autoLoad", "Auto Load", true) end
                addCheck(mod, dd, "swapBack", "Swap Back", true)
            end,
            onBind = function(mod)
                local rt, s = mod.rt, mod.settings
                if rt.stage or not Core.alive() then return end
                local hp = LP.Character and LP.Character:GetAttribute("Health") or 20
                if hp < s.minHealth then return notify("Health too low for a cart") end
                local rail, cart = Core.findSlot("rail"), Core.findSlot("tntcart")
                if not rail then return notify("No rail in your hotbar") end
                if not cart then return notify("No TNT minecart in your hotbar") end
                local weapon = weaponSlot(kind, s.needFlame)
                if not weapon then return notify(s.needFlame and ("No flame " .. kind .. " in your hotbar") or ("No " .. kind .. " in your hotbar")) end
                if not Hands.hasItem("arrow") then ident(); return notify("No arrows") end
                ident()
                local ground, target = pickGround(s)
                if not ground then return notify(s.place == "Target Feet" and "No target within reach" or "Look at the ground within reach") end
                if not Core.claim(mod) then return end
                mod.rt = {
                    stage = "rail", n = 0, rail = rail, cart = cart, weapon = weapon, origin = Hands.inv.selected,
                    groundPos = ground.pos, cell = ground.cell + Vector3.new(0, 1, 0), placed = 0, wait = 0,
                }
            end,
            tick = function(mod)
                local rt, s = mod.rt, mod.settings
                if not rt.stage then return end
                if not Core.alive() or Input.mouseFree then
                    Core.virtual("use", false)
                    mod.rt = {}
                    Core.release(mod)
                    return
                end
                local function sel(slot) if Hands.inv.selected ~= slot then Core.select(slot) end end
                local function arrowDir(speed)
                    local from = Controller.eye() * BLOCKS - Vector3.new(0, 0.3, 0)
                    local to = cellPoint(rt.cell, 0.4) * BLOCKS
                    return solve(from, to, speed, s.arc)
                end
                if rt.stage == "rail" then
                    sel(rt.rail)
                    rt.n += 1
                    if rt.n > s.delay then
                        if s.silent or s.place == "Target Feet" then Core.aim(dirTo(rt.groundPos)) end
                        pcall(Core.press, "use")
                        ident()
                        rt.stage, rt.n = "cart", 0
                    end
                elseif rt.stage == "cart" then
                    sel(rt.cart)
                    rt.n += 1
                    if rt.n > s.delay and os.clock() >= rt.wait then
                        if s.silent or s.place == "Target Feet" then Core.aim(dirTo(cellPoint(rt.cell, 0.2))) end
                        pcall(Core.press, "use")
                        ident()
                        rt.placed += 1
                        if rt.placed >= s.overload then rt.stage, rt.n = "arm", 0
                        else rt.wait = os.clock() + rand(math.min(s.olMin, s.olMax), math.max(s.olMin, s.olMax)) / 1000 end
                    end
                elseif rt.stage == "arm" then
                    sel(rt.weapon)
                    rt.n += 1
                    if rt.n > s.delay then
                        local it = Hands.inv.hotbar[rt.weapon]
                        rt.stage, rt.n = (isBow and "draw") or ((it and it.loaded) and "fire" or "load"), 0
                    end
                elseif rt.stage == "draw" then
                    sel(rt.weapon)
                    rt.n += 1
                    Core.virtual("use", true)
                    local using = Hands.using
                    local charge = (using and using.kind == "bow") and (Controller.tickCount - using.start) or 0
                    if charge >= s.minCharge then
                        local power = Combat.bowPower(math.min(charge, 20))
                        local dir = arrowDir(speedFull * power)

                        if not dir and charge < 20 then return end
                        if not dir then Core.virtual("use", false); notify("Cart is out of range"); rt.stage, rt.n = "back", 0; return end
                        Core.aim(dir)
                        Core.virtual("use", false)
                        rt.stage, rt.n = "back", 0
                    elseif rt.n > 70 then
                        Core.virtual("use", false)
                        notify("Couldn't draw the bow")
                        rt.stage, rt.n = "back", 0
                    end
                elseif rt.stage == "load" then
                    sel(rt.weapon)
                    rt.n += 1
                    local it = Hands.inv.hotbar[rt.weapon]
                    if not s.autoLoad then notify("Crossbow isn't loaded"); rt.stage, rt.n = "back", 0
                    elseif it and it.loaded then Core.virtual("use", false); rt.stage, rt.n = "fire", 0
                    elseif rt.n > 80 then Core.virtual("use", false); notify("Couldn't load the crossbow"); rt.stage, rt.n = "back", 0
                    else Core.virtual("use", true) end
                elseif rt.stage == "fire" then
                    sel(rt.weapon)
                    rt.n += 1
                    if rt.n > s.delay then
                        local dir = arrowDir(speedFull)
                        if not dir then notify("Cart is out of range"); rt.stage, rt.n = "back", 0; return end
                        Core.aim(dir)
                        pcall(Core.press, "use")
                        ident()
                        rt.stage, rt.n = "back", 0
                    end
                elseif rt.stage == "back" then
                    rt.n += 1
                    if rt.n > s.delay then
                        if s.swapBack and rt.origin ~= rt.weapon then Core.select(rt.origin) end
                        mod.rt = {}
                        Core.release(mod)
                    end
                end
            end,
            onToggle = function(mod, on)
                if not on then
                    pcall(Core.virtual, "use", false)
                    local rt = mod.rt
                    if rt.stage and rt.origin and Hands.inv.selected ~= rt.origin then pcall(Core.select, rt.origin) end
                end
            end,
        })
    end
    cartModule("Auto Cart", "bow", "Rail, TNT cart, then a flaming bow shot on the exact angle to set it off.")

    local function flightPoints(dir, cartBox)
        local start = Controller.eye() - Vector3.new(0, 0.1, 0)
        local v = dir * (ARROW_XBOW / BLOCKS)
        local p, pts = start, {}
        for _ = 1, 60 do
            local n = math.max(1, math.ceil(v.Magnitude / 0.25))
            for _ = 1, n do
                p = p + v / n
                pts[#pts + 1] = p
                if cartBox(p) then return pts, true end
            end
            v = Vector3.new(v.X * DRAG, v.Y * DRAG - GRAV / BLOCKS, v.Z * DRAG)
            if p.Y < -300 then break end
        end
        return pts, false
    end

    newModule(combat, "Xbow Cart", {
        desc = "Rail, TNT cart, a flint & steel fire in the bolt's path, then a crossbow shot through it.",
        build = function(mod, dd)
            addSlider(mod, dd, "delay", "Switch Delay", 0, 10, 2, 1, " ticks")
            addMode(mod, dd, "place", "Place At", { "Target Feet", "Crosshair" }, "Target Feet")
            addSlider(mod, dd, "minHealth", "Min Health", 1, 19, 8, 1, " hp")
            addCheck(mod, dd, "silent", "Silent Aim", true)
            addCheck(mod, dd, "autoLoad", "Auto Load", true)
            addCheck(mod, dd, "swapBack", "Swap Back", true)
        end,
        onBind = function(mod)
            local rt, s = mod.rt, mod.settings
            if rt.stage or not Core.alive() then return end
            local hp = LP.Character and LP.Character:GetAttribute("Health") or 20
            if hp < s.minHealth then return notify("Health too low for a cart") end
            local rail, cart = Core.findSlot("rail"), Core.findSlot("tntcart")
            local fns = Core.findSlot("igniter")
            local xb = weaponSlot("crossbow", false)
            if not rail then return notify("No rail in your hotbar") end
            if not cart then return notify("No TNT minecart in your hotbar") end
            if not fns then return notify("No flint & steel in your hotbar") end
            if not xb then return notify("No crossbow in your hotbar") end
            if not Hands.hasItem("arrow") then ident(); return notify("No arrows") end
            ident()
            local ground = pickGround(s)
            if not ground then return notify(s.place == "Target Feet" and "No target within reach" or "Look at the ground within reach") end
            if not Core.claim(mod) then return end
            local it = Hands.inv.hotbar[xb]
            mod.rt = {
                stage = (it and it.loaded) and "rail" or "load", n = 0, rail = rail, cart = cart, fns = fns, xb = xb, origin = Hands.inv.selected,
                groundPos = ground.pos, cell = ground.cell + Vector3.new(0, 1, 0),
            }
        end,
        tick = function(mod)
            local rt, s = mod.rt, mod.settings
            if not rt.stage then return end
            if not Core.alive() or Input.mouseFree then
                Core.virtual("use", false)
                mod.rt = {}
                Core.release(mod)
                return
            end
            local function sel(slot) if Hands.inv.selected ~= slot then Core.select(slot) end end
            local function cartPoint() return Vector3.new(rt.cell.X + 0.5, rt.cell.Y + 0.45, rt.cell.Z + 0.5) end
            local function shotDir()
                return solve(Controller.eye() * BLOCKS - Vector3.new(0, 0.3, 0), cartPoint() * BLOCKS, ARROW_XBOW, 0)
            end
            local function inCart(p)
                return p.X > rt.cell.X + 0.01 and p.X < rt.cell.X + 0.99 and p.Y > rt.cell.Y + 0.0625 and p.Y < rt.cell.Y + 0.7625 and p.Z > rt.cell.Z + 0.01 and p.Z < rt.cell.Z + 0.99
            end

            local function findFireCell()
                local dir = shotDir()
                if not dir then return nil end
                local eye = Controller.eye()
                local pts, hits = flightPoints(dir, inCart)
                if not hits then return nil end
                local seen = {}
                for _, p in ipairs(pts) do
                    local c = Vector3.new(math.floor(p.X), math.floor(p.Y), math.floor(p.Z))
                    local key = c.X .. "," .. c.Y .. "," .. c.Z
                    if not seen[key] then
                        seen[key] = true
                        local centre = c + Vector3.new(0.5, 0.5, 0.5)
                        if (centre - eye).Magnitude > 1.3 and (centre - eye).Magnitude <= 4.4
                            and not (c == rt.cell or c == rt.cell + Vector3.new(0, 1, 0)) then

                            local down = ray(Vector3.new(centre.X, c.Y + 1.4, centre.Z), Vector3.new(0, -1, 0), 2.2, { "Solid" })
                            if down and down.cell == c - Vector3.new(0, 1, 0) and down.normal.Y >= 0.5 then

                                local top = Vector3.new(centre.X, c.Y, centre.Z)
                                local aim = ray(eye, (top - eye).Unit, 4.5, { "Solid", "Webs", "Rails" })
                                if aim and aim.cell + Vector3.new(math.round(aim.normal.X), math.round(aim.normal.Y), math.round(aim.normal.Z)) == c then
                                    return c, top
                                end
                            end
                        end
                    end
                end
            end
            if rt.stage == "load" then
                sel(rt.xb)
                rt.n += 1
                local it = Hands.inv.hotbar[rt.xb]
                if not s.autoLoad then notify("Crossbow isn't loaded"); rt.stage, rt.n = "back", 0
                elseif it and it.loaded then Core.virtual("use", false); rt.stage, rt.n = "rail", 0
                elseif rt.n > 80 then Core.virtual("use", false); notify("Couldn't load the crossbow"); rt.stage, rt.n = "back", 0
                else Core.virtual("use", true) end
            elseif rt.stage == "rail" then
                sel(rt.rail)
                rt.n += 1
                if rt.n > s.delay then
                    if s.silent or s.place == "Target Feet" then Core.aim(dirTo(rt.groundPos)) end
                    pcall(Core.press, "use")
                    ident()
                    rt.stage, rt.n = "cart", 0
                end
            elseif rt.stage == "cart" then
                sel(rt.cart)
                rt.n += 1
                if rt.n > s.delay then
                    if s.silent or s.place == "Target Feet" then Core.aim(dirTo(cellPoint(rt.cell, 0.2))) end
                    pcall(Core.press, "use")
                    ident()
                    rt.stage, rt.n = "fire", 0
                end
            elseif rt.stage == "fire" then
                sel(rt.fns)
                rt.n += 1
                if rt.n > s.delay then
                    local c, top = findFireCell()
                    if not c then notify("No spot for the fire in the bolt's path"); rt.stage, rt.n = "back", 0; return end
                    rt.fire = c
                    Core.aim(dirTo(top))
                    pcall(Core.press, "use")
                    ident()
                    rt.stage, rt.n = "shoot", 0
                end
            elseif rt.stage == "shoot" then
                sel(rt.xb)
                rt.n += 1
                if rt.n > s.delay then
                    local dir = shotDir()
                    if not dir then notify("Cart is out of range"); rt.stage, rt.n = "back", 0; return end
                    Core.aim(dir)
                    pcall(Core.press, "use")
                    ident()
                    rt.stage, rt.n = "back", 0
                end
            elseif rt.stage == "back" then
                rt.n += 1
                if rt.n > s.delay then
                    if s.swapBack and rt.origin ~= rt.xb then Core.select(rt.origin) end
                    mod.rt = {}
                    Core.release(mod)
                end
            end
        end,
        onToggle = function(mod, on)
            if not on then
                pcall(Core.virtual, "use", false)
                local rt = mod.rt
                if rt.stage and rt.origin and Hands.inv.selected ~= rt.origin then pcall(Core.select, rt.origin) end
            end
        end,
    })
end

newModule(visual, "Trajectories", {
    desc = "Draws the flight path of your arrows and ender pearls, with a landing marker that turns red on a hit.",
    build = function(mod, dd)
        addCheck(mod, dd, "bow", "Bow", true)
        addCheck(mod, dd, "xbow", "Crossbow", true)
        addCheck(mod, dd, "pearl", "Ender Pearl", true)
        addCheck(mod, dd, "marker", "Landing Marker", true)
        addCheck(mod, dd, "hits", "Highlight Hits", true)
        addCheck(mod, dd, "friends", "Ignore Friends", true)
        addSlider(mod, dd, "length", "Length", 20, 90, 60, 5, " ticks")
    end,
    onToggle = function(mod, on)
        local rt = mod.rt
        if rt.holder then rt.holder:Destroy(); rt.holder = nil end
        if rt.marker then rt.marker:Destroy(); rt.marker = nil end
        if not on then return end
        local N = 260
        local holder = new("Part", { Anchored = true, CanCollide = false, CanQuery = false, CanTouch = false, Transparency = 1, Size = Vector3.one, CFrame = CFrame.new() }, workspace.CurrentCamera)
        rt.atts, rt.beams = {}, {}
        for i = 1, N do rt.atts[i] = new("Attachment", {}, holder) end
        for i = 1, N - 1 do
            rt.beams[i] = new("Beam", {
                Attachment0 = rt.atts[i], Attachment1 = rt.atts[i + 1], FaceCamera = true, LightEmission = 1, LightInfluence = 0,
                Segments = 1, Width0 = 0.1, Width1 = 0.1, Enabled = false, Texture = "", Transparency = NumberSequence.new(0.2),
            }, holder)
        end
        rt.marker = new("Part", { Anchored = true, CanCollide = false, CanQuery = false, CanTouch = false, CastShadow = false, Shape = Enum.PartType.Ball, Material = Enum.Material.Neon, Size = Vector3.new(0.9, 0.9, 0.9), Transparency = 1 }, workspace.CurrentCamera)
        rt.holder, rt.acc = holder, 0
    end,
    step = function(mod, dt)
        local rt, s = mod.rt, mod.settings
        if not rt.holder then return end
        rt.acc += dt
        if rt.acc < 1 / 30 then return end
        rt.acc = 0
        local function hide()
            for _, b in ipairs(rt.beams) do b.Enabled = false end
            rt.marker.Transparency = 1
        end
        if not (Core.alive() and not Input.mouseFree) then return hide() end
        local kind = Core.heldKind()
        local speed
        local grav = 0.15
        if kind == "pearl" and s.pearl then
            speed, grav = 4.5, 0.09
        elseif kind == "bow" and s.bow then
            local using = Hands.using
            if not (using and using.kind == "bow") then return hide() end
            speed = 9 * Combat.bowPower(math.min(Controller.tickCount - using.start, 20))
        elseif kind == "crossbow" and s.xbow then
            local held = Hands.held()
            if not (held and held.loaded) then return hide() end
            speed = 9.45
        else
            return hide()
        end
        if speed < 0.5 then return hide() end

        local BL = Config.BLOCK
        local pos = Controller.eye() * BL - Vector3.new(0, 0.3, 0)
        local vel = Controller.look() * speed

        local sv = Controller.state and Controller.state.vel
        if sv then vel = vel + Vector3.new(sv.X, Controller.state.onGround and 0 or sv.Y, sv.Z) * BL end
        local targets = {}
        for _, t in ipairs(Core.frameTargets()) do
            if not (s.friends and t.friend) then targets[#targets + 1] = (t.feet + Vector3.new(0, 0.9, 0)) * BL end
        end
        local pts, landing, hit = {}, nil, false
        local eyeS = pos
        for _ = 1, math.floor(s.length) do
            local seg = vel
            local len = seg.Magnitude
            local r = World.blockRay(pos / BL, seg.Unit, len / BL + 0.02, { "Solid" })
            ident()
            local reach = r and math.min(len, r.dist * BL) or len
            local n = math.max(1, math.ceil(reach / 2.2))
            for k = 1, n do
                local p = pos + seg.Unit * (reach * k / n)
                if (p - eyeS).Magnitude > 3 then pts[#pts + 1] = p end
                for _, c in ipairs(targets) do
                    if (p - c).Magnitude < 1.9 then hit, landing = true, p; break end
                end
                if hit then break end
            end
            if hit then break end
            if r then landing = r.pos * BL; pts[#pts + 1] = landing; break end
            pos = pos + vel
            vel = Vector3.new(vel.X * 0.99, vel.Y * 0.99 - grav, vel.Z * 0.99)
        end
        local col = (hit and s.hits) and Color3.fromRGB(255, 80, 80) or T.accent
        for i = 1, #rt.beams do
            local b = rt.beams[i]
            if pts[i + 1] then
                rt.atts[i].WorldPosition = pts[i]
                rt.atts[i + 1].WorldPosition = pts[i + 1]
                b.Enabled = true
                b.Color = ColorSequence.new(col)
                b.Transparency = NumberSequence.new(0.2 + 0.6 * (i / #pts))
            else
                b.Enabled = false
            end
        end
        if landing and s.marker then
            rt.marker.Position = landing
            rt.marker.Color = col
            rt.marker.Transparency = 0.25
        else
            rt.marker.Transparency = 1
        end
    end,
})

newModule(PNX.mace, "Pearl Catch", {
    desc = "One key: throws an ender pearl up, then a wind charge to catch it. Angles and timing are tunable.",
    build = function(mod, dd)
        addSlider(mod, dd, "pearlAngle", "Pearl Angle", 0, 90, 48, 1, "\xC2\xB0")
        addSlider(mod, dd, "windAngle", "Wind Charge Angle", 0, 90, 40, 1, "\xC2\xB0")
        addSlider(mod, dd, "delay", "Wind Charge Delay", 50, 300, 120, 10, " ms")
        addSlider(mod, dd, "movingDelay", "Moving Delay", 50, 300, 80, 10, " ms")
        addCheck(mod, dd, "silent", "Silent Aim", true)
        addCheck(mod, dd, "swapBack", "Swap Back", true)
    end,
    onBind = function(mod)
        local rt = mod.rt
        if rt.stage or not Core.alive() then return end
        local pearl, wind = Core.findSlot("pearl"), Core.findSlot("windcharge")
        if not pearl then return notify("No ender pearl in your hotbar") end
        if not wind then return notify("No wind charge in your hotbar") end
        local pc, wc = Hands.cooldownFraction(Hands.inv.hotbar[pearl].id), Hands.cooldownFraction(Hands.inv.hotbar[wind].id)
        ident()
        if pc > 0 then return notify("Pearl is on cooldown") end
        if wc > 0 then return notify("Wind charge is on cooldown") end
        if not Core.claim(mod) then return end
        mod.rt = { stage = "pearl", pearl = pearl, wind = wind, origin = Hands.inv.selected, n = 0 }
    end,
    tick = function(mod)
        local rt, s = mod.rt, mod.settings
        if not rt.stage then return end
        if not Core.alive() or Input.mouseFree then mod.rt = {}; Core.release(mod); return end

        local function throwAt(deg)
            if not s.silent then return end
            local look = Controller.look()
            local h = Vector3.new(look.X, 0, look.Z)
            h = h.Magnitude > 0.01 and h.Unit or Vector3.new(0, 0, -1)
            local a = math.rad(deg)
            Core.aim(Vector3.new(h.X * math.cos(a), math.sin(a), h.Z * math.cos(a)))
        end
        local function sel(slot) if Hands.inv.selected ~= slot then Core.select(slot) end end
        if rt.stage == "pearl" then
            sel(rt.pearl)
            throwAt(s.pearlAngle)
            pcall(Core.press, "use")
            ident()
            local st = Controller.state
            local moving = st and st.vel and Vector3.new(st.vel.X, 0, st.vel.Z).Magnitude > 0.05
            rt.wait = math.max(1, math.floor((moving and s.movingDelay or s.delay) / 50 + 0.5))
            rt.stage, rt.n = "gap", 0
        elseif rt.stage == "gap" then
            rt.n += 1
            if rt.n >= rt.wait then rt.stage, rt.n = "wind", 0 end
        elseif rt.stage == "wind" then
            sel(rt.wind)
            throwAt(s.windAngle)
            pcall(Core.press, "use")
            ident()
            rt.stage, rt.n = "back", 0
        elseif rt.stage == "back" then
            rt.n += 1
            if rt.n >= 1 then
                if s.swapBack and rt.origin ~= rt.wind then Core.select(rt.origin) end
                mod.rt = {}
                Core.release(mod)
            end
        end
    end,
    onToggle = function(mod, on)
        if not on then
            local rt = mod.rt
            if rt.stage and rt.origin and Hands.inv.selected ~= rt.origin then pcall(Core.select, rt.origin) end
        end
    end,
})

