    local function flat(spec)
        local f = { clock = spec.clock, bright = spec.bright, exp = spec.exp, stars = spec.stars, sat = spec.sat, con = spec.con, cb = spec.cb,
            bloomI = spec.bloomI, bloomS = spec.bloomS, bloomT = spec.bloomT, rays = spec.rays, amb = spec.amb, out = spec.out, tint = spec.tint }
        for k, v in pairs(spec.atm) do f[k] = v end
        return f
    end

    local function camFolder() return workspace.CurrentCamera end

    local function makeLayer(L, density)
        local cam = camFolder()
        local part = new("Part", {
            Anchored = true, CanCollide = false, CanQuery = false, CanTouch = false, CastShadow = false, Transparency = 1,
            Size = Vector3.new(L.diam, L.diam, L.diam), CFrame = CFrame.new(cam.CFrame.Position + Vector3.new(0, L.shift, 0)),
        }, cam)
        local s = L.size
        local e = new("ParticleEmitter", {
            Texture = SMOKE, Rate = L.rate * density, Lifetime = NumberRange.new(L.life * 0.55, L.life * 1.3),
            Speed = NumberRange.new(L.speed * 0.4, L.speed), SpreadAngle = Vector2.new(180, 180),
            Shape = Enum.ParticleEmitterShape.Sphere, ShapeStyle = Enum.ParticleEmitterShapeStyle.Surface,
            ShapeInOut = Enum.ParticleEmitterShapeInOut.Outward, LockedToPart = true,
            Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, s * 0.85, s * 0.3), NumberSequenceKeypoint.new(1, s * 1.15, s * 0.3) }),
            Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.18, L.tr, 0.1),
                NumberSequenceKeypoint.new(0.82, L.tr, 0.1), NumberSequenceKeypoint.new(1, 1),
            }),
            Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, L.col0), ColorSequenceKeypoint.new(0.5, L.col1), ColorSequenceKeypoint.new(1, L.col0) }),
            LightEmission = L.emit, LightInfluence = L.infl, RotSpeed = NumberRange.new(-5, 5), Rotation = NumberRange.new(0, 360),
            Acceleration = Vector3.zero, Drag = 0, ZOffset = 0, Orientation = Enum.ParticleOrientation.FacingCamera,
        }, part)
        e:Emit(math.clamp(math.floor(L.rate * density * L.life * 0.4), 6, 160))
        return { part = part, emitter = e, spec = L, base = L.emit }
    end

    local function bolt(a, b, off, levels)
        local pts = { a, b }
        for lvl = 1, levels do
            local nxt = {}
            for i = 1, #pts - 1 do
                local p, q = pts[i], pts[i + 1]
                local mid = (p + q) / 2
                local dir = (q - p)
                local rnd = Vector3.new(rand(-1, 1), rand(-1, 1), rand(-1, 1))
                local perp = dir:Cross(rnd)
                if perp.Magnitude > 1e-3 then mid += perp.Unit * off * rand(-1, 1) end
                nxt[#nxt + 1] = p
                nxt[#nxt + 1] = mid
            end
            nxt[#nxt + 1] = pts[#pts]
            pts = nxt
            off *= 0.52
        end
        return pts
    end

    local function addBeams(holder, pts, w0, w1, glowW, list)
        local atts = {}
        for i, p in ipairs(pts) do
            atts[i] = new("Attachment", {}, holder)
            atts[i].WorldPosition = p
        end
        for i = 1, #pts - 1 do
            local t0, t1 = (i - 1) / (#pts - 1), i / (#pts - 1)
            local function mk(width0, width1, col, em)
                local b = new("Beam", {
                    Attachment0 = atts[i], Attachment1 = atts[i + 1], FaceCamera = true, LightEmission = em, LightInfluence = 0,
                    Segments = 1, Width0 = width0, Width1 = width1, Color = ColorSequence.new(col), Transparency = NumberSequence.new(1),
                    Texture = "", TextureMode = Enum.TextureMode.Stretch,
                }, holder)
                list[#list + 1] = b
                return b
            end
            local lw0, lw1 = w0 + (w1 - w0) * t0, w0 + (w1 - w0) * t1
            mk(lw0 * glowW, lw1 * glowW, Color3.fromRGB(150, 175, 255), 1).Name = "g"
            mk(lw0, lw1, Color3.fromRGB(240, 246, 255), 1).Name = "c"
        end
    end

    newModule(visual, "Custom Sky", {
        build = function(mod, dd)
            addMode(mod, dd, "sky", "Sky", MODES, "Nebula")
            addSlider(mod, dd, "clouds", "Cloud Density", 20, 200, 100, 10, "%")
            addCheck(mod, dd, "animate", "Animate Time", true)
            addCheck(mod, dd, "lightning", "Lightning (Storm)", true)
            addSlider(mod, dd, "freq", "Lightning Gap", 2, 20, 6, 1, " s")
