                for _, k in ipairs({ "ClockTime", "Brightness", "Ambient", "OutdoorAmbient", "ExposureCompensation" }) do rt.snap.L[k] = Lighting[k] end
                rt.atm = Lighting:FindFirstChildOfClass("Atmosphere")
                rt.sky = Lighting:FindFirstChildOfClass("Sky")
                rt.rays = Lighting:FindFirstChildOfClass("SunRaysEffect")
                if rt.atm then for _, k in ipairs({ "Density", "Offset", "Color", "Decay", "Glare", "Haze" }) do rt.snap.A[k] = rt.atm[k] end end
                if rt.sky then for _, k in ipairs({ "SkyboxBk", "SkyboxDn", "SkyboxFt", "SkyboxLf", "SkyboxRt", "SkyboxUp", "StarCount", "CelestialBodiesShown" }) do rt.snap.S[k] = rt.sky[k] end end
                if rt.rays then rt.snap.R = { Intensity = rt.rays.Intensity, Spread = rt.rays.Spread, Enabled = rt.rays.Enabled } end
                rt.cc = new("ColorCorrectionEffect", { Name = "PrestigeSkyCC" }, Lighting)
                rt.bloom = new("BloomEffect", { Name = "PrestigeSkyBloom", Intensity = 0, Size = 24, Threshold = 1 }, Lighting)
                if rt.sky then
                    for _, k in ipairs({ "SkyboxBk", "SkyboxDn", "SkyboxFt", "SkyboxLf", "SkyboxRt", "SkyboxUp" }) do rt.sky[k] = "" end
                    rt.sky.CelestialBodiesShown = true
                end

                rt.cur = {
                    clock = Lighting.ClockTime, bright = Lighting.Brightness, exp = Lighting.ExposureCompensation, stars = rt.snap.S.StarCount or 0,
                    sat = 0, con = 0, cb = 0, bloomI = 0, bloomS = 24, bloomT = 1, rays = rt.rays and rt.rays.Intensity or 0,
                    amb = Lighting.Ambient, out = Lighting.OutdoorAmbient, tint = Color3.new(1, 1, 1),
                    Density = rt.snap.A.Density or 0.2, Offset = rt.snap.A.Offset or 0, Glare = rt.snap.A.Glare or 0, Haze = rt.snap.A.Haze or 0,
                    Color = rt.snap.A.Color or Color3.new(1, 1, 1), Decay = rt.snap.A.Decay or Color3.new(1, 1, 1),
                }
                rt.layers, rt.old, rt.bolts, rt.t0 = {}, {}, {}, os.clock()
                rt.gameClouds = workspace:FindFirstChild("MCClouds")
            else

                if rt.snap then
                    pcall(function()
                        for k, v in pairs(rt.snap.L) do Lighting[k] = v end
                        if rt.atm then for k, v in pairs(rt.snap.A) do rt.atm[k] = v end end
                        if rt.sky then for k, v in pairs(rt.snap.S) do rt.sky[k] = v end end
                        if rt.rays and rt.snap.R.Intensity then for k, v in pairs(rt.snap.R) do rt.rays[k] = v end end
                    end)
                end
                for _, k in ipairs({ "cc", "bloom", "rainPart" }) do if rt[k] then rt[k]:Destroy() end end
                for _, l in ipairs(rt.layers or {}) do l.part:Destroy() end
                for _, l in ipairs(rt.old or {}) do l.part:Destroy() end
                for _, b in ipairs(rt.bolts or {}) do b.holder:Destroy() end
                if rt.gameClouds and rt.gameClouds.Parent then
                    pcall(function()
                        if rt.gameClouds:IsA("BasePart") then rt.gameClouds.LocalTransparencyModifier = 0 end
                        for _, d in ipairs(rt.gameClouds:GetDescendants()) do
                            if d:IsA("Texture") or d:IsA("Decal") then d.LocalTransparencyModifier = 0 end
                        end
                    end)
                end
                mod.rt = {}
            end
        end,
        step = function(mod, dt)
            local rt, s = mod.rt, mod.settings
            if not rt.cur then return end
            local cam = camFolder()
            if not cam then return end
            local now = os.clock()
            local spec = SKYS[s.sky] or SKYS.Nebula
            local tgt = flat(spec)

            local density = s.clouds / 100
            if rt.mode ~= s.sky or rt.density ~= density then
                local fresh = rt.mode == nil
                rt.mode, rt.density = s.sky, density
                for _, l in ipairs(rt.layers) do
                    l.emitter.Enabled = false
                    l.dieAt = now + (fresh and 0 or 12)

                    rt.old[#rt.old + 1] = l
                end
                rt.layers = {}
                for _, L in ipairs(spec.layers) do rt.layers[#rt.layers + 1] = makeLayer(L, density) end
            end
            for i = #rt.old, 1, -1 do
                local l = rt.old[i]
                l.part.CFrame = CFrame.new(cam.CFrame.Position + Vector3.new(0, l.spec.shift, 0)) * CFrame.Angles(0, (now - rt.t0) * 0.006, 0)
                if now >= l.dieAt then l.part:Destroy(); table.remove(rt.old, i) end
            end

            local a = 1 - math.exp(-dt * 1.4)
            local cur = rt.cur
            local tclock = tgt.clock
            if s.animate and spec.amp > 0 then tclock += math.sin((now - rt.t0) * 0.045) * spec.amp end
            for _, k in ipairs(NUMS) do
                local goal = (k == "clock") and tclock or tgt[k]
                if goal ~= nil then cur[k] = cur[k] + (goal - cur[k]) * a end
            end
            for _, k in ipairs(COLS) do cur[k] = cur[k]:Lerp(tgt[k], a) end

            local flash = 0
            if s.sky == "Storm" and s.lightning then
                if not rt.nextStrike then rt.nextStrike = now + 1.5 end
                if now >= rt.nextStrike then
                    rt.nextStrike = now + s.freq * rand(0.5, 1.5)
                    local function strike()
                        local cf = cam.CFrame
                        local yaw = math.atan2(-cf.LookVector.X, -cf.LookVector.Z) + rand(-0.85, 0.85)
                        local dist = rand(320, 650)
                        local top = cf.Position + Vector3.new(-math.sin(yaw) * dist, dist * rand(0.4, 0.8), -math.cos(yaw) * dist)
                        local gp = RaycastParams.new()
                        gp.FilterType = Enum.RaycastFilterType.Exclude
                        gp.FilterDescendantsInstances = { cam, LP.Character }
                        local hit = workspace:Raycast(top, Vector3.new(0, -900, 0), gp)
                        local bottom = hit and hit.Position or (cf.Position + Vector3.new(top.X - cf.Position.X, -30, top.Z - cf.Position.Z))
                        local holder = new("Part", { Anchored = true, CanCollide = false, CanQuery = false, CanTouch = false, Transparency = 1, Size = Vector3.one, CFrame = CFrame.new(top) }, cam)
                        local beams = {}
                        local main = bolt(top, bottom, 110, 6)
                        addBeams(holder, main, 10, 3, 3.4, beams)
                        for _ = 1, math.random(2, 4) do
                            local i = math.random(math.floor(#main * 0.25), math.floor(#main * 0.8))
                            local from = main[i]
                            local to = from + Vector3.new(rand(-1, 1) * 160, -rand(120, 240), rand(-1, 1) * 160)
                            addBeams(holder, bolt(from, to, 50, 4), 3.4, 0.8, 3, beams)
                        end
                        local pulses = { { 0, 1 }, { 0.09, 0.6 }, { 0.17, 0.95 } }
                        if math.random() < 0.5 then pulses[#pulses + 1] = { 0.34, 0.5 } end
                        rt.bolts[#rt.bolts + 1] = { holder = holder, beams = beams, t0 = now, pulses = pulses }
                    end
                    strike()
                    if math.random() < 0.3 then task.delay(rand(0.2, 0.5), function() if mod.enabled and rt.cur then pcall(strike) end end) end
                end
            end
            for i = #rt.bolts, 1, -1 do
                local b = rt.bolts[i]
                local age = now - b.t0
                local env = 0
                for _, p in ipairs(b.pulses) do
                    local x = age - p[1]
                    if x >= 0 then
                        local rise = math.min(1, x / 0.025)
                        local fall = math.clamp(1 - x / 0.2, 0, 1) ^ 1.6
                        env = math.max(env, p[2] * rise * fall)
                    end
                end

                local glow = math.clamp(1 - age / 0.9, 0, 1) ^ 2.2 * 0.55
                flash = math.max(flash, math.max(env, glow))
                for _, bm in ipairs(b.beams) do
                    if bm.Name == "g" then bm.Transparency = NumberSequence.new(1 - env * 0.55)
                    else bm.Transparency = NumberSequence.new(1 - env * 0.98) end
                end
                if age > 1 then b.holder:Destroy(); table.remove(rt.bolts, i) end
            end
            rt.flash = (rt.flash or 0) + (flash - (rt.flash or 0)) * math.min(1, dt * 40)
            local f = rt.flash

            Lighting.ClockTime = cur.clock % 24
            Lighting.Brightness = cur.bright + 0.9 * f
            Lighting.ExposureCompensation = cur.exp + 0.22 * f
            Lighting.Ambient = cur.amb:Lerp(C3(185, 198, 255), f * 0.45)
            Lighting.OutdoorAmbient = cur.out:Lerp(C3(190, 205, 255), f * 0.45)
            if rt.atm then
                rt.atm.Density, rt.atm.Offset, rt.atm.Glare, rt.atm.Haze = cur.Density, cur.Offset, cur.Glare, cur.Haze
                rt.atm.Color = cur.Color:Lerp(C3(190, 205, 255), f * 0.35)
                rt.atm.Decay = cur.Decay:Lerp(C3(150, 170, 235), f * 0.35)
            end
            if rt.sky then rt.sky.StarCount = math.floor(cur.stars + 0.5); rt.sky.CelestialBodiesShown = spec.cel end
            rt.cc.TintColor = cur.tint:Lerp(C3(215, 225, 255), f * 0.5)
            rt.cc.Saturation, rt.cc.Contrast, rt.cc.Brightness = cur.sat, cur.con, cur.cb + 0.03 * f
            rt.bloom.Intensity, rt.bloom.Size, rt.bloom.Threshold = cur.bloomI + 0.45 * f, cur.bloomS, math.max(0.5, cur.bloomT - 0.15 * f)
            if rt.rays then rt.rays.Enabled = cur.rays > 0.01; rt.rays.Intensity = cur.rays end

            local base = CFrame.new(cam.CFrame.Position)
            for _, l in ipairs(rt.layers) do
                l.part.CFrame = base * CFrame.new(0, l.spec.shift, 0) * CFrame.Angles(0, (now - rt.t0) * 0.006, 0)
                if s.sky == "Storm" then l.emitter.LightEmission = math.min(1, f * 0.9) end
            end

            if rt.gameClouds and rt.gameClouds.Parent then
                local hide = s.hideClouds and 1 or 0
                if rt.hid ~= hide then
                    rt.hid = hide
                    pcall(function()
                        if rt.gameClouds:IsA("BasePart") then rt.gameClouds.LocalTransparencyModifier = hide end
                        for _, d in ipairs(rt.gameClouds:GetDescendants()) do
                            if d:IsA("Texture") or d:IsA("Decal") then d.LocalTransparencyModifier = hide end
                        end
                    end)
                end
            end
        end,
    })
end

function collect()
    local t = { version = 4, menuKey = Hub.menuKey, alpha = Hub.alpha, scale = Hub.getScale and Hub.getScale() or 1, theme = UI.TH.idx, friends = Hub.friends or {}, hud = Hub.hudPos or {}, cosmetics = Hub.cos or {}, accent = { math.floor(T.accent.R * 255 + .5), math.floor(T.accent.G * 255 + .5), math.floor(T.accent.B * 255 + .5) }, modules = {}, panels = {} }
    for _, m in ipairs(Hub.order) do
        if not m.def.noSave then t.modules[m.name] = { enabled = m.enabled, bind = m.bind, open = m.open, settings = m.settings } end
    end
    return t
end

local function applyConfig(t)
    if type(t) ~= "table" then return end
    if t.menuKey then Hub.menuKey = t.menuKey; Hub.renderMenuKey() end
    if t.theme and V3THEMES[t.theme] then UI.TH.set(t.theme) end
    if type(t.friends) == "table" then Hub.friends = t.friends end
    if type(t.hud) == "table" then Hub.hudPos = t.hud end
    if type(t.cosmetics) == "table" and Hub.cos then
        for k, v in pairs(t.cosmetics) do Hub.cos[k] = v end
        if Hub.cosRefresh then pcall(Hub.cosRefresh) end
    end
    if t.accent then Hub.setColor(Color3.fromRGB(t.accent[1], t.accent[2], t.accent[3])) end
    if t.alpha then Hub.setAlpha(t.alpha) end
    if t.scale then Hub.setScale(t.scale) end
    for n, d in pairs(t.modules or {}) do
        local m = Hub.modules[n]
        if m and not m.def.noSave then
            m.bind, m.open = d.bind, d.open == true
            for k, val in pairs(d.settings or {}) do if m.setters[k] then m.setters[k](val) end end
            m.render()
            setEnabled(m, d.enabled == true)
        end
    end
end

Hub.collect = collect
Hub.applyConfig = function(t)
    local q = Hub.quiet
    Hub.quiet = true
    local ok, err = pcall(applyConfig, t)
    Hub.quiet = q
    if not ok then warn("[Prestige] config: " .. tostring(err)) end
end

do
    local TH, B, R, T_, mixc, rectF, hit, ic = UI.TH, UI.B, UI.R, UI.T, UI.mixc, UI.rectF, UI.hit, UI.ic
    local F_SERIF = UI.F_SERIF
    local V2 = Vector2.new

    local function header(frame, title, sub)
        T_(frame, title, { x = 260, y = 26, w = 600, h = 44, size = 34, font = F_SEMI, slot = 12 })
        T_(frame, sub, { x = 260, y = 70, w = 600, h = 22, size = 17, slot = 13 })
    end

    local function scrollArea(frame, x, y, w, h)
