    end

    local function button(parent, text, x, y, w, h, o)
        o = o or {}
        local b = new("Frame", { Position = o.pos or UDim2.fromOffset(x, y), Size = UDim2.fromOffset(w, h), AnchorPoint = o.anchor or V2(0, 0), BorderSizePixel = 0, ZIndex = o.z or 5 }, parent)
        corner(b, o.r or 5)
        local st = new("UIStroke", { Thickness = 1 }, b)
        local hot, sel = false, false
        local api = { frame = b }
        local rb = B(b, "bg", function()
            if o.primary then local c1, a1 = TH.col(9); local c2 = TH.col(9); return c1:Lerp(Color3.new(1, 1, 1), hot and 0.16 or 0), a1 end
            local c1, a1 = TH.col(sel and 29 or 6)
            local c2, a2 = TH.col(7)
            return mixc(c1, a1, c2, a2, hot and 1 or 0)
        end)
        local rs = B(st, "str", function()
            if o.primary then return TH.col(9) end
            local c1, a1 = TH.col(sel and 25 or 14)
            local c2, a2 = TH.col(o.hotStroke or 9)
            return mixc(c1, a1, c2, a2, hot and 1 or 0)
        end)
        local lab = T_(b, text, { sz = UDim2.fromScale(1, 1), size = o.size or 14, ax = Enum.TextXAlignment.Center, z = (o.z or 5) + 1 })
        local rt = B(lab, "txt", function()
            if o.primary then local c, a = TH.col(9); return Color3.new(1, 1, 1), 1 end
            if o.hotText and hot then return Color3.new(1, 0.5, 0.5), 1 end
            local c1, a1 = TH.col(sel and 12 or 13)
            local c2, a2 = TH.col(12)
            return mixc(c1, a1, c2, a2, hot and 1 or 0)
        end)
        local btn = hit(b, (o.z or 5) + 2)
        btn.MouseEnter:Connect(function() hot = true; rb(); rs(); rt() end)
        btn.MouseLeave:Connect(function() hot = false; rb(); rs(); rt() end)
        if o.onClick then btn.MouseButton1Click:Connect(o.onClick) end
        function api.setSel(v) sel = v; rb(); rs(); rt() end
        function api.setText(t) lab.Text = t end
        api.btn = btn
        return api
    end
    UI.button = button

    local function glassCard(parent, x, y, w, h, z)
        return rectF(parent, x, y, w, h, 12, 23, 15, { z = z or 4, fmul = 1.4 })
    end

    do
        local page = UI.gen["Settings"]
        local f = page.frame
        header(f, "Settings", "Appearance and keybinds")
        local c1 = glassCard(f, 260, 100, 260, 358)
        T_(c1, "Main color", { x = 20, y = 18, w = 220, h = 22, size = 18, slot = 12, z = 6 })
        T_(c1, "Accent for trails, effects and HUD", { x = 20, y = 42, w = 220, h = 34, size = 14, slot = 30, wrap = true, ay = Enum.TextYAlignment.Top, z = 6 })

        local pk = rectF(c1, 20, 80, 220, 258, 8, 6, 14, { z = 6 })
        local hue, sat, val, alpha = 245, 0.55, 0.99, 1
        do
            local r, g, b = 0x85 / 255, 0x76 / 255, 0xFC / 255
            local mx, mn = math.max(r, g, b), math.min(r, g, b)
            local d = mx - mn
            local h
            if d == 0 then h = 0 elseif mx == r then h = ((g - b) / d) % 6 elseif mx == g then h = (b - r) / d + 2 else h = (r - g) / d + 4 end
            hue, sat, val = h * 60, mx == 0 and 0 or d / mx, mx
        end
        local sv = new("Frame", { Position = UDim2.fromOffset(12, 12), Size = UDim2.fromOffset(170, 170), BorderSizePixel = 0, ZIndex = 7, ClipsDescendants = true }, pk)
        corner(sv, 4)
        local white = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, ZIndex = 7 }, sv)
        new("UIGradient", { Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 1) }) }, white)
        local black = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), BorderSizePixel = 0, ZIndex = 8 }, sv)
        new("UIGradient", { Rotation = 90, Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0) }) }, black)
        local svs = new("UIStroke", { Thickness = 1 }, sv)
        R(svs, "str", 14)
        local ring = new("Frame", { AnchorPoint = V2(0.5, 0.5), Size = UDim2.fromOffset(14, 14), BackgroundTransparency = 1, ZIndex = 10 }, sv)
        corner(ring, 7)
        new("UIStroke", { Color = Color3.new(1, 1, 1), Thickness = 2 }, ring)
        local ring2 = new("Frame", { AnchorPoint = V2(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(10, 10), BackgroundTransparency = 1, ZIndex = 10 }, ring)
        corner(ring2, 5)
        new("UIStroke", { Color = Color3.new(0, 0, 0), Thickness = 1 }, ring2)

        local hueBar = new("Frame", { Position = UDim2.fromOffset(190, 12), Size = UDim2.fromOffset(18, 170), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, ZIndex = 7 }, pk)
        corner(hueBar, 4)
        local seq = {}
        for i = 0, 6 do table.insert(seq, ColorSequenceKeypoint.new(i / 6, Color3.fromHSV(math.min(i / 6, 0.999), 1, 1))) end
        new("UIGradient", { Rotation = 90, Color = ColorSequence.new(seq) }, hueBar)
        local hs = new("UIStroke", { Thickness = 1 }, hueBar)
        R(hs, "str", 14)
        local hk = new("Frame", { AnchorPoint = V2(0.5, 0.5), Size = UDim2.fromOffset(22, 6), BackgroundTransparency = 1, ZIndex = 9 }, hueBar)
        corner(hk, 2)
        new("UIStroke", { Color = Color3.new(1, 1, 1), Thickness = 1 }, hk)

