                for m = 0, 1 do
                    if (k + m) % 2 == 0 then new("Frame", { Position = UDim2.fromOffset(k * 8, m * 8), Size = UDim2.fromOffset(8, 8), BackgroundColor3 = Color3.fromRGB(100, 100, 100), BorderSizePixel = 0, ZIndex = 7 }, aBar) end
