        end
        local aFill = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, ZIndex = 8 }, aBar)
        local aGrad = new("UIGradient", {}, aFill)
        local as = new("UIStroke", { Thickness = 1 }, aBar)
        R(as, "str", 14)
        local ak = new("Frame", { AnchorPoint = V2(0.5, 0.5), Size = UDim2.fromOffset(6, 20), BackgroundTransparency = 1, ZIndex = 9 }, aBar)
        corner(ak, 2)
        new("UIStroke", { Color = Color3.new(1, 1, 1), Thickness = 1 }, ak)

        local sw = new("Frame", { Position = UDim2.fromOffset(12, 218), Size = UDim2.fromOffset(28, 28), BackgroundColor3 = Color3.fromRGB(100, 100, 100), BorderSizePixel = 0, ZIndex = 7, ClipsDescendants = true }, pk)
        corner(sw, 4)
        local swFill = new("Frame", { Size = UDim2.fromScale(1, 1), BorderSizePixel = 0, ZIndex = 8 }, sw)
        local sws = new("UIStroke", { Thickness = 1 }, sw)
        R(sws, "str", 14)
        local hexBox, hexSt = rectF(pk, 48, 218, 160, 28, 4, 7, 14, { z = 7 })
        local hexT = new("TextBox", { Position = UDim2.fromOffset(8, 0), Size = UDim2.new(1, -16, 1, 0), BackgroundTransparency = 1, Text = "", FontFace = F_REG, TextSize = 14, TextXAlignment = Enum.TextXAlignment.Left, ClearTextOnFocus = false, ZIndex = 9 }, hexBox)
        R(hexT, "txt", 12)

        local function curColor() return Color3.fromHSV(hue / 360, sat, val) end
        local function hex() local c = curColor(); local s = string.format("#%02X%02X%02X", math.floor(c.R * 255 + .5), math.floor(c.G * 255 + .5), math.floor(c.B * 255 + .5)); if alpha < 0.999 then s = s .. string.format("%02X", math.floor(alpha * 255 + .5)) end return s end
        local function apply(fromUser)
            local c = curColor()
            sv.BackgroundColor3 = Color3.fromHSV(hue / 360, 1, 1)
            ring.Position = UDim2.fromScale(sat, 1 - val)
            hk.Position = UDim2.fromScale(0.5, hue / 360)
            ak.Position = UDim2.fromScale(alpha, 0.5)
