        local listening, hot = false, false
        local rkt = B(kt, "txt", function() return TH.col(listening and 9 or 12) end)
        local rks = B(kst, "str", function() local c1, a1 = TH.col(14); local c2b, a2 = TH.col(listening and 16 or 15); return mixc(c1, a1, c2b, a2, (listening or hot) and 1 or 0) end)
