            listening = true
            kt.Text = "Press a key"
            rkt()
            rks()
            listen(function(name) listening = false; Hub.menuKey = name or Hub.menuKey; kt.Text = pretty(Hub.menuKey); rkt(); rks(); dirty() end)
        end)
