        local function localFiles()
            local out = {}
            local ok, files = pcall(listfiles, CFG)
            if ok then
                for _, p in ipairs(files) do
                    local n = p:match("([^/\\]+)%.json$")
                    if n then
                        local okd, data = pcall(function() return HttpService:JSONDecode(readfile(CFG .. "/" .. n .. ".json")) end)
                        local meta = okd and type(data) == "table" and data.meta or {}
                        table.insert(out, { name = n, desc = meta.desc or "Saved setup", date = meta.date or "", tags = meta.tags or {}, by = "You" })
                    end
                end
            end
            table.sort(out, function(a, b) return a.name < b.name end)
            return out
        end

