            if tab == "public" then
                for i, p in ipairs(PRESETS) do
                    cfgCard(p, "Apply", "Save copy", function()
                        local data = { modules = {} }
                        for n, d in pairs(p.mods) do data.modules[n] = { enabled = d.enabled, settings = d.settings, bind = Hub.modules[n] and Hub.modules[n].bind } end

                        local q = Hub.quiet
                        Hub.quiet = true
                        for _, m in ipairs(Hub.order) do
                            if m.enabled and not p.mods[m.name] and not m.hidden and m.name ~= "Self Destruct" then Hub.setEnabled(m, false) end
                        end
                        Hub.quiet = q
                        Hub.applyConfig(data)
                        dirty()
                        notify("Applied " .. p.name)
                    end, function()
                        local data = { meta = { desc = p.desc, date = os.date("%Y-%m-%d"), tags = p.tags }, modules = p.mods }
                        pcall(function() writefile(CFG .. "/" .. p.name .. ".json", HttpService:JSONEncode(data)) end)
                        notify("Saved " .. p.name)
                    end, i)
                end
            elseif tab == "personal" then
                for i, info in ipairs(localFiles()) do
                    cfgCard(info, "Load", "Delete", function()
                        local ok, data = pcall(function() return HttpService:JSONDecode(readfile(CFG .. "/" .. info.name .. ".json")) end)
                        if ok then Hub.applyConfig(data); dirty(); notify("Loaded " .. info.name) else notify("Config not found") end
                    end, function()
                        pcall(function() delfile(CFG .. "/" .. info.name .. ".json") end)
                        notify("Deleted " .. info.name)
                        refresh()
                    end, i)
                end
            end
        end
        for i, n in ipairs(names) do
            local b = button(f, n[2], 260 + (i - 1) * 160, 100, 150, 35, { r = 6, size = 17, z = 5 })
            b.btn.MouseButton1Click:Connect(function() tab = n[1]; refresh() end)
            tabs[i] = { id = n[1], api = b }
        end

        do
            local card = glassCard(createFrame, 0, 0, 560, 330, 5)
            T_(card, "Create a new config", { x = 20, y = 18, w = 400, h = 24, size = 20, font = F_SEMI, slot = 12, z = 6 })
            T_(card, "Snapshots your current settings and saves them as a config.", { x = 20, y = 46, w = 500, h = 18, size = 14, slot = 13, z = 6 })
            local function field(label, y, max, placeholder, h)
                T_(card, label, { x = 20, y = y, w = 300, h = 20, size = 17, slot = 12, z = 6 })
                local cnt = T_(card, "0/" .. max, { pos = UDim2.new(1, -20, 0, y), anchor = V2(1, 0), w = 80, h = 20, size = 13, slot = 30, ax = Enum.TextXAlignment.Right, z = 6 })
                local b, st = rectF(card, 20, y + 26, 520, h or 30, 4, 7, 14, { z = 6 })
                local tb = new("TextBox", { Position = UDim2.fromOffset(10, 0), Size = UDim2.new(1, -20, 1, 0), BackgroundTransparency = 1, Text = "", PlaceholderText = placeholder, FontFace = F_REG, TextSize = 14, TextXAlignment = Enum.TextXAlignment.Left, ClearTextOnFocus = false, ZIndex = 8 }, b)
                R(tb, "txt", 12)
                tb.PlaceholderColor3 = Color3.fromRGB(110, 110, 130)
                tb:GetPropertyChangedSignal("Text"):Connect(function()
                    if #tb.Text > max then tb.Text = tb.Text:sub(1, max) end
                    cnt.Text = #tb.Text .. "/" .. max
                end)
                tb.Focused:Connect(function() tween(st, { Color = (TH.col(9)) }, 0.12) end)
                tb.FocusLost:Connect(function() R(st, "str", 14) end)
                return tb
            end
            local nameT = field("Config name", 80, 20, "e.g. Crystal PvP config")
            local descT = field("Description", 150, 50, "What the config does")
            local go = button(card, "Create config", 20, 250, 520, 40, { primary = true, z = 6, size = 17 })
            go.btn.MouseButton1Click:Connect(function()
                local n = nameT.Text:gsub("[^%w_%- ]", "")
                if #n < 3 then return notify("Name needs 3-20 characters") end
                local data = Hub.collect()
                data.meta = { desc = descT.Text, date = os.date("%Y-%m-%d"), tags = {} }
                local ok = pcall(function() writefile(CFG .. "/" .. n .. ".json", HttpService:JSONEncode(data)) end)
                notify(ok and ("Saved " .. n) or "Save failed")
                if ok then nameT.Text = ""; descT.Text = ""; tab = "personal"; refresh() end
            end)

            local pv = glassCard(createFrame, 580, 0, 230, 150, 5)
            T_(pv, "Tip", { x = 16, y = 14, w = 190, h = 20, size = 17, slot = 12, z = 6 })
            T_(pv, "Configs store every module's state, settings and keybinds. Load them any time from Personal configs.", { x = 16, y = 40, w = 198, h = 96, size = 14, slot = 13, wrap = true, ay = Enum.TextYAlignment.Top, z = 6 })
        end
        page.onShow = refresh
        refresh()
    end
end

do
    local TH, B, R, T_, mixc, rectF, hit, ic = UI.TH, UI.B, UI.R, UI.T, UI.mixc, UI.rectF, UI.hit, UI.ic
    local V2 = Vector2.new
    local RSMC = game:GetService("ReplicatedStorage"):FindFirstChild("MC")
    local ok0, Store = pcall(require, RSMC.Store)
    local ok1, Skins = pcall(require, RSMC.Skins)
    local ok2, WSk = pcall(require, RSMC.WeaponSkins)
    local ok3, Emotes = pcall(require, RSMC.Emotes)

    Hub.cos = { kill = "None", skin = "Default", emote = "wave", w = {}, auto = true, botHits = false }
    local cos = Hub.cos

    local function pretty2(id) return (tostring(id):gsub("_", " "):gsub("(%a)([%w]*)", function(a, b) return a:upper() .. b end)) end
    local KILL, SKIN, EMOTE, WSETS = { "None" }, { "Default" }, {}, { "None" }
    local WTYPES = ok2 and WSk.TYPES or { "sword", "axe", "spear", "mace", "armor", "elytra" }
    if ok0 and Store.EFFECTS then
        local ids = {}
        for k, v in pairs(Store.EFFECTS) do ids[#ids + 1] = type(v) == "table" and (v.id or v.key or k) or v end
        table.sort(ids)
        for _, id in ipairs(ids) do KILL[#KILL + 1] = pretty2(id) end
    end
    local function killId(label) return label ~= "None" and label:lower():gsub(" ", "_") or nil end
    if ok1 then
        local n = {}
        for k in pairs(Skins) do if type(Skins[k]) == "table" and Skins[k].tex then n[#n + 1] = k end end
        table.sort(n, function(a, b) return a:lower() < b:lower() end)
        for _, k in ipairs(n) do SKIN[#SKIN + 1] = k end
    end
    if ok3 then for _, e in ipairs(Emotes.LIST) do EMOTE[#EMOTE + 1] = type(e) == "table" and (e.id or e.name) or e end end
    if ok2 then for _, st in ipairs(WSk.SETS) do WSETS[#WSETS + 1] = pretty2(st.id or st.name or st) end end

    local lastPos, lastHp = {}, {}
    local acc = 0
    connect(RS.Heartbeat, function(dt)
        acc += dt
        if acc < 0.1 then return end
        acc = 0
        if cos.kill == "None" or not (gameOk and Core.alive()) then return end
        pcall(function()
            for _, t in ipairs(Core.targets(false)) do
                local p = t.feet * Config.BLOCK
                lastPos[t.name] = p
                lastPos[t.model.Name] = p
                lastHp[t.id] = t.model:GetAttribute("Health") or t.health
            end
        end)
    end)
    local function playKill(label, pos)
        local id = killId(label)
        if not (id and pos and MCFolder) then return end
        asGame(function() require(MCFolder.KillEffects).play(id, pos, nil, nil) end)
    end
    local lastFire = {}
    local function fire(t)
        if os.clock() - (lastFire[t.id] or 0) < 1.2 then return end
        lastFire[t.id] = os.clock()
        playKill(cos.kill, t.feet * Config.BLOCK)
    end

    addNetHandler("hurt", function(p)
        if not (Hub.alive and cos.auto and cos.kill ~= "None") then return end
        if p.attacker ~= myEntityId() or (p.amount or 0) < 0.05 then return end
        local id, before = p.id, lastHp[p.id]
        for _, t in ipairs(Core.targets(false)) do
            if t.id == id then
                if (t.plr == nil and cos.botHits) or (before and before - p.amount <= 0.05) then return fire(t) end
                task.delay(0.12, function()
                    for _, t2 in ipairs(Core.targets(false)) do
                        if t2.id == id and (t2.model:GetAttribute("Health") or t2.health) <= 0.05 then fire(t2) end
                    end
                end)
                return
            end
        end
    end)
    addNetHandler("killed", function(p)
        if not (Hub.alive and cos.auto and cos.kill ~= "None") then return end
        local pos = lastPos[tostring(p.victim)]
        if not pos and Hub.lastTarget and Hub.lastTarget.feet then pos = Hub.lastTarget.feet * Config.BLOCK end
        if pos then playKill(cos.kill, pos) end
    end)

    local orig = setmetatable({}, { __mode = "k" })
    local function ws()
        local t = {}
        for _, ty in ipairs(WTYPES) do local v = cos.w[ty]; if v and v ~= "None" then t[ty] = killId(v) end end
        return t
    end
    local function applyChar()
        local char = LP.Character
        if not char then return end
        local o = orig[char]
        if not o then o = {}; orig[char] = o end

        local want = ws()
        if next(want) then
            local json = HttpService:JSONEncode(want)
            if o.ws == nil then o.ws = char:GetAttribute("WSkins") or false end
            if char:GetAttribute("WSkins") ~= json then char:SetAttribute("WSkins", json) end
        elseif o.ws ~= nil then
            char:SetAttribute("WSkins", o.ws or nil)
            o.ws = nil
        end
    end

    local texName = {}
    if ok1 then for k, v in pairs(Skins) do if type(v) == "table" and v.tex then texName[v.tex] = k end end end
    local swapped = setmetatable({}, { __mode = "k" })
    local origTex
    local function applySkin()
        local char = LP.Character
        if not (ok1 and char) then return end
        if not origTex then
            local nm = char:GetAttribute("Skin")
            origTex = nm and Skins[nm] and Skins[nm].tex or Skins.STEVE.tex
        end
        local want = cos.skin ~= "Default" and Skins[cos.skin] and Skins[cos.skin].tex or nil
        local function fix(sa)
            if not sa:IsA("SurfaceAppearance") then return end
            local cm = sa.ColorMap
            if want then
                if texName[cm] and cm ~= want then sa.ColorMap = want; swapped[sa] = true end
            elseif swapped[sa] then
                sa.ColorMap = origTex
                swapped[sa] = nil
            end
        end
        for _, root in ipairs({ char, LP:FindFirstChildOfClass("PlayerGui"), workspace.CurrentCamera }) do
            if root then for _, d in ipairs(root:GetDescendants()) do fix(d) end end
        end
    end
    local acc2 = 0
    connect(RS.Heartbeat, function(dt)
        acc2 += dt
        if acc2 < 0.5 or not Hub.alive then return end
        acc2 = 0
        pcall(applyChar)
        pcall(applySkin)
    end)
    function Hub.cosApply() pcall(applyChar); pcall(applySkin) end

    local page = UI.gen["Cosmetics"]
    local f = page.frame
    T_(f, "Cosmetics", { x = 260, y = 26, w = 600, h = 44, size = 34, font = F_SEMI, slot = 12 })
    T_(f, "Visual only. Just you see these, nobody else in the server.", { x = 260, y = 70, w = 700, h = 22, size = 17, slot = 13 })

    local dropdowns = {}
    local function glass(x, y, w, h) return rectF(f, x, y, w, h, 12, 23, 15, { z = 4, fmul = 1.4 }) end
    local function title(card, text, sub)
        T_(card, text, { x = 20, y = 16, w = 340, h = 24, size = 19, font = F_SEMI, slot = 12, z = 6 })
        if sub then T_(card, sub, { x = 20, y = 42, w = 350, h = 34, size = 14, slot = 30, wrap = true, ay = Enum.TextYAlignment.Top, z = 6 }) end
    end

    local function dropdown(parent, x, y, w, options, get, set, o)
        o = o or {}
        local b, st = rectF(parent, x, y, w, 30, 5, 7, 14, { z = 6, pos = o.pos, anchor = o.anchor })
        local lab = T_(b, "", { pos = UDim2.fromOffset(10, 0), sz = UDim2.new(1, -36, 1, 0), size = 15, slot = 12, trunc = true, z = 7 })
        local chev = new("ImageLabel", { BackgroundTransparency = 1, Image = icon("chevron-down"), Size = UDim2.fromOffset(12, 12), AnchorPoint = V2(0.5, 0.5), Position = UDim2.new(1, -16, 0.5, 0), ZIndex = 7 }, b)
        local hot = false
        local rc = B(chev, "img", function() return TH.col(hot and 9 or 13) end)
        local rs = B(st, "str", function() local c1, a1 = TH.col(14); local c2, a2 = TH.col(9); return mixc(c1, a1, c2, a2, hot and 1 or 0) end)
        local function render() lab.Text = tostring(get()) end
        local btn = hit(b, 8)
        btn.MouseEnter:Connect(function() hot = true; rc(); rs() end)
        btn.MouseLeave:Connect(function() hot = false; rc(); rs() end)
        btn.MouseButton1Click:Connect(function() UI.openDropdown(b, options, get(), function(v) set(v); render(); dirty() end) end)
        table.insert(dropdowns, render)
        render()
        return b
    end

    local c1 = glass(260, 108, 396, 150)
    title(c1, "Kill Effect", "Plays on every kill you get. Pick one from the shop list for free.")
    dropdown(c1, 20, 92, 230, KILL, function() return cos.kill end, function(v) cos.kill = v end)
    local prev = UI.button(c1, "Preview", 262, 92, 114, 30, { z = 6, size = 15, primary = true, onClick = function()
        local cam = workspace.CurrentCamera
        local pos = cam.CFrame.Position + cam.CFrame.LookVector * 14 - Vector3.new(0, 3, 0)
        if cos.kill == "None" then notify("Pick a kill effect first") else playKill(cos.kill, pos) end
    end })

    local c2 = glass(260, 276, 396, 150)
    title(c2, "Emote", "Plays an emote on you. Moving cancels it, like normal.")
    local emoteLabels = {}
    for _, e in ipairs(EMOTE) do emoteLabels[#emoteLabels + 1] = pretty2(e) end
    local function emoteId(label) return label:lower():gsub(" ", "_") end
    dropdown(c2, 20, 92, 230, emoteLabels, function() return pretty2(cos.emote) end, function(v) cos.emote = emoteId(v) end)
    UI.button(c2, "Play", 262, 92, 114, 30, { z = 6, size = 15, primary = true, onClick = function()
        local char = LP.Character
        if not char then return notify("Spawn in first") end
        char:SetAttribute("Emote", cos.emote)
        char:SetAttribute("EmoteAt", workspace:GetServerTimeNow())
    end })

    local c3 = glass(674, 108, 396, 150)
    title(c3, "Skin", "Wear any shop character skin on yourself.")
    dropdown(c3, 20, 92, 356, SKIN, function() return cos.skin end, function(v) cos.skin = v; Hub.cosApply() end)

    local ROWH = 46
    local c4 = glass(674, 276, 396, 78 + #WTYPES * ROWH)
    title(c4, "Weapon Skins", "Pick a skin set for each kind of gear.")
    for i, ty in ipairs(WTYPES) do
        local y = 80 + (i - 1) * ROWH
        T_(c4, ok2 and WSk.TYPE_NAMES[ty] or pretty2(ty), { x = 20, y = y, w = 120, h = 30, size = 17, slot = 12, z = 6 })
        dropdown(c4, 150, y, 226, WSETS, function() return cos.w[ty] or "None" end, function(v) cos.w[ty] = v; Hub.cosApply() end)
    end
    local autoRow = glass(260, 444, 396, 62)
    T_(autoRow, "Auto-play kill effect", { x = 20, y = 0, w = 250, h = 62, size = 17, slot = 12, z = 6 })
    local sw
    sw = UI.pillSwitch(autoRow, UDim2.new(1, -20, 0.5, 0), V2(1, 0.5), 24, function() return cos.auto end, function() cos.auto = not cos.auto; sw.refresh(); dirty() end, 7)

    local botRow = glass(260, 518, 396, 62)
    T_(botRow, "Also on every bot hit", { x = 20, y = 0, w = 250, h = 62, size = 17, slot = 12, z = 6 })
    local sw2
    sw2 = UI.pillSwitch(botRow, UDim2.new(1, -20, 0.5, 0), V2(1, 0.5), 24, function() return cos.botHits end, function() cos.botHits = not cos.botHits; sw2.refresh(); dirty() end, 7)

    function Hub.cosRefresh() for _, r in ipairs(dropdowns) do r() end; sw.refresh(); sw2.refresh(); Hub.cosApply() end
end

local closing = 0
local backdrop = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.fromRGB(4, 3, 10), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 0, Active = false }, gui)
new("UIGradient", { Rotation = 90, Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.35), NumberSequenceKeypoint.new(1, 0.75) }) }, backdrop)
local blurFx = new("BlurEffect", { Name = HttpService:GenerateGUID(false), Size = 0 }, game:GetService("Lighting"))
local function setMenu(open)
    Hub.open = open
    tween(backdrop, { BackgroundTransparency = open and 0 or 1 }, 0.3)
    tween(blurFx, { Size = open and 9 or 0 }, 0.3)
    if gameOk then Input.mouseFree = open end
    pcall(function() RS:UnbindFromRenderStep("PrestigeMouse") end)
    closing += 1
    local token = closing
    if open then
        RS:BindToRenderStep("PrestigeMouse", Enum.RenderPriority.Last.Value + 1, function()
            UIS.MouseBehavior = Enum.MouseBehavior.Default
            UIS.MouseIconEnabled = true
        end)
        gui.Enabled = true
        UI.window.GroupTransparency = 1
        UI.window.Position = UI.winPos(18)
        tween(UI.window, { GroupTransparency = 0, Position = UI.winPos(0) }, 0.34)
    else
        listening = nil
        if UI.closeDropdown then UI.closeDropdown() end
        tween(UI.window, { GroupTransparency = 1, Position = UI.winPos(12) }, 0.2)
        task.delay(0.24, function()
            if token == closing then gui.Enabled = false end
        end)
    end
end

Hub.setMenu = setMenu

do
    local edit = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Visible = false, ZIndex = 80 }, gui)
    local shade = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.62, BorderSizePixel = 0, ZIndex = 80 }, edit)
    local bar = new("Frame", { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 56), Size = UDim2.fromOffset(420, 46), BackgroundColor3 = Color3.fromRGB(14, 14, 18), BackgroundTransparency = 0.12, BorderSizePixel = 0, ZIndex = 90 }, edit)
    corner(bar, 12)
    new("TextLabel", { Position = UDim2.fromOffset(16, 0), Size = UDim2.fromOffset(220, 46), BackgroundTransparency = 1, Text = "HUD editor  \xC2\xB7  drag to move", FontFace = F_SEMI, TextSize = 14, TextColor3 = Color3.fromRGB(235, 235, 245), TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 91 }, bar)
    local function mkBtn(text, x, w, primary)
        local b = new("TextButton", { Position = UDim2.fromOffset(x, 9), Size = UDim2.fromOffset(w, 28), BackgroundColor3 = primary and T.accent or Color3.fromRGB(34, 34, 44), BorderSizePixel = 0, Text = text, FontFace = F_SEMI, TextSize = 13, TextColor3 = Color3.new(1, 1, 1), AutoButtonColor = false, ZIndex = 91 }, bar)
        corner(b, 8)
        b.MouseEnter:Connect(function() tween(b, { BackgroundTransparency = 0.2 }, 0.1) end)
        b.MouseLeave:Connect(function() tween(b, { BackgroundTransparency = 0 }, 0.12) end)
        return b
    end
    local resetB, doneB = mkBtn("Reset", 250, 76, false), mkBtn("Done", 334, 76, true)

    local items = {
        { key = "hud", name = "Watermark & stats", mod = "Hud", frame = function(m) return m.rt.top end, size = Vector2.new(230, 70),
          base = function(m, vp, sz) return m.settings.position == "Top Center" and Vector2.new(vp.X / 2 - sz.X / 2, 10) or Vector2.new(168, 10) end },
        { key = "list", name = "Module list", mod = "Hud", frame = function(m) return m.rt.list end, size = Vector2.new(170, 120),
          base = function(m, vp, sz) return Vector2.new(vp.X - 10 - sz.X, 88) end },
        { key = "target", name = "Target HUD", mod = "Target HUD", frame = function(m) return m.rt.root end, size = Vector2.new(165, 52),
          base = function(m, vp, sz) return Vector2.new(vp.X / 2 - sz.X / 2, vp.Y / 2 + 96) end },
        { key = "cooldown", name = "Cooldown bar", mod = "Cooldown Indicator", frame = function(m) return m.rt.root end, size = Vector2.new(110, 22),
          base = function(m, vp, sz) return Vector2.new(vp.X / 2 - sz.X / 2, vp.Y / 2 + m.settings.offset - 8) end },
        { key = "notify", name = "Notifications", mod = "Notifications", frame = function(m) return m.rt.stack end, size = Vector2.new(240, 60),
          base = function(m, vp, sz) return Vector2.new(vp.X - 16 - sz.X, vp.Y - 90 - sz.Y) end },
    }
    local handles = {}
    local function rectOf(it, m)
        local vp = workspace.CurrentCamera.ViewportSize
        local f = it.frame(m)
        local sz = it.size
        if f and f.Visible and f.AbsoluteSize.X > 8 and f.AbsoluteSize.Y > 4 then sz = f.AbsoluteSize end
        if sz.X < it.size.X * 0.6 then sz = Vector2.new(math.max(sz.X, it.size.X), math.max(sz.Y, it.size.Y)) end
        local o = Hub.hudPos[it.key]
        local pos = it.base(m, vp, sz) + (o and Vector2.new(o[1], o[2]) or Vector2.zero)
        return pos, sz
    end
    local function build()
        for _, h in pairs(handles) do h.frame:Destroy() end
        handles = {}
        for _, it in ipairs(items) do
            local m = Hub.modules[it.mod]
            if m and m.enabled then
                local f = new("Frame", { BackgroundColor3 = T.accent, BackgroundTransparency = 0.88, BorderSizePixel = 0, ZIndex = 85 }, edit)
                corner(f, 8)
                local st = new("UIStroke", { Color = T.accent, Thickness = 1.5, Transparency = 0.25 }, f)
                local lab = new("TextLabel", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = it.name, FontFace = F_SEMI, TextSize = 12, TextColor3 = Color3.new(1, 1, 1), TextTransparency = 0.1, ZIndex = 86 }, f)
                local btn = new("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, ZIndex = 88 }, f)
                local h = { frame = f, it = it, m = m }
                handles[it.key] = h
                btn.MouseEnter:Connect(function() tween(f, { BackgroundTransparency = 0.78 }, 0.1) end)
                btn.MouseLeave:Connect(function() tween(f, { BackgroundTransparency = 0.88 }, 0.12) end)
                btn.InputBegan:Connect(function(i)
                    if i.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
                    local start = UIS:GetMouseLocation()
                    local o = Hub.hudPos[it.key] or { 0, 0 }
                    local o0 = { o[1], o[2] }
                    UI.setDrag(function()
                        local d = UIS:GetMouseLocation() - start
                        Hub.hudPos[it.key] = { o0[1] + d.X, o0[2] + d.Y }
                    end)
                end)
            end
        end
    end
    local conn
    local function place()
        for _, h in pairs(handles) do
            local pos, sz = rectOf(h.it, h.m)
            h.frame.Position = UDim2.fromOffset(pos.X - 4, pos.Y - 4)
            h.frame.Size = UDim2.fromOffset(sz.X + 8, sz.Y + 8)
        end
    end
    function Hub.hudEdit(on)
        if on == (edit.Visible) then return end
        Hub.editing = on
        if on then
            if not Hub.open then Hub.setMenu(true) end
            tween(UI.win, { GroupTransparency = 1 }, 0.18)
            task.delay(0.2, function() if edit.Visible then UI.win.Visible = false end end)
            tween(backdrop, { BackgroundTransparency = 1 }, 0.2)
            tween(blurFx, { Size = 0 }, 0.2)
            build()
            edit.Visible = true
            conn = RS.RenderStepped:Connect(place)
            place()
        else
            if conn then conn:Disconnect(); conn = nil end
            edit.Visible = false
            for _, h in pairs(handles) do h.frame:Destroy() end
            handles = {}
            UI.win.Visible = true
            tween(UI.win, { GroupTransparency = 0 }, 0.22)
            tween(backdrop, { BackgroundTransparency = 0 }, 0.2)
            tween(blurFx, { Size = 9 }, 0.2)
            dirty()
        end
    end
    doneB.MouseButton1Click:Connect(function() Hub.hudEdit(false) end)
    resetB.MouseButton1Click:Connect(function() Hub.hudPos = {}; dirty() end)
    connect(UIS.InputBegan, function(i)
        if edit.Visible and i.KeyCode == Enum.KeyCode.Escape then Hub.hudEdit(false) end
    end)
end
connect(UIS.InputBegan, function(input)
    if listening then
        local name = keyName(input)
        if name then
            local cb = listening
            listening = nil
            cb((name == "Escape" or name == "Backspace") and nil or name)
        end
        return
    end
    local name = keyName(input)
    if not name or UIS:GetFocusedTextBox() then return end
    if name == "Escape" and Hub.open and not Hub.editing then
        if UI.catcher then UI.closeDropdown(); return end
        local ap = UI.active
        if ap and ap.openMod then ap.closeDetail(); return end
        return setMenu(false)
    end
    if name == Hub.menuKey then return setMenu(not Hub.open) end
    if not gameOk then return end
    for _, m in ipairs(Hub.order) do
        if m.enabled and m.bind == name and m.def.onBind and not Hub.open then
            local ok, err = pcall(m.def.onBind, m)
            if not ok then warn("[Prestige] " .. m.name .. " bind: " .. tostring(err)) end
        end
    end
end)

function Hub.Unload()
    Hub.alive = false
    for _, c in ipairs(Hub.conns) do pcall(function() c:Disconnect() end) end
    pcall(function() RS:UnbindFromRenderStep("PrestigeMouse") end)
    for _, m in ipairs(Hub.order) do
        if m.enabled and m.def.onToggle and not m.def.noSave then pcall(m.def.onToggle, m, false) end
    end
    pcall(Core.unaim)
    if gameOk then
        for _, fn in ipairs({ tickFn, postFn }) do
            local i = table.find(Controller.beforeTick, fn)
            if i then table.remove(Controller.beforeTick, i) end
        end
        if pressTable then
            for _, fn in ipairs({ silentPre, silentPost, wtapPost }) do
                local i = table.find(pressTable, fn)
                if i then table.remove(pressTable, i) end
            end
        end
        Input.mouseFree = false
    end
    pcall(function() gui:Destroy() end)
    pcall(function() hud:Destroy() end)
    pcall(function() world:Destroy() end)
    pcall(function() blurFx:Destroy() end)
    getgenv().PrestigeClient = nil
    getgenv().LungeHub = nil
end

Hub.alive = true
do local ok, err = xpcall(UI.go, debug.traceback, UI.cat["Combat"]); if not ok then warn("[Prestige] go: " .. tostring(err)) end end
do local ok, err = xpcall(setEnabled, debug.traceback, Hub.modules["Hud"], true); if not ok then warn("[Prestige] hud: " .. tostring(err)) end end
pcall(function()
    if isfile(AUTOSAVE) then applyConfig(HttpService:JSONDecode(readfile(AUTOSAVE))) end
end)
Hub.quiet = false
notify("Prestige Client " .. Hub.version .. " - " .. pretty(Hub.menuKey) .. " toggles the menu")
setMenu(true)
